window.READER_DATA={"sections":[{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Boy Jesus: At Twelve, Visits Jerusalem — Tarries behind — Talks in Temple with the Doctors — Speaks to his Mother his First Recorded Words.","source":"Luke 2, 40-52.","items":[{"number":1,"reference":"","text":"How is it that ye sought me? wist ye not that I must be about my Father's business?","id":"saying-1","section_index":0,"contexts":[{"book":"Luke","chapter":2,"verse":49,"matched":true}]}],"notes":[],"era":0},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Jesus At Thirty — Baptized By John.","source":"Matthew 3, 1-6; 13-17: Mark 1, 10-11; Luke 3, 22-23.","items":[{"number":2,"reference":"","text":"Suffer it to be so now: for thus it becometh us to fulfill all righteousness.","id":"saying-2","section_index":1,"contexts":[{"book":"Matthew","chapter":3,"verse":1,"matched":false},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Luke","chapter":3,"verse":1,"matched":false}]}],"notes":[],"era":0},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Christ's Long Fast in the Wilderness — Satan's Futile Wiles.","source":"Matthew 4, 1-11: Mark 1, 13: Luke 4, 1-13.","items":[{"number":3,"reference":"","text":"It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of God.","id":"saying-3","section_index":2,"contexts":[{"book":"Matthew","chapter":4,"verse":4,"matched":true},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Luke","chapter":4,"verse":1,"matched":false}]},{"number":4,"reference":"","text":"It is written again, Thou shalt not tempt the Lord thy God.","id":"saying-4","section_index":2,"contexts":[{"book":"Matthew","chapter":4,"verse":7,"matched":true},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Luke","chapter":4,"verse":1,"matched":false}]},{"number":5,"reference":"","text":"Get thee behind me, Satan; get thee hence: for it is written, Thou shalt worship the Lord thy God, and him only shalt thou serve.","id":"saying-5","section_index":2,"contexts":[{"book":"Matthew","chapter":4,"verse":1,"matched":false},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Luke","chapter":4,"verse":1,"matched":false}]}],"notes":[],"era":0},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"John Answers the Priests — \"Behold the Lamb of God\" — Jesus Hails Andrew, Simon, Philip and Nathanael.","source":"John 1, 19-20 . . . 22-29 . . . 37-51.","items":[{"number":6,"reference":"","text":"What seek ye?","id":"saying-6","section_index":3,"contexts":[{"book":"John","chapter":1,"verse":38,"matched":true}]},{"number":7,"reference":"","text":"Come and see.","id":"saying-7","section_index":3,"contexts":[{"book":"John","chapter":1,"verse":39,"matched":true}]},{"number":8,"reference":"","text":"Thou art Simon the son of Jona: thou shalt be called Cephas.","id":"saying-8","section_index":3,"contexts":[{"book":"John","chapter":1,"verse":42,"matched":true}]},{"number":9,"reference":"","text":"Follow me.","id":"saying-9","section_index":3,"contexts":[{"book":"John","chapter":1,"verse":1,"matched":false}]},{"number":10,"reference":"","text":"Behold an Israelite indeed, in whom is no guile!","id":"saying-10","section_index":3,"contexts":[{"book":"John","chapter":1,"verse":47,"matched":true}]},{"number":11,"reference":"","text":"Before that Philip called thee, when thou wart under the fig tree, I saw thee.","id":"saying-11","section_index":3,"contexts":[{"book":"John","chapter":1,"verse":1,"matched":false}]},{"number":12,"reference":"","text":"Because I said unto thee, I saw thee under the fig tree, believest thou? thou shalt see greater things than these. Verily, verily, I say unto you, Hereafter ye shall see heaven open, and the angels of God ascending and descending upon the Son of man.","id":"saying-12","section_index":3,"contexts":[{"book":"John","chapter":1,"verse":1,"matched":false}]}],"notes":[],"era":1},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Jesus’ Mother and the Water Changed to Wine — He Drives the Moneymakers from the Temple — Temple of the Body.","source":"John 2, 1-9; 12-16; 18-21.","items":[{"number":13,"reference":"","text":"Woman, what have I to do with thee? mine hour is not yet come.","id":"saying-13","section_index":4,"contexts":[{"book":"John","chapter":2,"verse":4,"matched":true}]},{"number":14,"reference":"","text":"Draw out now, and bear unto the governor of the feast.","id":"saying-14","section_index":4,"contexts":[{"book":"John","chapter":2,"verse":8,"matched":true}]},{"number":15,"reference":"","text":"Take these things hence, make not my Father's house a house of merchandise.","id":"saying-15","section_index":4,"contexts":[{"book":"John","chapter":2,"verse":1,"matched":false}]},{"number":16,"reference":"","text":"Destroy this temple, and in three days I will raise it up.","id":"saying-16","section_index":4,"contexts":[{"book":"John","chapter":2,"verse":19,"matched":true}]}],"notes":[],"era":1},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Night time Visit of Nicodemus — Christ Enlightens Him.","source":"John 3, 1-21.","items":[{"number":17,"reference":"","text":"Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God.","id":"saying-17","section_index":5,"contexts":[{"book":"John","chapter":3,"verse":3,"matched":true}]},{"number":18,"reference":"","text":"Verily, verily, I say unto thee, Except a man be born of water and of the Spirit, he cannot enter into the kingdom of God. That which is born of the flesh is flesh: and that which is born of the Spirit is spirit. Marvel not that I said unto thee, Ye must be born again. The wind bloweth where it listeth, and thou hearest the sound thereof, but canst not tell whence it cometh, and whither it goeth: so is every one that is born of the Spirit.","id":"saying-18","section_index":5,"contexts":[{"book":"John","chapter":3,"verse":6,"matched":true}]},{"number":19,"reference":"","text":"Art thou a master of Israel, and knowest not these things? Verily, verily, I say unto thee, We speak that we do know, and testify that we have seen; and ye receive not our witness. If I have told you earthly things, and ye believe not, how shall ye believe, if I tell you of heavenly things? And no man hath ascended up to heaven, but he that came down from heaven, even the Son of man which is in heaven. And as Moses lifted up the serpent in the wilderness, even so must the Son of man be lifted up: that whosoever believeth in him should not perish, but have eternal life. For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life. For God sent not his Son into the world to condemn the world; but that the world through him might be saved. He that believeth on him is not condemned; but he that believeth not is condemned already, because he hath not believed in the name of the only begotten Son of God. And this is the condemnation, that light has come into the world, and men loved darkness rather than light, because their deeds were evil. For every one that doeth evil hateth the light, neither cometh to the light, lest his deeds should be reproved. But he that doeth truth cometh to the light, that his deeds may be made manifest, that they are wrought in God.","id":"saying-19","section_index":5,"contexts":[{"book":"John","chapter":3,"verse":11,"matched":true}]}],"notes":[],"era":1},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"John Extols Jesus — The Woman at the Well — \"One Soweth, and Another Reapeth.\"","source":"John 3:22–36; John 4:1–42","items":[{"number":20,"reference":"","text":"Give me to drink.","id":"saying-20","section_index":6,"contexts":[{"book":"John","chapter":4,"verse":7,"matched":true},{"book":"John","chapter":3,"verse":1,"matched":false}]},{"number":21,"reference":"","text":"If thou knewest the gift of God, and who it is that saith to thee, Give me to drink; thou wouldest have asked of him, and he would have given thee living water.","id":"saying-21","section_index":6,"contexts":[{"book":"John","chapter":4,"verse":10,"matched":true},{"book":"John","chapter":3,"verse":1,"matched":false}]},{"number":22,"reference":"","text":"Whosoever drinketh of this water shall thirst again; but whosoever drinketh of the water that I shall give him shall never thirst; but the water that I shall give him shall be in him a well of water springing up into everlasting life.","id":"saying-22","section_index":6,"contexts":[{"book":"John","chapter":4,"verse":14,"matched":true},{"book":"John","chapter":3,"verse":1,"matched":false}]},{"number":23,"reference":"","text":"Go, call thy husband, and come hither.","id":"saying-23","section_index":6,"contexts":[{"book":"John","chapter":4,"verse":16,"matched":true},{"book":"John","chapter":3,"verse":1,"matched":false}]},{"number":24,"reference":"","text":"Thou hast well said, I have no husband: for thou hast had five husbands; and he whom thou now hast is not thy husband: in that saidst thou truly.","id":"saying-24","section_index":6,"contexts":[{"book":"John","chapter":4,"verse":18,"matched":true},{"book":"John","chapter":3,"verse":1,"matched":false}]},{"number":25,"reference":"","text":"Woman, believe me, the hour cometh, when ye shall neither in this mountain, nor yet at Jerusalem, worship the Father. Ye worship ye know not what: we know what we worship; for salvation is of the Jews. But the hour cometh, and now is, when the true worshippers shall worship the Father in spirit and in truth: for the Father seeketh such to worship him. God is a Spirit: and they that worship him must worship him in spirit and in truth.","id":"saying-25","section_index":6,"contexts":[{"book":"John","chapter":4,"verse":22,"matched":true},{"book":"John","chapter":3,"verse":1,"matched":false}]},{"number":26,"reference":"","text":"I that speak unto thee am he.","id":"saying-26","section_index":6,"contexts":[{"book":"John","chapter":4,"verse":26,"matched":true},{"book":"John","chapter":3,"verse":1,"matched":false}]},{"number":27,"reference":"","text":"I have meat to eat that ye know not of.","id":"saying-27","section_index":6,"contexts":[{"book":"John","chapter":4,"verse":32,"matched":true},{"book":"John","chapter":3,"verse":1,"matched":false}]},{"number":28,"reference":"","text":"My meat is to do the will of him that sent me, and to finish his work. Say not ye, There are yet four months, and then cometh harvest? Behold, I say unto you, Lift up your eyes, and look on the fields; for they are white already to harvest. And he that reapeth receiveth wages, and gathereth fruit unto life eternal: that both he that soweth and he that reapeth may rejoice together. And herein is that saying true, One soweth, and another reapeth. I sent you to reap that whereon ye bestowed no labor: other men labored, and ye are entered into their labor.","id":"saying-28","section_index":6,"contexts":[{"book":"John","chapter":4,"verse":35,"matched":true},{"book":"John","chapter":3,"verse":1,"matched":false}]}],"notes":[],"era":1},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Christ in Cana Cures Nobleman's Son at Capernaum.","source":"John 4, 43-53.","items":[{"number":29,"reference":"","text":"Except ye see signs and wonders, ye will not believe.","id":"saying-29","section_index":7,"contexts":[{"book":"John","chapter":4,"verse":48,"matched":true}]},{"number":30,"reference":"","text":"Go thy way: thy son liveth.","id":"saying-30","section_index":7,"contexts":[{"book":"John","chapter":4,"verse":50,"matched":true}]}],"notes":[],"era":1},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"At the Pool: The Impotent Man Cured — Sabbath Healing Justified — Jesus' Sonship Set Forth — \"Search the Scriptures.\"","source":"John 5, 1-47.","items":[{"number":31,"reference":"","text":"Wilt thou be made whole?","id":"saying-31","section_index":8,"contexts":[{"book":"John","chapter":5,"verse":6,"matched":true}]},{"number":32,"reference":"","text":"Rise, take up thy bed, and walk.","id":"saying-32","section_index":8,"contexts":[{"book":"John","chapter":5,"verse":8,"matched":true}]},{"number":33,"reference":"","text":"Behold, thou art made whole: sin no more, lest a worse thing come unto thee.","id":"saying-33","section_index":8,"contexts":[{"book":"John","chapter":5,"verse":14,"matched":true}]},{"number":34,"reference":"","text":"My Father worketh hitherto, and I work.","id":"saying-34","section_index":8,"contexts":[{"book":"John","chapter":5,"verse":17,"matched":true}]},{"number":35,"reference":"","text":"Verily, verily, I say unto you, The Son can do nothing of himself, but what he seeth the Father do: for what things soever he doeth, these also doeth the Son likewise. For the Father loveth the Son, and sheweth him all things that himself doeth: and he will shew him greater works than these, that ye may marvel. For as the Father raiseth up the dead, and quickeneth them; even so the Son quickeneth whom he will. For the Father judgeth no man, but hath committed all judgment unto the Son; that all men should honor the Son, even as they honor the Father. He that honoreth not the Son honoreth not the Father which hath sent him. Verily, verily, I say unto you, He that heareth my word, and believeth on him that sent me, hath everlasting life, and shall not come into condemnation; but is passed from death unto life. Verily, verily, I say unto you. The hour is coming, and now is, when the dead shall hear the voice of the Son of God: and they that hear shall live. For as the Father hath life in himself; so hath he given to the Son to have life in himself; and hath given him authority to execute judgment also because he is the Son of man. Marvel not at this: for the hour is coming, in the which all that are in the graves shall hear his voice, and shall come forth; they that have done good, unto the resurrection of life; and they that have done evil, unto the resurrection of damnation. I can of mine own self do nothing: as I hear, I judge: and my judgment is just; because I seek not mine own will, but the will of the Father which hath sent me. If I bear witness of myself, my witness is not true. There is another that beareth witness of me; and I know that the witness which he witnesseth of me is true. Ye sent unto John, and he bare witness unto the truth. But I receive not testimony from man: but these things I say, that ye might be saved. He was a burning and a shining light: and we were willing for a season to rejoice in his light. But I have greater witness than that of John: for the works which the Father hath given me to finish, the same works that I do, bear witness of me, that the Father hath sent me. And the Father himself, which hath sent me, hath borne witness of me. Ye have neither heard his voice at any time, nor seen his shape. And ye have not his word abiding in you: for whom he hath sent, him ye believe not. Search the Scriptures; for in them ye think ye have eternal life: and they are they which testify of me. And ye will not come to me, that ye might have life. I receive not honor from men. But I know you, that ye have not the love of God in you. I am come in my Father's name, and ye receive me not: if another shall come in his own name, him ye will receive. How can ye believe, which receive honor one of another, and seek not the honor that cometh from God only? Do not think that I will accuse you to the Father: there is one that accuseth you, even Moses, in whom ye trust. For had ye believed Moses, ye would have believed me: for he wrote of me. But if ye believe not his writings, how shall ye believe my words?","id":"saying-35","section_index":8,"contexts":[{"book":"John","chapter":5,"verse":20,"matched":true}]}],"notes":[],"era":1},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Christ Reads in Synagogue at Nazareth — Eludes Angry Hearers — Begins to Preach Repentance.","source":"Luke 4, 16-31; Mark 1, 15; Matthew 4, 17.","items":[{"number":36,"reference":"","text":"The Spirit of the Lord is upon me, because he hath anointed me to preach the gospel to the poor; he hath sent me to heal the brokenhearted, to preach deliverance to the captives, and recovering of sight to the blind, to set at liberty them that are bruised, to preach the acceptable year of the Lord.","id":"saying-36","section_index":9,"contexts":[{"book":"Luke","chapter":4,"verse":18,"matched":true},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Matthew","chapter":4,"verse":1,"matched":false}]},{"number":37,"reference":"","text":"This day is this Scripture fulfilled in your ears.","id":"saying-37","section_index":9,"contexts":[{"book":"Luke","chapter":4,"verse":21,"matched":true},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Matthew","chapter":4,"verse":1,"matched":false}]},{"number":38,"reference":"","text":"Ye will surely say unto me this proverb, Physician, heal thyself: whatsoever we have heard done in Capernaum, do also here in thy country.","id":"saying-38","section_index":9,"contexts":[{"book":"Luke","chapter":4,"verse":23,"matched":true},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Matthew","chapter":4,"verse":1,"matched":false}]},{"number":39,"reference":"","text":"Verily I say unto you, No prophet is accepted in his own country. But I tell you of a truth, many widows were in Israel in the days of Elias, when the heaven was shut up three years and six months, when great famine was throughout all the land; but unto none of them was Elias sent, save unto Sarepta, a city of Sidom, unto a woman that was a widow. And many lepers were in Israel in the time of Eliseus the prophet: and none of them was cleansed, saving Naaman the Syrian.","id":"saying-39","section_index":9,"contexts":[{"book":"Luke","chapter":4,"verse":25,"matched":true},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Matthew","chapter":4,"verse":1,"matched":false}]},{"number":40,"reference":"","text":"The time is fulfilled, and the kingdom of heaven is at hand: repent ye, and believe the gospel. Repent: for the kingdom of God is at hand.","id":"saying-40","section_index":9,"contexts":[{"book":"Luke","chapter":4,"verse":1,"matched":false},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Matthew","chapter":4,"verse":1,"matched":false}]}],"notes":[],"era":1},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"By the Sea — Christ Chooses the Four — The Cure in the Synagogue — Solitary Prayer — In \"The Next Towns\" Round About Galilee.","source":"Mark 1, 16-26; Luke 4, 31 . . . 38 . . . 44; Matthew 4, 17 . . . 25.","items":[{"number":41,"reference":"","text":"Come ye after me, and I will make you to become fishers of men. Follow me.","id":"saying-41","section_index":10,"contexts":[{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Luke","chapter":4,"verse":1,"matched":false},{"book":"Matthew","chapter":4,"verse":1,"matched":false}]},{"number":42,"reference":"","text":"Hold thy peace, and come out of him.","id":"saying-42","section_index":10,"contexts":[{"book":"Mark","chapter":1,"verse":25,"matched":true},{"book":"Luke","chapter":4,"verse":35,"matched":true},{"book":"Matthew","chapter":4,"verse":1,"matched":false}]},{"number":43,"reference":"","text":"I must preach the kingdom of God to other cities also: for therefore am I sent.","id":"saying-43","section_index":10,"contexts":[{"book":"Luke","chapter":4,"verse":43,"matched":true},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Matthew","chapter":4,"verse":1,"matched":false}]},{"number":44,"reference":"","text":"Let us go into the next towns, that I may preach there also: for therefore came I forth.","id":"saying-44","section_index":10,"contexts":[{"book":"Mark","chapter":1,"verse":38,"matched":true},{"book":"Luke","chapter":4,"verse":1,"matched":false},{"book":"Matthew","chapter":4,"verse":1,"matched":false}]}],"notes":[],"era":1},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Sermon on the Mount: The Beatitudes, Admonitions, Precepts.","source":"Matthew 5, 1-48.","items":[{"number":45,"reference":"","text":"Blessed are the poor in spirit: for theirs is the kingdom of heaven. Blessed are they that mourn: for they shall be comforted. Blessed are the meek: for they shall inherit the earth. Blessed are they which do hunger and thirst after righteousness: for they shall be filled. Blessed are the merciful: for they shall obtain mercy. Blessed are the pure in heart: for they shall see God. Blessed are the peacemakers: for they shall be called the children of God. Blessed are they which are persecuted for righteousness' sake: for theirs is the kingdom of heaven. Blessed are ye, when men shall revile you, and persecute you, and shall say all manner of evil against you falsely, for my sake. Rejoice, and be exceeding glad: for great is your reward in heaven: for so persecuted they the prophets which were before you. Ye are the salt of the earth; but if the salt have lost his savor, wherewith shall it be salted? it is thenceforth good for nothing, but to be cast out, and to be trodden under foot of men. Ye are the light of the world. A city that is set on a hill cannot be hid. Neither do men light a candle, and put it under a bushel, but on a candlestick; and it giveth light unto all that are in the house. Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven. Think not that I am come to destroy the law, or the prophets: I am not come to destroy, but to fulfil. For verily I say unto you, Till heaven and earth pass, one jot or one tittle shall in no wise pass from the law, till all be fulfilled. Whosoever therefore shall break one of these least commandments, and shall teach men so, he shall be called the least in the kingdom of heaven: but whosoever shall do and teach them, the same shall be called great in the kingdom of heaven. For I say unto you, That except your righteousness shall exceed the righteousness of the scribes and Pharisees, ye shall in no case enter into the kingdom of heaven. Ye have heard that it was said by them of old time, Thou shalt not kill; and whosoever shall kill shall be in danger of the judgment: but I say unto you, That whosoever is angry with his brother without a cause shall be in danger of the judgment: and whosoever shall say to his brother, Raca, shall be in danger of the council: but whosoever shall say, Thou fool, shall be in danger of hell fire. Therefore if thou bring thy gift to the altar, and there rememberest that thy brother hath aught against thee; leave there thy gift before the altar, and go thy way; first be reconciled to thy brother, and then come and offer thy gift. Agree with thine adversary quickly, while thou art in the way with him; lest at any time the adversary deliver thee to the judge, and the judge deliver thee to the officer, and thou be cast into prison. Verily I say unto thee, Thou shalt by no means come out thence, till thou hast paid the uttermost farthing. Ye have heard that it was said by them of old time, Thou shalt not commit adultery: but I say unto you, That whosoever looketh on a woman to lust after her hath committed adultery with her already in his heart. And if thy right eye offend thee, pluck it out, and cast it from thee: for it is profitable for thee that one of thy members should perish, and not that thy whole body should be cast into hell. And if thy right hand offend thee, cut it off, and cast it from thee, for it is profitable for thee that one of thy members should perish, and not that thy whole body should be cast into hell. It hath been said, Whosoever shall put away his wife, let him give her a writing of divorcement: but I say unto you, That whosoever shall put away his wife, saving for the cause of fornication, causeth her to commit adultery: and whosoever shall marry her that is divorced committeth adultery. Again, ye have heard that it hath been said by them of old time, Thou shalt not forswear thyself, but shalt perform unto the Lord thine oaths: but I say unto you, Swear not at all; neither by heaven; for it is God's throne: nor by the earth; for it is his footstool: neither by Jerusalem; for it is the city of the great King. Neither shalt thou swear by thy head, because thou canst not make one hair white or black. But let your communication be, Yea, yea; Nay, nay: for whatsoever is more than these cometh of evil. Ye have heard that it hath been said, An eye for an eye, and a tooth for a tooth: but I say unto you, That ye resist not evil: but whosoever shall smite thee on thy right cheek, turn to him the other also. And if any man will sue thee at the law, and take away thy coat, let him have thy cloak also. And whosoever shall compel thee to go a mile, go with him twain. Give to him that asketh thee, and from him that would borrow of thee turn not thou away. Ye have heard that it hath been said, Thou shalt love thy neighbor, and hate thine enemy: but I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you; that ye may be the children of your Father which is in heaven: for he maketh his sun to rise on the evil and on the good, and sendeth rain on the just and on the unjust. For if ye love them which love you, what reward have ye? do not even the publicans the same? And if ye salute your brethren only, what do ye more than others? do not even the publicans so? Be ye therefore perfect, even as your Father, which is in heaven is perfect.","id":"saying-45","section_index":11,"contexts":[{"book":"Matthew","chapter":5,"verse":3,"matched":true}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Sermon on the Mount (Continued): Almsgiving, The Lord's Prayer, Forgiving, Treasures, God or Mammon, Sufficient unto the Day.","source":"Matthew 6, 1-34.","items":[{"number":46,"reference":"","text":"TAKE heed that ye do not your alms before men, to be seen of them; otherwise ye have no reward of your Father which is in heaven. Therefore when thou doest thine alms, do not sound a trumpet before thee, as the hypocrites do in the synagogues and in the streets, that they may have glory of men. Verily I say unto you, They have their reward. But when thou doest alms, let not thy left hand know what thy right hand doeth: that thine alms may be in secret: and thy Father which seeth in secret himself shall reward thee openly. And when thou prayest, thou shalt not be as the hyprocites are: for they love to pray standing in the synagogues and in the corners of the streets, that they may be seen of men. Verily I say unto you, They have their reward. But thou, when thou prayest, enter into thy closet, and when thou hast shut thy door, pray to thy Father which is in secret; and thy Father which seeth in secret shall reward thee openly. But when ye pray, use not vain repetitions, as the heathen do: for they think that they shall be heard for their much speaking. Be not ye therefore like unto them: for your Father knoweth what things ye have need of, before ye ask him. After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name. Thy kingdom come. Thy will be done in earth, as it is in heaven. Give us this day our daily bread. And forgive us our debts, as we forgive our debtors. And lead us not into temptation, but deliver us from evil: For thine is the kingdom, and the power, and the glory, for ever. Amen. For if ye forgive men their trespasses, your heavenly Father will also forgive you: but if ye forgive not men their trespasses, neither will your Father forgive your trespasses. Moreover when ye fast, be not, as the hypocrites, of a sad countenance: for they disfigure their faces, that they may appear unto men to fast. Verily I say unto you, They have their reward. But thou, when thou fastest, anoint thy head, and wash thy face; that thou appear not unto men to fast, but unto thy Father which is in secret: and thy Father, which seeth in secret, shall reward thee openly. Lay not up for yourselves treasures upon earth, where moth and rust doth corrupt, and where thieves break through and steal: but lay up for yourselves treasures in heaven, where neither moth nor rust doth corrupt, and where thieves do not break through nor steal. For where your treasure is, there will your heart be also. The light of the body is the eye: if therefore thine eye be single, thy whole body shall be full of light. But if thine eye be evil, thy whole body shall be full of darkness. If therefore the light that is in thee be darkness, how great is that darkness! No man can serve two masters: for either he will hate the one, and love the other: or else he will hold to the one, and despise the other. Ye cannot serve God and mammon. Therefore I say unto you, Take no thought for your life, what ye shall eat, or what ye shall drink; nor yet for your body, what ye shall put on. Is not the life more than meat, and the body than raiment? Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they? Which of you by taking thought can add one cubic unto his stature? And why take ye thought for raiment? Consider the lilies of the field, how they grow; they toil not, neither do they spin; and yet I say unto you, That even Solomon in all his glory was not arrayed like one of these. Wherefore, if God so clothe the grass of the field, which to day is, and to morrow is cast into the oven, shall he not much more clothe you, O ye of little faith? Therefore take no thought, saying, What shall we eat? or, What shall we drink? or, Wherewithal shall we be clothed? (for after all these things do the Gentiles seek) for your heavenly Father knoweth that ye have need of all these things. But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you. Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.","id":"saying-46","section_index":12,"contexts":[{"book":"Matthew","chapter":6,"verse":1,"matched":true}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Sermon on the Mount (Concluded): Judge Not, Pearls before Swine, Prayer, the Golden Rule, the Strait Gate, \"I Never Knew You,\" Rock Foundation.","source":"Matthew 7, 1-29.","items":[{"number":47,"reference":"","text":"JUDGE not, that ye be not judged. For with what judgment ye judge, ye shall be judged: and with what measure ye mete, it shall be measured to you again. And why beholdest thou the mote that is in thy brother's eye, but considerest not the beam that is in thine own eye? Or how wilt thou say to thy brother, Let me pull out the mote out of thine eye; and, behold, a beam is in thine own eye? Thou hypocrite, first cast out the beam out of thine own eye; and then shalt thou see clearly to cast out the mote out of thy brother's eye. Give not that which is holy unto the dogs, neither cast ye your pearls before swine, lest they trample them under their feet, and turn again and rend you. Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you: for every one that asketh receiveth; and he that seeketh findeth; and to him that knocketh it shall be opened. Or what man is there of you, whom if his son ask bread, will he give him a stone? Or if he asks a fish, will he give him a serpent? If ye then, being evil, know how to give good gifts unto your children, how much more shall your Father which is in heaven give good things to them that ask him? Therefore all things whatsoever ye would that men should do to you, do ye even so to them: for this is the law and the prophets. Enter ye in at the strait gate: for wide is the gate, and broad is the way, that leadeth to destruction, and many there be which go in thereat: because strait is the gate, and narrow is the way, which leadeth unto life, and few there be that find it. Beware of false prophets, which come to you in sheep's clothing, but inwardly they are ravening wolves. Ye shall know them by their fruits. Do men gather grapes of thorns, or figs of thistles? Even so every good tree bringeth forth good fruit; but a corrupt tree bringeth forth evil fruit. A good tree cannot bring forth evil fruit, neither can a corrupt tree bring forth good fruit. Every tree that bringeth not forth good fruit is hewn down, and cast into the fire. Wherefore by their fruits ye shall know them. Not every one that saith unto me, Lord, Lord, shall enter into the kingdom of heaven; but he that doeth the will of my Father which is in heaven. Many will say to me in that day, Lord, Lord, have we not prophesied in thy name? and in thy name have cast out devils? and in thy name done many wonderful works? And then will I profess unto them, I never knew you: depart from me, ye that work iniquity. Therefore whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man, which built his house upon a rock: and the rain descended, and the floods came, and the winds blew, and beat upon that house: and it fell not: for it was founded upon a rock. And every one that heareth these sayings of mine, and doeth them not, shall be likened unto a foolish man, which built his house upon the sand: and the rain descended, and the floods came, and the winds blew, and beat upon that house; and it fell: and great was the fall of it.","id":"saying-47","section_index":13,"contexts":[{"book":"Matthew","chapter":7,"verse":1,"matched":true}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"A Leper Cleansed — The Draught of Fish — Palsied Man Cured.","source":"Matthew 8, 1-4; 9, 2-7; Mark 1, 40-45; 2, 1-12; Luke 5, 1-15; and 18-25.","items":[{"number":48,"reference":"","text":"I will; be thou clean.","id":"saying-48","section_index":14,"contexts":[{"book":"Matthew","chapter":8,"verse":3,"matched":true},{"book":"Mark","chapter":1,"verse":41,"matched":true},{"book":"Luke","chapter":5,"verse":13,"matched":true},{"book":"Matthew","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false}]},{"number":49,"reference":"","text":"See thou tell no man; but go thy way: say nothing to any man. Shew thyself to the priest, and offer the gift for thy cleansing, those things which Moses commanded, for a testimony unto them.","id":"saying-49","section_index":14,"contexts":[{"book":"Matthew","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Luke","chapter":5,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false}]},{"number":50,"reference":"","text":"Launch out into the deep, and let down your nets for a draught.","id":"saying-50","section_index":14,"contexts":[{"book":"Luke","chapter":5,"verse":4,"matched":true},{"book":"Matthew","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false}]},{"number":51,"reference":"","text":"Fear not; from henceforth thou shalt catch men.","id":"saying-51","section_index":14,"contexts":[{"book":"Luke","chapter":5,"verse":10,"matched":true},{"book":"Matthew","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false}]},{"number":52,"reference":"","text":"Son, be of good cheer; thy sins be forgiven thee.","id":"saying-52","section_index":14,"contexts":[{"book":"Matthew","chapter":9,"verse":2,"matched":true},{"book":"Matthew","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Luke","chapter":5,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false}]},{"number":53,"reference":"","text":"What reason ye in your hearts? Why reason ye these things? Wherefore think ye evil? Whether is it easier to say to the sick of the palsy, Thy sins be forgiven thee; or to say, Arise, and take up thy bed, and walk? But that ye may know that the Son of man hath power on earth to forgive sins,","id":"saying-53","section_index":14,"contexts":[{"book":"Mark","chapter":2,"verse":9,"matched":true},{"book":"Matthew","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Luke","chapter":5,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false}]},{"number":54,"reference":"","text":"I say unto thee, Arise, and take up thy couch, and go thy way into thine house.","id":"saying-54","section_index":14,"contexts":[{"book":"Matthew","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":1,"verse":1,"matched":false},{"book":"Luke","chapter":5,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Matthew (Levi) Called — His Banquet — The Whole Need Not a Physician — John's Disciples Fast: Christ's Fast Not — Two Parables: Old Garment, New Wine.","source":"Luke 5, 27-39; Matthew 9, 9-17; Mark 2, 13-22.","items":[{"number":55,"reference":"","text":"Follow me.","id":"saying-55","section_index":15,"contexts":[{"book":"Luke","chapter":5,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false}]},{"number":56,"reference":"","text":"They that be whole need not a physician, but they that are sick. But go ye and learn what that meaneth. I will have mercy, and not sacrifice: for I am not come to call the righteous, but sinners to repentance.","id":"saying-56","section_index":15,"contexts":[{"book":"Matthew","chapter":9,"verse":13,"matched":true},{"book":"Luke","chapter":5,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false}]},{"number":57,"reference":"","text":"Can ye make the children of the bridechamber fast, while the bridegroom is with them? as long as they have the bridegroom with them, they cannot fast. But the days will come, when the bridegroom shall be taken away from them, and then shall they fast in those days.","id":"saying-57","section_index":15,"contexts":[{"book":"Luke","chapter":5,"verse":35,"matched":true},{"book":"Mark","chapter":2,"verse":20,"matched":true},{"book":"Matthew","chapter":9,"verse":1,"matched":false}]},{"number":58,"reference":"","text":"No man also seweth a piece of new cloth upon an old garment; else the new piece that filleth it up agreeth not with the old: it taketh away from the old, and the rent is made worse.","id":"saying-58","section_index":15,"contexts":[{"book":"Luke","chapter":5,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false}]},{"number":59,"reference":"","text":"And no man putteth new wine into old bottles: else the bottles will be marred: the new wine will burst the bottles, and be spilled, and the bottles shall perish. But new wine must be put into new bottles; and both are preserved. No man also having drunk old wine straightway desireth new; for he saith, The old is better.","id":"saying-59","section_index":15,"contexts":[{"book":"Luke","chapter":5,"verse":38,"matched":true},{"book":"Matthew","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"In the Cornfield on the Sabbath — \"The Sabbath was Made for Man\" — The Withered Hand — The Pharisees Conspire — The Twelve Ordained — Parables.","source":"Matthew 12, 1-16: Mark 2, 23-28; 3, 1-15; 22-29: Luke 6, 1-13; 11, 24-26.","items":[{"number":60,"reference":"","text":"Have ye never read so much as this: what David did, when himself was a hungered, and had need, he, and they which were with him: how he went into the house of God in the days of Abiathar the high priest, and did take and eat the shewbread, and gave also to them which were with him, which was not lawful for him to eat, neither for them which were with him, but for the priests alone? Or have ye not read in the law, how that on the sabbath days the priests in the temple profane the sabbath, and are blameless? But I say unto you, That in this place is one greater than the temple. But if ye had known what this meaneth, I will have mercy, and not sacrifice, ye would not have condemned the guiltless. The sabbath was made for man, and not man for the sabbath: therefore the Son of man is Lord even of the sabbath day.","id":"saying-60","section_index":16,"contexts":[{"book":"Matthew","chapter":12,"verse":5,"matched":true},{"book":"Mark","chapter":2,"verse":1,"matched":false},{"book":"Luke","chapter":6,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Luke","chapter":11,"verse":1,"matched":false}]},{"number":61,"reference":"","text":"Rise up, and stand forth in the midst.","id":"saying-61","section_index":16,"contexts":[{"book":"Luke","chapter":6,"verse":8,"matched":true},{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Luke","chapter":11,"verse":1,"matched":false}]},{"number":62,"reference":"","text":"I will ask you one thing: Is it lawful on the sabbath days to do good, or to do evil? to save life, or to kill? to save life, or to destroy it?","id":"saying-62","section_index":16,"contexts":[{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false},{"book":"Luke","chapter":6,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Luke","chapter":11,"verse":1,"matched":false}]},{"number":63,"reference":"","text":"What man shall there be among you, that shall have one sheep, and if it fall into a pit on the sabbath day, will he not lay hold on it, and lift it out? How much then is a man better than a sheep? Wherefore it is lawful to do well on the sabbath days.","id":"saying-63","section_index":16,"contexts":[{"book":"Matthew","chapter":12,"verse":12,"matched":true},{"book":"Mark","chapter":2,"verse":1,"matched":false},{"book":"Luke","chapter":6,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Luke","chapter":11,"verse":1,"matched":false}]},{"number":64,"reference":"","text":"Stretch forth thine hand.","id":"saying-64","section_index":16,"contexts":[{"book":"Matthew","chapter":12,"verse":13,"matched":true},{"book":"Mark","chapter":3,"verse":5,"matched":true},{"book":"Mark","chapter":2,"verse":1,"matched":false},{"book":"Luke","chapter":6,"verse":1,"matched":false},{"book":"Luke","chapter":11,"verse":1,"matched":false}]},{"number":65,"reference":"","text":"How can Satan cast out Satan? And if a kingdom be divided against itself, that kingdom cannot stand. And if a house be divided against itself, that house cannot stand. And if Satan rise up against himself, and be divided, he cannot stand, but hath an end. No man can enter into a strong man's house, and spoil his goods, except he will first bind the strong man; and then he will spoil his house. Verily I say unto you, All sins shall be forgiven unto the sons of men, and blasphemies wherewith soever they shall blaspheme: but he that shall blaspheme against the Holy Ghost hath never forgiveness, but is in danger of eternal damnation.","id":"saying-65","section_index":16,"contexts":[{"book":"Mark","chapter":3,"verse":24,"matched":true},{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false},{"book":"Luke","chapter":6,"verse":1,"matched":false},{"book":"Luke","chapter":11,"verse":1,"matched":false}]},{"number":66,"reference":"","text":"When the unclean spirit is gone out of a man, he walketh through dry places, seeking rest: and finding none, he saith, I will return unto my house whence I came out. And when he cometh, he findeth it swept and garnished. Then goeth he, and taketh to him seven other spirits more wicked than himself; and the last state of that man is worse than the first.","id":"saying-66","section_index":16,"contexts":[{"book":"Luke","chapter":11,"verse":24,"matched":true},{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":2,"verse":1,"matched":false},{"book":"Luke","chapter":6,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Twelve By Name — The Sermon in the Plain: Benisons and Admonitions, Precepts, the Golden Rule Again, Judge Not, Give.","source":"Matthew 10, 2-4: Mark 3, 16-19: Luke 6, 14-38.","items":[{"number":67,"reference":"","text":"Blessed be ye poor: for yours is the kingdom of God. Blessed are ye that hunger now: for ye shall be filled. Blessed are ye that weep now: for ye shall laugh. Blessed are ye, when men shall have you, and when they shall separate you from their company, and shall reproach you, and cast out your name as evil, for the Son of man's sake. Before ye in that day, and leap for joy: for, behold, your reward is great in heaven: for in the like manner did their fathers unto the prophets. But woe unto you that are rich! for ye have received your consolation. Woe unto you that are full! for ye shall hunger. Woe unto you that laugh now! for ye shall mourn and weep. Woe unto you, when all men shall speak well of you! for so did their fathers to the false prophets. But I say unto you which hear, Love your enemies, do good to them which hate you, bless them that curse you, and pray for them which despitefully use you. And unto him that smiteth thee on the one cheek offer also the other; and him that taketh away by cloak forbid not to take thy coat also. Give to every man that asketh of thee; and of him that taketh away thy goods ask them not again. And as ye would that men should do to you, do ye also to them likewise. For if ye love them which love you, what thank have ye? for sinners also love those that love them. And if ye do good to them which do good to you, what thank have ye? for sinners also do even the same. And if ye lend to them of whom ye hope to receive, what thank have ye? for sinners also lend to sinners, to receive as much again. But love ye your enemies, and do good, and lend, hoping for nothing again; and your reward shall be great, and ye shall be the children of the Highest: for he is kind unto the unthankful and to the evil. Be ye therefore merciful, as your Father also is merciful. Judge not, and ye shall not be judged: condemn not, and ye shall not be condemned: forgive, and ye shall be forgiven: Give, and it shall be given unto you; good measure, pressed down, and shaken together, and running over, shall men give into your bosom. For with the same measure that ye mete withal it shall be measured to you again.","id":"saying-67","section_index":17,"contexts":[{"book":"Luke","chapter":6,"verse":21,"matched":true},{"book":"Matthew","chapter":10,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Sermon in the Plain (Concluded) — More Parables — \"Why Call Ye Me, 'Lord, Lord'?\" — Rock Foundation.","source":"Luke 6, 39-49.","items":[{"number":68,"reference":"","text":"Can the blind lead the blind? shall they not both fall into the ditch? The disciple is not above his master: but every one that is perfect shall be as his master. And why beholdest thou the mote that is in thy brother's eye, but perceivest not the beam that is in thine own eye? Either how canst thou say to thy brother, Brother, let me pull out the mote that is in thine eye, when thou thyself beholdest not the beam that is in thine own eye? Thou hypocrite, cast out first the beam out of thine own eye, and then shalt thou see clearly to pull out the mote that is in thy brother's eye. For a good tree bringeth not forth corrupt fruit; neither doth a corrupt tree bring forth good fruit. For every tree is known by his own fruit. For of thorns men do not gather figs, nor of a bramble bush gather they grapes. A good man out of the good treasure of his heart bringeth forth that which is good; and an evil man out of the evil treasure of his heart bringeth forth that which is evil: for of the abundance of the heart his mouth speaketh. And why call ye me, Lord, Lord, and do not the things which I say? Whosoever cometh to me, and heareth my sayings, and doeth them, I will shew you to whom he is like: He is like a man which built a house, and digged deep, and laid the foundation on a rock: and when the flood arose, the stream beat vehemently upon that house, and could not shake it: for it was founded upon a rock. But he that heareth, and doeth not, is like a man that without a foundation built a house upon the earth; against which the stream did beat vehemently, and immediately it fell; and the ruin of that house was great.","id":"saying-68","section_index":18,"contexts":[{"book":"Luke","chapter":6,"verse":40,"matched":true}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Centurion's Servant Healed — The Widow's Son Restored.","source":"Matthew 8, 5-13: Luke 7, 11-18.","items":[{"number":69,"reference":"","text":"I will come and heal him.","id":"saying-69","section_index":19,"contexts":[{"book":"Matthew","chapter":8,"verse":7,"matched":true},{"book":"Luke","chapter":7,"verse":1,"matched":false}]},{"number":70,"reference":"","text":"Verily I say unto you, I have not found so great faith, no, not in Israel. And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven: but the children of the kingdom shall be cast out into outer darkness: there shall be weeping and gnashing of teeth.","id":"saying-70","section_index":19,"contexts":[{"book":"Matthew","chapter":8,"verse":11,"matched":true},{"book":"Luke","chapter":7,"verse":1,"matched":false}]},{"number":71,"reference":"","text":"Go thy way; and as thou hast believed, so be it done unto thee.","id":"saying-71","section_index":19,"contexts":[{"book":"Matthew","chapter":8,"verse":13,"matched":true},{"book":"Luke","chapter":7,"verse":1,"matched":false}]},{"number":72,"reference":"","text":"Weep not.","id":"saying-72","section_index":19,"contexts":[{"book":"Matthew","chapter":8,"verse":1,"matched":false},{"book":"Luke","chapter":7,"verse":1,"matched":false}]},{"number":73,"reference":"","text":"Young man, I say unto thee, Arise.","id":"saying-73","section_index":19,"contexts":[{"book":"Luke","chapter":7,"verse":14,"matched":true},{"book":"Matthew","chapter":8,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"John, From Prison, Sends Messengers — Jesus Replies — Extols John: A Sermon with Parables — \"Friend of Sinners.\"","source":"Matthew 11, 2-15; 16-19: Luke 7, 24-35.","items":[{"number":74,"reference":"","text":"Go your way, and tell John again what things ye have seen and heard: how that the blind receive their sight, and the lane walk, the lepers are cleansed, and the deaf hear, the dead are raised up, and the poor have the gospel preached to them. And blessed is he, whosoever shall not be offended in me.","id":"saying-74","section_index":20,"contexts":[{"book":"Matthew","chapter":11,"verse":6,"matched":true},{"book":"Luke","chapter":7,"verse":23,"matched":true}]},{"number":75,"reference":"","text":"What went ye out into the wilderness for to see? A reed shaken with the wind? But what went ye out for to see? A man clothed in soft raiment? Behold, they that wear soft clothing, they which are gorgeously apparelled, and live delicately, are in kings’ courts, in kings’ houses. But what went ye out for to see? A prophet? Yea, I say unto you, and much more than a prophet. For this is he of whom it is written, Behold, I send my messenger before thy face, which shall prepare thy way before thee. Verily, I say unto you, Among them that are born of women there hath not risen a greater prophet than John the Baptist: notwithstanding, he that is least in the kingdom of God is greater than he. And from the days of John the Baptist until now the kingdom of heaven suffereth violence, and the violent take it by force. For all the prophets and the law prophesied until John. And if ye will receive it, this is Elias, which was for to come. He that hath ears to hear, let him hear.","id":"saying-75","section_index":20,"contexts":[{"book":"Matthew","chapter":11,"verse":10,"matched":true},{"book":"Luke","chapter":7,"verse":26,"matched":true}]},{"number":76,"reference":"","text":"But whereunto then shall I liken the men of this generation? and to what are they like? They are like unto children sitting in the marketplace, and calling unto their fellows, one to another, and saying, We have piped unto you, and ye have not danced; we have mourned unto you, and ye have not lamented: ye have not wept. For John the Baptist came neither eating bread nor drinking wine; and they say, He hath a devil. The Son of man is come eating and drinking; and they say, Behold a man gluttonous and a winebibber, a friend of publicans and sinners! But wisdom is justified of all her children.","id":"saying-76","section_index":20,"contexts":[{"book":"Matthew","chapter":11,"verse":17,"matched":true},{"book":"Luke","chapter":7,"verse":35,"matched":true}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Woe unto Chorazin, Bethsaida, Capernaum — \"Come unto Me...My Yoke is Easy.\"","source":"Matthew 11, 20-30: Luke 10, 13-15.","items":[{"number":77,"reference":"","text":"Woe unto thee, Chorazin! woe unto thee, Bethsaida! for if the mighty works, which were done in you, had been done in Tyre and Sidon, they would have repented long ago in sackcloth and ashes. But I say unto you, It shall be more tolerable for Tyre and Sidon at the day of judgment, than for you. And thou, Capernaum, which are exalted unto heaven, shall be brought down to hell: for if the mighty works, which have been done in thee, had been done in Sodom, it would have remained until this day. But I say unto you, That it shall be more tolerable for the land of Sodom in the day of judgment, than for thee.","id":"saying-77","section_index":21,"contexts":[{"book":"Matthew","chapter":11,"verse":21,"matched":true},{"book":"Luke","chapter":10,"verse":1,"matched":false}]},{"number":78,"reference":"","text":"I thank thee, O Father, Lord of heaven and earth, because thou hast hid these things from the wise and prudent, and hast revealed them unto babes. Even so, Father: for so it seemed good in thy sight. All things are delivered unto me of my Father, and no man knoweth the Son, but the Father; neither knoweth any man the Father, save the Son, and he to whomsoever the Son will reveal him. Come unto me, all ye that labor and are heavy laden, and I will give you rest. Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls. For my yoke is easy, and my burden is light.","id":"saying-78","section_index":21,"contexts":[{"book":"Matthew","chapter":11,"verse":26,"matched":true},{"book":"Luke","chapter":10,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Woman with the Alabaster Box of Ointment, and Simon the Pharisee: Parable of the Two Debtors.","source":"Luke 7, 36-50.","items":[{"number":79,"reference":"","text":"Simon, I have somewhat to say unto thee: There was a certain creditor which had two debtors; the one owed five hundred pence, and the other fifty. And when they had nothing to pay, he frankly forgave them both. Tell me therefore, which of them will love him most?","id":"saying-79","section_index":22,"contexts":[{"book":"Luke","chapter":7,"verse":41,"matched":true}]},{"number":80,"reference":"","text":"Thou hast rightly judged.","id":"saying-80","section_index":22,"contexts":[{"book":"Luke","chapter":7,"verse":43,"matched":true}]},{"number":81,"reference":"","text":"Seest thou this woman? I entered into thine house, thou gavest me no water for my feet: but she hath washed my feet with tears, and wiped them with the hairs of her head. Thou gavest me no kiss: but this woman, since the time I came in, hath not ceased to kiss my feet. My head with oil thou didst not anoint: but this woman hath anointed my feet with ointment. Wherefore I say unto thee, Her sins, which are many, are forgiven; for she loveth much: but to whom little is forgiven, the same loveth little.","id":"saying-81","section_index":22,"contexts":[{"book":"Luke","chapter":7,"verse":45,"matched":true}]},{"number":82,"reference":"","text":"Thy sins are forgiven.","id":"saying-82","section_index":22,"contexts":[{"book":"Luke","chapter":7,"verse":48,"matched":true}]},{"number":83,"reference":"","text":"Thy faith hath saved thee; go in peace.","id":"saying-83","section_index":22,"contexts":[{"book":"Luke","chapter":7,"verse":50,"matched":true}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Man Blind, Mute, and Bedeviled — Doubting Pharisees Admonished — Parables — \"Every Idle Word.\"","source":"Matthew 12, 22-37: Luke 11, 17-23: Mark 3, 22-29.","items":[{"number":84,"reference":"","text":"Every kingdom divided against itself is brought to desolation; and every city or house divided against itself falleth: it shall not stand: and if Satan cast out Satan, he is divided against himself; how shall then his kingdom stand? because ye say that I cast out devils through Beelzebub. And if I by Beelzebub cast out devils, by whom do your children cast them out? therefore they shall be your judges. But if I with the finger of God cast out devils by the Spirit of God, no doubt then the kingdom of God is come unto you. Or else, how can one enter into a strong man's house, and spoil his goods, except he first bind the strong man? and then he will spoil his house. When a strong man armed keepeth his palace, his goods are in peace: but when a stronger than he shall come upon him, and overcome him, he taketh from him all his armor wherein he trusted, and divideth the spoils. He that is not with me is against me; and he that gathereth not with me scattereth abroad. Wherefore I say unto you, All manner of sin and blasphemy shall be forgiven unto the sons of men: but the blasphemy against the Holy Ghost shall not be forgiven unto men. And whosoever speaketh a word against the Son of man, it shall be forgiven him: but whosoever speaketh against the Holy Ghost is in danger of eternal damnation: it shall not be forgiven him, neither in this world, neither in the world to come. Either make the tree good, and his fruit good; or else make the tree corrupt: for the tree is known by his fruit. O generation of vipers, how can ye, being evil, speak good things? for out of the abundance of the heart the mouth speaketh. A good man out of the good treasure of the heart bringeth forth good things: and an evil man out of the evil treasure bringeth forth evil things. But I say unto you, That every idle word that men shall speak, they shall give account thereof in the day of judgment. For by thy words thou shalt be justified, and by thy words thou shalt be condemned.","id":"saying-84","section_index":23,"contexts":[{"book":"Matthew","chapter":12,"verse":26,"matched":true},{"book":"Luke","chapter":11,"verse":21,"matched":true},{"book":"Mark","chapter":3,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Doubters Seek a Sign — \"A Greater than Solomon is Here\" — Parable: The Backslider.","source":"Matthew 12, 38-45.","items":[{"number":85,"reference":"","text":"An evil and adulterous generation seeketh after a sign; and there shall no sign be given to it, but the sign of the prophet Jonas: for as Jonas was three days and three nights in the whale's belly; so shall the Son of man be three days and three nights in the heart of the earth. The men of Nineveh shall rise in judgment with this generation, and shall condemn it: because they repented at the preaching of Jonas; and, behold, a greater than Jonas is here. The queen of the south shall rise up in the judgment with this generation, and shall condemn it: for she came from the uttermost parts of the earth to hear the wisdom of Solomon; and, behold, a greater than Solomon is here. When the unclean spirit is gone out of a man, he walketh through dry places, seeking rest, and findeth none. Then he saith, I will return into my house from whence I came out; and when he is come, he findeth it empty, swept, and garnished. Then goeth he, and taketh with himself seven other spirits more wicked than himself, and they enter in and dwell there: and the last state of that man is worse than the first. Even so shall it be also unto this wicked generation.","id":"saying-85","section_index":24,"contexts":[{"book":"Matthew","chapter":12,"verse":40,"matched":true}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"His Mother and Brethren would Speak with Jesus — From Ship Talks to Hearers on the Shore: Three Parables on Seeds, One on the Candle.","source":"Matt. 12, 46-50; 13, 1-30; Mark 3, 31-35; 4, 1-29: Luke 8, 4-18; 19-21.","items":[{"number":86,"reference":"","text":"Who is my mother? and who are my brethren?","id":"saying-86","section_index":25,"contexts":[{"book":"Matthew","chapter":12,"verse":48,"matched":true},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false}]},{"number":87,"reference":"","text":"Behold my mother and my brethren! My mother and my brethren are these which hear the word of God, and do it. For whosoever shall do the will of God my Father which is in heaven, the same is my brother, and my sister, and mother.","id":"saying-87","section_index":25,"contexts":[{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false}]},{"number":88,"reference":"","text":"Hearken: Behold, a sower went forth to sow his seed: and it came to pass, as he sowed, some fell by the way side, and it was trodden down, and the fowls of the air came and devoured it up. Some seed fell on stony ground where it had not much earth: and immediately it sprang up, because it had not much deepness of earth: but when the sun was up, because it had no depth of earth, it was scorched; and because it had no root, it withered away. And some fell upon a rock: as soon as it was sprung up, it withered away, because it lacked moisture. And some fell among thorns, and the thorns grew up with it, and choked it, and it yielded no fruit. But other fell into good ground, and did yield fruit that sprang up, and increased; and bare fruit, some a hundredfold, some sixtyfold, and some thirtyfold. He that hath ears to hear, let him hear.","id":"saying-88","section_index":25,"contexts":[{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false}]},{"number":89,"reference":"","text":"Because it is given unto you to know the mysteries of the kingdom of heaven, but to them it is not given but in parables: unto them that are without, all these things are done in parables. For whosoever hath, to him shall be given, and he shall have more abundance: but whosoever hath not, from him shall be taken away even that he hath. Therefore speak I to them in parables: because they seeing see not; and hearing they hear not, neither do they understand.","id":"saying-89","section_index":25,"contexts":[{"book":"Matthew","chapter":13,"verse":12,"matched":true},{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false}]},{"number":90,"reference":"","text":"which saith, By hearing ye shall hear, and shall not understand; and seeing ye shall see, and shall not perceive: for this people's heart is waxed gross, and their ears are dull of hearing, and their eyes they have closed; lest at any time they should see with their eyes, and hear with their ears, and should understand with their heart, and should be converted, and I should heal them, and their sins should be forgiven them. But blessed are your eyes, for they see: and your ears, for they hear. For verily I say unto you, That many prophets and righteous men have desired to see those things which ye see, and have not seen them; and to hear those things which ye hear, and have not heard them.","id":"saying-90","section_index":25,"contexts":[{"book":"Matthew","chapter":13,"verse":15,"matched":true},{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false}]},{"number":91,"reference":"","text":"Know ye not this parable? And how then will ye know all parables? Hear ye therefore the parable of the sower. Now the parable is this: The seed is the word of God. The sower soweth the word. When any one heareth the word of the kingdom, and understandeth it not, then cometh immediately Satan the wicked one, and catcheth away that word, which was sown in his heart: the devil taketh away the word out of their hearts, lest they should believe and be saved. This is he which received seed by the way side, where the word is sown. They on the rock received seed into stony places: these are they who when they have heard the word, anon with joy receive it, and for a while believe; yet have no root in themselves, and so endure but for a time; and in time of temptation fall away: for afterward, when affliction or tribulation or persecution ariseth for the word's sake, immediately they are offended. And they which received the seed among thorns, are they, which, when they have heard the word, go forth, and are choked with the cares of this world and the deceitfulness of riches and the pleasures of this life; and bring no fruit to perfection: the lusts of other things entering in, choke the word, and it becometh unfruitful. But he that received the seed into the good ground is he that in an honest and good heart, having heard the word, understandeth it, and keepeth it, and beareth fruit with patience, and bringeth forth, some a hundredfold, some sixty, some thirty.","id":"saying-91","section_index":25,"contexts":[{"book":"Luke","chapter":8,"verse":11,"matched":true},{"book":"Matthew","chapter":13,"verse":18,"matched":true},{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false}]},{"number":92,"reference":"","text":"The kingdom of heaven is likened unto a man which sowed good seed in his field: but while men slept, his enemy came and sowed tares among the wheat, and went his way. But when the blade was sprung up, and brought forth fruit, then appeared the tares also. So the servants of the householder came and said unto him, Sir, didst not thou sow good seed in thy field? from whence then hath it tares? He said unto them, An enemy hath done this. The servants said unto him, Wilt thou then that we go and gather them up? But he said, Nay; lest while ye gather up the tares, ye root up also the wheat with them. Let both grow together until the harvest: and in the time of harvest I will say to the reapers, Gather ye together first the tares, and bind them in bundles to burn them: but gather the wheat into my barn.","id":"saying-92","section_index":25,"contexts":[{"book":"Matthew","chapter":13,"verse":25,"matched":true},{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false}]},{"number":93,"reference":"","text":"Is a candle brought to be put under a bushel, or under a bed? and not to be set on a candlestick? No man, when he hath lighted a candle, covereth it with a vessel, or putteth it under a bed; but setteth it on a candlestick, that they which enter in may see the light. For there is nothing hid, neither was anything kept secret, which shall not be manifested; but that it should be known and come abroad. If any man have ears to hear, let him hear. Take heed what ye hear. With what measure ye mete, it shall be measured to you; and unto you that hear shall more be given: for he that hath, to him shall be given; and he that hath not, from him shall be taken even that which he hath.","id":"saying-93","section_index":25,"contexts":[{"book":"Luke","chapter":8,"verse":16,"matched":true},{"book":"Mark","chapter":4,"verse":23,"matched":true},{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Matthew","chapter":13,"verse":1,"matched":false}]},{"number":94,"reference":"","text":"So is the kingdom of God, as if a man should cast seed into the ground; and should sleep, and rise night and day, and the seed should spring and grow up, he knoweth not how. For the earth bringeth forth fruit of herself; first the blade, then the ear, after that the full corn in the ear. But when the fruit is brought forth, immediately he putteth in the sickle, because the harvest is come.","id":"saying-94","section_index":25,"contexts":[{"book":"Mark","chapter":4,"verse":27,"matched":true},{"book":"Matthew","chapter":12,"verse":1,"matched":false},{"book":"Mark","chapter":3,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Matthew","chapter":13,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Parables: The Mustard Seed, the Leaven, the Merchantman, the Net — Parable of the Tares explained — The Tempest Quelled.","source":"Matthew 13:31–53; Mark 4:30–41; Luke 8:22–25","items":[{"number":95,"reference":"","text":"Whereunto shall we liken the kingdom of God? or with what comparison shall we compare it? A grain of mustard seed is the least of all seeds: is indeed less than all the seeds that be in the earth; but when it is sown in the earth, it groweth up: it becometh greater than all herbs; it shooteth out great branches, and becometh a tree, so that the fowls of the air come and lodge in the branches thereof.","id":"saying-95","section_index":26,"contexts":[{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false}]},{"number":96,"reference":"","text":"Unto what is the kingdom of God like? and whereunto shall I resemble it? The kingdom of heaven is like unto a grain of mustard seed, which a man took and cast into a garden in his field; and it grew, and waxed a great tree, and the birds of the air lodged in the branches thereof, in the shadow of it.","id":"saying-96","section_index":26,"contexts":[{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false}]},{"number":97,"reference":"","text":"Whereunto shall I liken the kingdom of God?","id":"saying-97","section_index":26,"contexts":[{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false}]},{"number":98,"reference":"","text":"The kingdom of heaven is like unto leaven, which a woman took, and hid in three measures of meal, till the whole was leavened.","id":"saying-98","section_index":26,"contexts":[{"book":"Matthew","chapter":13,"verse":33,"matched":true},{"book":"Mark","chapter":4,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false}]},{"number":99,"reference":"","text":"He that soweth the good seed is the Son of man; the field is the world; the good seed are the children of the kingdom; but the tares are the children of the wicked one; the enemy that sowed them is the devil; the harvest is the end of the world; and the reapers are the angels. As therefore the tares are gathered and burned in the fire; so shall it be in the end of this world. The Son of man shall send forth his angels, and they shall gather out of his kingdom all things that offend, and them which do iniquity; and shall cast them into a furnace of fire: there shall be wailing and gnashing of teeth. Then shall the righteous shine forth as the sun in the kingdom of their Father. Who hath ears to hear, let him hear. Again, the kingdom of heaven is like unto a treasure hid in a field; the which when a man hath found, he hideth, and for joy thereof goeth and selleth all that he hath, and buyeth that field. Again, the kingdom of heaven is like unto a merchantman, seeking goodly pearls: who, when he had found one pearl of great price, went and sold all that he had, and bought it. Again, the kingdom of heaven is like unto a net, that was cast into the sea, and gathered of every kind: which, when it was full, they drew to shore, and sat down, and gathered the good into vessels, but cast the bad away. So shall it be at the end of the world: the angels shall come forth, and sever the wicked from the just, and shall cast them into the furnace of fire: there shall be wailing and gnashing of teeth.","id":"saying-99","section_index":26,"contexts":[{"book":"Matthew","chapter":13,"verse":9,"matched":true},{"book":"Mark","chapter":4,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false}]},{"number":100,"reference":"","text":"Have ye understood all these things?","id":"saying-100","section_index":26,"contexts":[{"book":"Matthew","chapter":13,"verse":51,"matched":true},{"book":"Mark","chapter":4,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false}]},{"number":101,"reference":"","text":"Therefore every scribe which is instructed unto the kingdom of heaven, is like unto a man that is a householder, which bringeth forth out of his treasure things new and old.","id":"saying-101","section_index":26,"contexts":[{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false}]},{"number":102,"reference":"","text":"Let us pass over unto the other side of the lake.","id":"saying-102","section_index":26,"contexts":[{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false}]},{"number":103,"reference":"","text":"Why are ye fearful, O ye of little faith?","id":"saying-103","section_index":26,"contexts":[{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false}]},{"number":104,"reference":"","text":"Peace, be still.","id":"saying-104","section_index":26,"contexts":[{"book":"Mark","chapter":4,"verse":39,"matched":true},{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false}]},{"number":105,"reference":"","text":"Why are ye fearful? where is your faith? how is it that ye have no faith?","id":"saying-105","section_index":26,"contexts":[{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Mark","chapter":4,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Madman and the Swine.","source":"Mark 5, 1-20: Luke 8, 26-40: Matthew 8, 28-34.","items":[{"number":106,"reference":"","text":"Come out of the man, thou unclean spirit.","id":"saying-106","section_index":27,"contexts":[{"book":"Mark","chapter":5,"verse":8,"matched":true},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Matthew","chapter":8,"verse":1,"matched":false}]},{"number":107,"reference":"","text":"What is thy name?","id":"saying-107","section_index":27,"contexts":[{"book":"Mark","chapter":5,"verse":9,"matched":true},{"book":"Luke","chapter":8,"verse":30,"matched":true},{"book":"Matthew","chapter":8,"verse":1,"matched":false}]},{"number":108,"reference":"","text":"Go.","id":"saying-108","section_index":27,"contexts":[{"book":"Mark","chapter":5,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Matthew","chapter":8,"verse":1,"matched":false}]},{"number":109,"reference":"","text":"Return to thine own house. Go home to thy friends; tell them how the Lord had compassion on thee, and shew them how great things God hath done unto thee.","id":"saying-109","section_index":27,"contexts":[{"book":"Mark","chapter":5,"verse":1,"matched":false},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Matthew","chapter":8,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Jairus' Daughter Healed — The Woman who had Spent her all on Physicians — The Two Blind Men.","source":"Luke 8:40–56; Mark 5:21–43; Matthew 9:18–34","items":[{"number":110,"reference":"","text":"Be not afraid, only believe. Fear not, believe only, and she shall be made whole.","id":"saying-110","section_index":28,"contexts":[{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":5,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false}]},{"number":111,"reference":"","text":"Why make ye this ado, and weep? Weep not. Give place. The damsel is not dead, but sleepeth.","id":"saying-111","section_index":28,"contexts":[{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":5,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false}]},{"number":112,"reference":"","text":"Maid, arise.","id":"saying-112","section_index":28,"contexts":[{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":5,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false}]},{"number":113,"reference":"","text":"Who touched me?","id":"saying-113","section_index":28,"contexts":[{"book":"Luke","chapter":8,"verse":45,"matched":true},{"book":"Mark","chapter":5,"verse":31,"matched":true},{"book":"Matthew","chapter":9,"verse":1,"matched":false}]},{"number":114,"reference":"","text":"Somebody hath touched me: for I perceive that virtue is gone out of me. Who touched my clothes?","id":"saying-114","section_index":28,"contexts":[{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":5,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false}]},{"number":115,"reference":"","text":"Daughter, be of good comfort; thy faith hath made thee whole. Go in peace, and be whole of thy plague.","id":"saying-115","section_index":28,"contexts":[{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":5,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false}]},{"number":116,"reference":"","text":"Believe ye that I am able to do this?","id":"saying-116","section_index":28,"contexts":[{"book":"Matthew","chapter":9,"verse":28,"matched":true},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":5,"verse":1,"matched":false}]},{"number":117,"reference":"","text":"According to your faith be it unto you.","id":"saying-117","section_index":28,"contexts":[{"book":"Matthew","chapter":9,"verse":29,"matched":true},{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":5,"verse":1,"matched":false}]},{"number":118,"reference":"","text":"See that no man know it. But they spread abroad his fame in all that country.","id":"saying-118","section_index":28,"contexts":[{"book":"Luke","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":5,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Home Again: A Prophet without Honor — Mission of the Twelve: Instructions, Admonitions, Sparrows, Hairs Numbered — They Set Out.","source":"Mark 6, 1-6, 7-13: Matthew 13, 54-58; 9, 35-38; 10, 5-42: Luke 9, 1-6.","items":[{"number":119,"reference":"","text":"A prophet is not without honor, save in his own country, and among his own kin, and in his own house.","id":"saying-119","section_index":29,"contexts":[{"book":"Mark","chapter":6,"verse":1,"matched":false},{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":10,"verse":1,"matched":false}]},{"number":120,"reference":"","text":"The harvest truly is plenteous, but the laborers are few; pray ye therefore the Lord of the harvest, that he will send forth laborers into his harvest.","id":"saying-120","section_index":29,"contexts":[{"book":"Mark","chapter":6,"verse":1,"matched":false},{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":10,"verse":1,"matched":false}]},{"number":121,"reference":"","text":"Go not into the way of the Gentiles, and into any city of the Samaritans enter ye not: but go rather to the lost sheep of the house of Israel. And as ye go, preach, saying, The kingdom of heaven is at hand. Heal the sick, cleanse the lepers, raise the dead, cast out devils: freely ye have received, freely give. Take nothing for your journey, neither staves nor bread; provide neither gold, nor silver, nor brass in your purses, nor scrip for your journey, neither two coats apiece; nor yet shoes, but be shod with sandals; for the workman is worthy of his meat. And into whatsoever city or town ye shall enter, in what place soever ye enter into a house, inquire who in it is worthy; and there abide till ye go, and thence depart. And when ye come into a house, salute it. And if the house be worthy, let your peace come upon it: but if it be not worthy, let your peace return to you. And whosoever shall not receive you, nor hear your words, when ye depart out of that house or city, shake off the very dust from your feet for a testimony against them. Verily I say unto you, It shall be more tolerable for the land of Sodom and Gomorrah in the day of judgment, than for that city. Behold, I send you forth as sheep in the midst of wolves: be ye therefore wise as serpents, and harmless as doves. But beware of men: for they will deliver you up to the councils, and they will scourge you in their synagogues; and ye shall be brought before governors and kings for my sake, for a testimony against them and the Gentiles. But when they deliver you up, take no thought how or what ye shall speak: for it shall be given you in that same hour what ye shall speak. For it is not ye that speak, but the Spirit of your Father which speaketh in you. And the brother shall deliver up the brother to death, and the father the child: and the children shall rise up against their parents, and cause them to be put to death. And ye shall be hated of all men for my name's sake: but he that endureth to the end shall be saved. But when they persecute you in this city, flee ye into another: for verily I say unto you, Ye shall not have gone over the cities of Israel, till the Son of man be come. The disciple is not above his master, nor the servant above his lord. It is enough for the disciple that he be as his master, and the servant as his lord. If they have called the master of the house Beelzebub, how much more shall they call them of his household? Fear them not therefore: for there is nothing covered that shall not be revealed; and hid that shall not be known. What I tell you in darkness that speak ye in light: and what ye hear in the ear, that preach ye upon the housetops. And fear not them which kill the body, but are not able to kill the soul: but rather fear him which is able to destroy both soul and body in hell. Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father. But the very hairs of your head are all numbered. Fear ye not therefore, ye are of more value than many sparrows. Whosoever therefore shall confess me before men, him will I confess also before my Father which is in heaven. But whosoever shall deny me before men, him will I also deny before my Father which is in heaven. Think not that I am come to send peace on earth: I came not to send peace, but a sword. For I am come to set a man at variance against his father, and the daughter against her mother, and the daughter in law against her mother in law. And a man's foes shall be they of his own household. He that loveth father or mother more than me is not worthy of me: and he that loveth son or daughter more than me is not worthy of me. And he that taketh not his cross, and followeth after me, is not worthy of me. He that findeth his life shall lose it; and he that loseth his life for my sake shall find it. He that receiveth you receiveth me, and he that receiveth me receiveth him that sent me. He that receiveth a prophet in the name of a prophet shall receive a prophet's reward; and he that receiveth a righteous man in the name of a righteous man shall receive a righteous man's reward. And whosoever shall give to drink unto one of these little ones a cup of cold water only in the name of a disciple, verily I say unto you, he shall in no wise lose his reward.","id":"saying-121","section_index":29,"contexts":[{"book":"Matthew","chapter":10,"verse":6,"matched":true},{"book":"Mark","chapter":6,"verse":1,"matched":false},{"book":"Matthew","chapter":13,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":9,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Herod the Tetrarch Desires to See Christ — Christ Withdraws. A D. 29. Age 32 Decapolis: Bethsaida .","source":"Matthew 14, 1-4; 13-14: Luke 9, 7-11: Mark 6, 17-18; 30-33: John 6, 1-3.","items":[{"number":122,"reference":"","text":"Come ye yourselves apart into a desert place, and rest a while.","id":"saying-122","section_index":30,"contexts":[{"book":"Mark","chapter":6,"verse":31,"matched":true},{"book":"Matthew","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"John","chapter":6,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Five Loaves and Two Fishes Suffices Five Thousand Persons.","source":"John 6, 5-13: Matthew 14, 15-21: Mark 6, 35-44: Luke 9, 12-17.","items":[{"number":123,"reference":"","text":"Whence shall we buy bread, that these may eat?","id":"saying-123","section_index":31,"contexts":[{"book":"John","chapter":6,"verse":5,"matched":true},{"book":"Matthew","chapter":14,"verse":1,"matched":false},{"book":"Mark","chapter":6,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false}]},{"number":124,"reference":"","text":"They need not depart; give ye them to eat. How many loaves have ye? Go and see.","id":"saying-124","section_index":31,"contexts":[{"book":"John","chapter":6,"verse":1,"matched":false},{"book":"Matthew","chapter":14,"verse":1,"matched":false},{"book":"Mark","chapter":6,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false}]},{"number":125,"reference":"","text":"Bring them hither to me. Make the men sit down by fifties in a company.","id":"saying-125","section_index":31,"contexts":[{"book":"John","chapter":6,"verse":1,"matched":false},{"book":"Matthew","chapter":14,"verse":1,"matched":false},{"book":"Mark","chapter":6,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false}]},{"number":126,"reference":"","text":"Gather up the fragments that remain, that nothing be lost.","id":"saying-126","section_index":31,"contexts":[{"book":"John","chapter":6,"verse":12,"matched":true},{"book":"Matthew","chapter":14,"verse":1,"matched":false},{"book":"Mark","chapter":6,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Jesus Would not be Made King — Walks on the Sea — Doubting Peter's Adventure — Jesus Exalts Faith.","source":"Matthew 14, 22-32: Mark 6, 45-53: John 6, 15-21.","items":[{"number":127,"reference":"","text":"Be of good cheer; it is I: be not afraid.","id":"saying-127","section_index":32,"contexts":[{"book":"Matthew","chapter":14,"verse":27,"matched":true},{"book":"Mark","chapter":6,"verse":50,"matched":true},{"book":"John","chapter":6,"verse":1,"matched":false}]},{"number":128,"reference":"","text":"Come.","id":"saying-128","section_index":32,"contexts":[{"book":"Matthew","chapter":14,"verse":1,"matched":false},{"book":"Mark","chapter":6,"verse":1,"matched":false},{"book":"John","chapter":6,"verse":1,"matched":false}]},{"number":129,"reference":"","text":"O thou of little faith, wherefore didst thou doubt?","id":"saying-129","section_index":32,"contexts":[{"book":"Matthew","chapter":14,"verse":31,"matched":true},{"book":"Mark","chapter":6,"verse":1,"matched":false},{"book":"John","chapter":6,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"\"I Am the Bread of Life\" — In the Synagogue: To the People, to the Disciples, to the Twelve: \"One of You is a Devil\" — Many Disciples Fall Away.","source":"John 6, 22-71.","items":[{"number":130,"reference":"","text":"Verily, verily, I say unto you, ye seek me, not because ye saw the miracles, but because ye did eat of the loaves, and were filled. Labor not for the meat which perisheth, but for the meat which endureth unto everlasting life, which the Son of man shall give unto you: for him hath God the Father sealed.","id":"saying-130","section_index":33,"contexts":[{"book":"John","chapter":6,"verse":1,"matched":false}]},{"number":131,"reference":"","text":"This is the work of God, that ye believe on him whom he hath sent.","id":"saying-131","section_index":33,"contexts":[{"book":"John","chapter":6,"verse":29,"matched":true}]},{"number":132,"reference":"","text":"Verily, verily, I say unto you, Moses gave you not that bread from heaven; but my Father giveth you the true bread from heaven. For the bread of God is he which cometh down from heaven, and giveth life unto the world.","id":"saying-132","section_index":33,"contexts":[{"book":"John","chapter":6,"verse":33,"matched":true}]},{"number":133,"reference":"","text":"I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst. But I said unto you, That ye also have seen me, and believe not. All that the Father giveth me shall come to me; and him that cometh to me I will in no wise cast out. For I came down from heaven, not to do mine own will, but the will of him that sent me. And this is the Father's will which hath sent me, that of all which he hath given me I should lose nothing, but should raise it up again at the last day. And this is the will of him that sent me, that every one which seeth the Son, and believeth on him, may have everlasting life: and I will raise him up at the last day.","id":"saying-133","section_index":33,"contexts":[{"book":"John","chapter":6,"verse":36,"matched":true}]},{"number":134,"reference":"","text":"Murmur not among yourselves. No man can come to me, except the Father which hath sent me draw him: and I will raise him up at the last day. It is written in the prophets, And they shall be all taught of God. Every man therefore that hath heard, and hath learned of the Father, cometh unto me. Not that any man hath seen the Father, save he which is of God, he hath seen the Father. Verily, verily, I say unto you, He that believeth on me hath everlasting life. I am that bread of life. Your fathers did eat manna in the wilderness, and are dead. This is the bread which cometh down from heaven, that a man may eat thereof, and not die. I am the living bread which came down from heaven: if any man eat of this bread, he shall live forever: and the bread that I will give is my flesh, which I will give for the life of the world.","id":"saying-134","section_index":33,"contexts":[{"book":"John","chapter":6,"verse":44,"matched":true}]},{"number":135,"reference":"","text":"Verily, verily, I say unto you, Except ye eat the flesh of the Son of man, and drink his blood, ye have no life in you. Whoso eateth my flesh, and drinketh my blood, hath eternal life; and I will raise him up at the last day. For my flesh is meat indeed, and my blood is drink indeed. He that eateth my flesh, and drinketh my blood, dwelleth in me, and I in him. As the living Father hath sent me, and I live by the Father, so he that eateth me, even he shall live by me. This is that bread which came down from heaven: not as your fathers did eat manna, and are dead: he that eateth of this bread shall live for ever.","id":"saying-135","section_index":33,"contexts":[{"book":"John","chapter":6,"verse":54,"matched":true}]},{"number":136,"reference":"","text":"Doth this offend you? What and if ye shall see the Son of man ascend up where he was before? It is the Spirit that quickeneth; the flesh profiteth nothing: the words that I speak unto you, they are spirit, and they are life. But there are some of you that believe not.","id":"saying-136","section_index":33,"contexts":[{"book":"John","chapter":6,"verse":62,"matched":true}]},{"number":137,"reference":"","text":"Therefore said I unto you, that no man can come unto me, except it were given unto him of my Father.","id":"saying-137","section_index":33,"contexts":[{"book":"John","chapter":6,"verse":65,"matched":true}]},{"number":138,"reference":"","text":"Will ye also go away?","id":"saying-138","section_index":33,"contexts":[{"book":"John","chapter":6,"verse":67,"matched":true}]},{"number":139,"reference":"","text":"Have I not chosen you twelve, and one of you is a devil?","id":"saying-139","section_index":33,"contexts":[{"book":"John","chapter":6,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Pharisees Querulous — Tradition of the Elders: Unwashen Hands — Washing of Pots not the Whole of Godliness — Blind Leaders of the Blind.","source":"Mark 7, 1-23: Matthew 15, 1-20.","items":[{"number":140,"reference":"","text":"Why do ye also transgress the commandment of God by your tradition? Full well ye reject the commandment of God, that ye may keep your tradition. For God commanded, saying (Moses said), Honor thy father and thy mother: and, Whoso curseth father or mother, let him die the death. But ye say, If a man shall say (Whosoever shall say) to his father or his mother, It is Corban, that is to say, a gift, by whatsoever thou mightest be profited by me; and honor not his father or his mother: he shall be free. And ye suffer him no more to do aught for his father or his mother; making the word of God of none effect through your tradition, which ye have delivered; and many such like things do ye. Thus have ye made the commandment of God of none effect by your tradition. Well hath Elias prophesied of you hypocrites, as it is written, This people draweth night unto me with their mouth, this people honoreth me with their lips; but their heart is far from me. Howbeit in vain do they worship me, teaching for doctrines the commandments of men. Ye hypocrites! For, laying aside the commandment of God, ye hold the tradition of men, as the washing of pots and cups: and many other like things ye do.","id":"saying-140","section_index":34,"contexts":[{"book":"Mark","chapter":7,"verse":7,"matched":true},{"book":"Matthew","chapter":15,"verse":1,"matched":false}]},{"number":141,"reference":"","text":"Hearken unto me every one of you. Hear, and understand. Not that which goeth into the mouth defileth a man. There is nothing from without a man, that entering into him can defile him; but the things which come out of him, those are they that defile the man. If any man have ears to hear, let him hear.","id":"saying-141","section_index":34,"contexts":[{"book":"Mark","chapter":7,"verse":15,"matched":true},{"book":"Matthew","chapter":15,"verse":1,"matched":false}]},{"number":142,"reference":"","text":"Are ye also yet so without understanding? Do not ye yet perceive that whatsoever thing from without entereth into a man, entereth in at the mouth, goeth into the belly, and is cast out into the draught, purging all meats? It entereth not into his heart; it cannot defile him. But those things which proceed out of the mouth come forth from the heart; and they defile the man: for from within, out of the heart of men, proceed evil thoughts, adulteries, fornications, murders, thefts, covetousness, wickedness, false witness, deceit, lasciviousness, an evil eye, blasphemies, pride, foolishness: all these evil things come from within, and these are the things which defile the man; but to eat with unwashen hands defileth not a man.","id":"saying-142","section_index":34,"contexts":[{"book":"Mark","chapter":7,"verse":21,"matched":true},{"book":"Matthew","chapter":15,"verse":18,"matched":true}]},{"number":143,"reference":"","text":"Every plant which my heavenly Father hath not planted, shall be rooted up. Let them alone: they be blind leaders of the blind. And if the blind lead the blind, both shall fall into the ditch.","id":"saying-143","section_index":34,"contexts":[{"book":"Matthew","chapter":15,"verse":14,"matched":true},{"book":"Mark","chapter":7,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Syrophenician's Daughter Healed — A Deaf Mute Hears and Talks.","source":"Matthew 15, 21-28: Mark 7, 24-36.","items":[{"number":144,"reference":"","text":"I am not sent but unto the lost sheep of the house of Israel.","id":"saying-144","section_index":35,"contexts":[{"book":"Matthew","chapter":15,"verse":24,"matched":true},{"book":"Mark","chapter":7,"verse":1,"matched":false}]},{"number":145,"reference":"","text":"Let the children first be filled: for it is not meet to take the children's bread, and to cast it unto the dogs.","id":"saying-145","section_index":35,"contexts":[{"book":"Mark","chapter":7,"verse":27,"matched":true},{"book":"Matthew","chapter":15,"verse":1,"matched":false}]},{"number":146,"reference":"","text":"O woman, great is thy faith: be it unto thee even as thou wilt. For this saying go thy way; the devil is gone out of thy daughter.","id":"saying-146","section_index":35,"contexts":[{"book":"Matthew","chapter":15,"verse":1,"matched":false},{"book":"Mark","chapter":7,"verse":1,"matched":false}]},{"number":147,"reference":"","text":"Be opened.","id":"saying-147","section_index":35,"contexts":[{"book":"Matthew","chapter":15,"verse":1,"matched":false},{"book":"Mark","chapter":7,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Seven Loaves, a Few Fishes — Test of Faith — Leaven of the Pharisees — The Bethsaidan's Sight Restored.","source":"Mark 8, 1-26: Matthew 15, 32-39; John 6, 1-12.","items":[{"number":148,"reference":"","text":"I have compassion on the multitude, because they have now been with me three days, and have nothing to eat: and if I send them away fasting to their own houses, they will faint by the way.","id":"saying-148","section_index":36,"contexts":[{"book":"Mark","chapter":8,"verse":2,"matched":true},{"book":"Matthew","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":6,"verse":1,"matched":false}]},{"number":149,"reference":"","text":"I will not send them away fasting, lest they faint in the way. How many loaves have ye?","id":"saying-149","section_index":36,"contexts":[{"book":"Mark","chapter":8,"verse":1,"matched":false},{"book":"Matthew","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":6,"verse":1,"matched":false}]},{"number":150,"reference":"","text":"Why doth this generation seek after a sign? verily I say unto you, There shall no sign be given unto this generation. When it is evening, ye say, It will be fair weather: for the sky is red. And in the morning, It will be foul weather to day: for the sky is red and lowering. O ye hypocrites, ye can discern the face of the sky; but can ye not discern the signs of the times? A wicked and adulterous generation seeketh after a sign; and there shall no sign be given unto it, but the sign of the prophet Jonas.","id":"saying-150","section_index":36,"contexts":[{"book":"Mark","chapter":8,"verse":1,"matched":false},{"book":"Matthew","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":6,"verse":1,"matched":false}]},{"number":151,"reference":"","text":"Take heed and beware of the leaven of the Pharisees and of the Sadducees, and of the leaven of Herod.","id":"saying-151","section_index":36,"contexts":[{"book":"Mark","chapter":8,"verse":1,"matched":false},{"book":"Matthew","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":6,"verse":1,"matched":false}]},{"number":152,"reference":"","text":"O ye of little faith, why reason ye among yourselves, because ye have brought no bread? Perceive ye not yet, neither understand? Have ye your heart yet hardened? Having eyes, see ye not? and having ears, hear ye not? and do ye not remember? Do ye not understand, neither remember the five loaves of the five thousand, and how many baskets ye took up? Neither the seven loaves of the four thousand, and how many baskets ye took up? When I brake the five loaves among the five thousand, how many baskets full of fragments took ye up?","id":"saying-152","section_index":36,"contexts":[{"book":"Mark","chapter":8,"verse":18,"matched":true},{"book":"Matthew","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":6,"verse":1,"matched":false}]},{"number":153,"reference":"","text":"And when the seven among four thousand, how many baskets full of fragments took ye up?","id":"saying-153","section_index":36,"contexts":[{"book":"Mark","chapter":8,"verse":20,"matched":true},{"book":"Matthew","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":6,"verse":1,"matched":false}]},{"number":154,"reference":"","text":"How is it that ye do not understand that I spake it not to you concerning bread, that ye should beware of the leaven of the Pharisees and of the Sadducees?","id":"saying-154","section_index":36,"contexts":[{"book":"Mark","chapter":8,"verse":1,"matched":false},{"book":"Matthew","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":6,"verse":1,"matched":false}]},{"number":155,"reference":"","text":"Neither go into the town, nor tell it to any in the town.","id":"saying-155","section_index":36,"contexts":[{"book":"Mark","chapter":8,"verse":26,"matched":true},{"book":"Matthew","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":6,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Christ Discloses his Sonship — Advances Peter — Foretells his own Fate — \"What Shall it Profit a Man.\"","source":"Matthew 16, 13-28: Mark 8, 27-38; 9, 1: Luke 9, 18-27.","items":[{"number":156,"reference":"","text":"Whom do men say that I, the Son of man, am? Whom say the people that I am?","id":"saying-156","section_index":37,"contexts":[{"book":"Matthew","chapter":16,"verse":1,"matched":false},{"book":"Mark","chapter":8,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":9,"verse":1,"matched":false}]},{"number":157,"reference":"","text":"But whom say ye that I am?","id":"saying-157","section_index":37,"contexts":[{"book":"Matthew","chapter":16,"verse":15,"matched":true},{"book":"Mark","chapter":8,"verse":29,"matched":true},{"book":"Luke","chapter":9,"verse":20,"matched":true},{"book":"Mark","chapter":9,"verse":1,"matched":false}]},{"number":158,"reference":"","text":"Blessed art thou, Simon Bar-jona: for flesh and blood hath not revealed it unto thee, but my Father which is in heaven. And I say unto thee, That thou art Peter, and upon this rock I will build my church; and the gates of hell shall not prevail against it. And I will give unto thee the keys of the kingdom of heaven: and whatsoever thou shalt bind on earth, shall be bound in heaven; and whatsoever thou shalt loose on earth shall be loosed in heaven.","id":"saying-158","section_index":37,"contexts":[{"book":"Matthew","chapter":16,"verse":19,"matched":true},{"book":"Mark","chapter":8,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":9,"verse":1,"matched":false}]},{"number":159,"reference":"","text":"The Son of man must suffer many things, and be rejected of the elders and chief priests and scribes, and be slain, and be raised the third day.","id":"saying-159","section_index":37,"contexts":[{"book":"Luke","chapter":9,"verse":22,"matched":true},{"book":"Matthew","chapter":16,"verse":1,"matched":false},{"book":"Mark","chapter":8,"verse":1,"matched":false},{"book":"Mark","chapter":9,"verse":1,"matched":false}]},{"number":160,"reference":"","text":"Get thee behind me, Satan: thou are an offence unto me: for thou savorest not the things that be of God, but the things that be of men.","id":"saying-160","section_index":37,"contexts":[{"book":"Matthew","chapter":16,"verse":1,"matched":false},{"book":"Mark","chapter":8,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":9,"verse":1,"matched":false}]},{"number":161,"reference":"","text":"If any man will come after me, whosoever will, let him deny himself, and take up his cross daily, and follow me. For whosoever will save his life shall lose it: but whosoever will lose his life for my sake and the gospel's, the same shall save it. For what shall it profit a man, what is a man advantaged, if he gain the whole world, and lose himself, lose his own soul? or be cast away? Or what shall a man give in exchange for his soul? For the Son of man shall come in the glory of his Father with his angels; and then he shall reward every man according to his works. Whosoever therefore shall be ashamed of me and of my words, in this adulterous and sinful generation, of him also shall the Son of man be ashamed, when he shall come in his own glory: and cometh in the glory of his Father with his holy angels.","id":"saying-161","section_index":37,"contexts":[{"book":"Matthew","chapter":16,"verse":27,"matched":true},{"book":"Mark","chapter":8,"verse":37,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":9,"verse":1,"matched":false}]},{"number":162,"reference":"","text":"But I tell you of a truth, there be some standing here which shall not taste of death, till they have seen the kingdom of God come with power, the Son of man coming in his kingdom.","id":"saying-162","section_index":37,"contexts":[{"book":"Matthew","chapter":16,"verse":1,"matched":false},{"book":"Mark","chapter":8,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":9,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Jesus Transfigured — Moses and Elias Appear — A Lunatic Cured: \"Help Thou Mine Unbelief.\"","source":"Luke 9, 28-42: Matthew 17, 1-21: Mark 9, 2-29.","items":[{"number":163,"reference":"","text":"Arise, and be not afraid.","id":"saying-163","section_index":38,"contexts":[{"book":"Matthew","chapter":17,"verse":7,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":9,"verse":1,"matched":false}]},{"number":164,"reference":"","text":"Tell the vision to no man, until the Son of man be risen again from the dead.","id":"saying-164","section_index":38,"contexts":[{"book":"Matthew","chapter":17,"verse":9,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Mark","chapter":9,"verse":1,"matched":false}]},{"number":165,"reference":"","text":"Elias verily cometh first, and restoreth all things; and how it is written of the Son of man, that he must suffer many things, and be set at nought. But I say unto you, That Elias is indeed come already, and they knew him not; and they have done unto him whatsoever they listed, as it is written of him. Likewise shall also the Son of man suffer of them.","id":"saying-165","section_index":38,"contexts":[{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false},{"book":"Mark","chapter":9,"verse":1,"matched":false}]},{"number":166,"reference":"","text":"What question ye with them?","id":"saying-166","section_index":38,"contexts":[{"book":"Mark","chapter":9,"verse":16,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false}]},{"number":167,"reference":"","text":"O faithless and perverse generation, how long shall I be with you? How long shall I suffer you? Bring thy son hither to me.","id":"saying-167","section_index":38,"contexts":[{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false},{"book":"Mark","chapter":9,"verse":1,"matched":false}]},{"number":168,"reference":"","text":"How long is it ago since this came unto him?","id":"saying-168","section_index":38,"contexts":[{"book":"Mark","chapter":9,"verse":21,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false}]},{"number":169,"reference":"","text":"If thou canst believe, all things are possible to him that believeth.","id":"saying-169","section_index":38,"contexts":[{"book":"Mark","chapter":9,"verse":23,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false}]},{"number":170,"reference":"","text":"Thou dumb and deaf spirit, I charge thee, come out of him, and enter no more into him.","id":"saying-170","section_index":38,"contexts":[{"book":"Mark","chapter":9,"verse":25,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false}]},{"number":171,"reference":"","text":"Because of your unbelief: for verily I say unto you, If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence; and it shall remove; and nothing shall be impossible unto you. Howbeit this kind goeth not out, can come forth, by nothing, but by prayer and fasting.","id":"saying-171","section_index":38,"contexts":[{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false},{"book":"Mark","chapter":9,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Jesus Foretells his Death and Resurrection — Exhorts to Humility — Tribute: the Fish and the Coin.","source":"Mark 9, 30-37: Luke 9, 44-48: Matthew 17, 22-27.","items":[{"number":172,"reference":"","text":"Let these sayings sink down into your ears: for the Son of man shall be betrayed, and delivered into the hands of men: and they shall kill him; and the third day after that he is killed, he shall be raised again.","id":"saying-172","section_index":39,"contexts":[{"book":"Mark","chapter":9,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false}]},{"number":173,"reference":"","text":"What was it that ye disputed among yourselves by the way?","id":"saying-173","section_index":39,"contexts":[{"book":"Mark","chapter":9,"verse":33,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false}]},{"number":174,"reference":"","text":"If any man desire to be first, the same shall be last of all.","id":"saying-174","section_index":39,"contexts":[{"book":"Mark","chapter":9,"verse":35,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false}]},{"number":175,"reference":"","text":"Whosoever shall receive this child in my name, receiveth me; whosoever shall receive one of such children in my name, receiveth me: and whosoever shall receive me, receiveth me not, but him that sent me: for he that is least among you all, the same shall be great.","id":"saying-175","section_index":39,"contexts":[{"book":"Mark","chapter":9,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false}]},{"number":176,"reference":"","text":"What thinkest thou, Simon? Of whom do the kings of the earth take custom or tribute? of their own children, or of strangers?","id":"saying-176","section_index":39,"contexts":[{"book":"Matthew","chapter":17,"verse":25,"matched":true},{"book":"Mark","chapter":9,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false}]},{"number":177,"reference":"","text":"Then are the children free. Notwithstanding, lest we should offend them, go thou to the sea, and cast a hook, and take up the fish that first cometh up; and when thou has opened his mouth, thou shalt find a piece of money: that take, and give unto them for me and thee.","id":"saying-177","section_index":39,"contexts":[{"book":"Mark","chapter":9,"verse":1,"matched":false},{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Matthew","chapter":17,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"John Answered: \"Forbid Him Not\" — Salt — \"have Peace with One Another.\"","source":"Mark 9, 38-50: Luke 9, 49-50.","items":[{"number":178,"reference":"","text":"Forbid him not: for there is no man which shall do a miracle in my name, that can lightly speak evil of me. For he that is not against us is for us, is on our part. For whosoever shall give you a cup of water to drink in my name, because ye belong to Christ, verily I say unto you, he shall not lose his reward. And whosoever shall offend one of these little ones that believe in me, it is better for him that a millstone were hanged about his neck, and he were cast into the sea. And if thy hand offend thee, cut it off: it is better for thee to enter into life maimed, than having two hands to go into hell, into the fire that never shall be quenched: where their worm dieth not, and the fire is not quenched. And if thy foot offend thee, cut it off: it is better for thee to enter halt into life, than having two feet to be cast into hell, into the fire that never shall be quenched: where their worm dieth not, and the fire is not quenched. And if thine eye offend thee, pluck it out: it is better for thee to enter into the kingdom of God with one eye, than having two eyes to be cast into hell fire: where their worm dieth not, and the fire is not quenched. For every one shall be salted with fire, and every sacrifice shall be salted with salt. Salt is good: but if the salt have lost his saltness, wherewith will ye season it? Have salt in yourselves, and have peace one with another.","id":"saying-178","section_index":40,"contexts":[{"book":"Mark","chapter":9,"verse":41,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"\"Except Ye Become as Little Children\" — Humility and Forgiveness — Parables:The Ninety and Nine, The Wicked Servant — \"Where Two or Three Are Gathered Together.\"","source":"Matthew 18, 1-35.","items":[{"number":179,"reference":"","text":"Verily I say unto you, Except ye be converted, and become as little children, ye shall not enter into the kingdom of heaven. Whosoever therefore shall humble himself as this little child, the same is greatest in the kingdom of heaven. And whoso shall receive one such little child in my name receiveth me. But whoso shall offend one of these little ones which believe in me, it were better for him that a millstone were hanged about his neck, and that he were drowned in the depth of the sea. Woe unto the world because of offences! for it must needs be that offences come; but woe to that man by whom the offence cometh! Wherefore, if thy hand or thy foot offend thee, cut them off, and cast them from thee: it is better for thee to enter into life halt or maimed, rather than having' two hands or two feet to be cast into everlasting fire. And if thine eye offend thee, pluck it out, and cast it from thee: it is better for thee to enter into life with one eye, rather than having two eyes to be cast into hell fire. Take heed that ye despise not one of these little ones; for I say unto you, That in heaven their angels do always behold the face of my Father which is in heaven. For the Son of man is come to save that which was lost. How think ye? if a man have a hundred sheep, and one of them be gone astray, doth he not leave the ninety and nine, and goeth into the mountains, and seeketh that which is gone astray? And if so be that he find it, verily I say unto you, he rejoiceth more of that sheep, than of the ninety and nine which went not astray. Even so it is not the will of your Father which is in heaven, that one of these little ones should perish. Moreover if thy brother shall trespass against thee, go and tell him his fault between thee and him alone: if he shall hear thee, thou hast gained thy brother. But if he will not hear thee, then take with thee one or two more, that in the mouth of two or three witnesses every word may be established. And if he shall neglect to hear them, tell it unto the church: but if he neglect to hear the church, let him be unto thee as a heathen man and a publican. Verily I say unto you, Whatsoever ye shall bind on earth shall be bound in heaven: and whatsoever ye shall loose on earth shall be loosed in heaven. Again I say unto you, That if two of you shall agree on earth as touching any thing that they shall ask, it shall be done for them of my Father which is in heaven. For where two or three are gathered together in my name, there am I in the midst of them.","id":"saying-179","section_index":41,"contexts":[{"book":"Matthew","chapter":18,"verse":4,"matched":true}]},{"number":180,"reference":"","text":"I say not unto thee, Until seven times: but, Until seventy times seven. Therefore is the kingdom of heaven likened unto a certain king, which would take account of his servants. And when he had begun to reckon, one was brought unto him, which owed him ten thousand talents. But forasmuch as he had not to pay, his lord commanded him to be sold, and his wife, and children, and all that he had, and payment to be made. The servant therefore fell down, and worshipped him, saying, Lord, have patience with me, and I will pay thee all. Then the lord of that servant was moved with compassion and loosed him, and forgave him the debt. But the same servant went out, and found one of his fellow servants, which owed him a hundred pence: and he laid hands on him, and took him by the throat, saying, Pay me that thou owest. And his fellow servant fell down at his feet, and besought him, saying, Have patience with me, and I will pay thee all. And he would not: but went and cast him into prison, till he should pay the debt. So when his fellow servants saw what was done, they were very sorry, and came and told unto their lord all that was done. Then his lord, after that he had called him, said unto him, O thou wicked servant, I forgave thee all that debt, because thou desiredst me; shouldest not thou also have had compassion on thy fellow servant, even as I had pity on thee? And his lord was wroth, and delivered him to the tormentors, till he should pay all that was due unto him. So likewise shall my heavenly Father do also unto you, if ye from your hearts forgive not every one his brother their trespasses.","id":"saying-180","section_index":41,"contexts":[{"book":"Matthew","chapter":18,"verse":23,"matched":true}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"At the Feast of the Tabernacle — Opinions Divided.","source":"John 7, 1-46, 53; 8, 1.","items":[{"number":181,"reference":"","text":"My time is not yet come: but your time is always ready. The world cannot hate you; but me it hateth, because I testify of it, that the works thereof are evil. Go ye up unto this feast: for my time is not yet full come.","id":"saying-181","section_index":42,"contexts":[{"book":"John","chapter":7,"verse":7,"matched":true},{"book":"John","chapter":8,"verse":1,"matched":false}]},{"number":182,"reference":"","text":"My doctrine is not mine, but his that sent me. If any man will do his will, he shall know of the doctrine, whether it be of God, or whether I speak of myself. He that speaketh of himself seeketh his own glory: but he that seeketh his glory that sent him, the same is true, and no unrighteousness is in him. Did not Moses give you the law, and yet none of you keepeth the law? Why go ye about to kill me?","id":"saying-182","section_index":42,"contexts":[{"book":"John","chapter":7,"verse":17,"matched":true},{"book":"John","chapter":8,"verse":1,"matched":false}]},{"number":183,"reference":"","text":"I have done one work, and ye all marvel. Moses therefore gave unto you circumcision (not because it is of Moses, but of the fathers); and ye on the sabbath day circumcise a man. If a man on the sabbath day receive circumcision, that the law of Moses should not be broken; are ye angry at me, because I have made a man every whit whole on the sabbath day? Judge not according to the appearance, but judge righteous judgment.","id":"saying-183","section_index":42,"contexts":[{"book":"John","chapter":7,"verse":22,"matched":true},{"book":"John","chapter":8,"verse":1,"matched":false}]},{"number":184,"reference":"","text":"Ye both know me, and ye know whence I am: and I am not come of myself, but he that sent me is true, whom ye know not. But I know him; for I am from him, and he hath sent me.","id":"saying-184","section_index":42,"contexts":[{"book":"John","chapter":7,"verse":29,"matched":true},{"book":"John","chapter":8,"verse":1,"matched":false}]},{"number":185,"reference":"","text":"Yet a little while am I with you, and then I go unto him that sent me. Ye shall seek me, and shall not find me: and where I am, thither ye cannot come.","id":"saying-185","section_index":42,"contexts":[{"book":"John","chapter":7,"verse":34,"matched":true},{"book":"John","chapter":8,"verse":1,"matched":false}]},{"number":186,"reference":"","text":"If any man thirst, let him come unto me, and drink. He that believeth on me, as the Scripture hath said, out of his belly shall flow rivers of living water.","id":"saying-186","section_index":42,"contexts":[{"book":"John","chapter":7,"verse":38,"matched":true},{"book":"John","chapter":8,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"A Woman's Accusers Shamed — Christ Confutes the Jews — \"I am the Light of the World\" — \"The Truth Shall Make You Free\" — \"I Seek Not Mine Own Glory\" — \"Before Abraham Was, I Am\" — He Eludes the Mob.","source":"John 8, 2-59.","items":[{"number":187,"reference":"","text":"He that is without sin among you, let him first cast a stone at her.","id":"saying-187","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":7,"matched":true}]},{"number":188,"reference":"","text":"Woman, where are those thine accusers? hath no man condemned thee?","id":"saying-188","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":10,"matched":true}]},{"number":189,"reference":"","text":"Neither do I condemn thee: go, and sin no more.","id":"saying-189","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":11,"matched":true}]},{"number":190,"reference":"","text":"I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life.","id":"saying-190","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":12,"matched":true}]},{"number":191,"reference":"","text":"Though I bear record of myself, yet my record is true: for I know whence I came, and whither I go; but ye cannot tell whence I come, and whither I go. Ye judge after the flesh; I judge no man. And yet if I judge, my judgment is true: for I am not alone, but I and the Father that sent me. It is also written in your law, that the testimony of two men is true. I am one that bear witness of myself, and the Father that sent me beareth witness of me.","id":"saying-191","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":15,"matched":true}]},{"number":192,"reference":"","text":"Ye neither know me, nor my Father: if ye had known me, ye should have known my Father also.","id":"saying-192","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":19,"matched":true}]},{"number":193,"reference":"","text":"I go my way, and ye shall seek me, and shall die in your sins: whither I go, ye cannot come.","id":"saying-193","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":21,"matched":true}]},{"number":194,"reference":"","text":"Ye are from beneath; I am from above: ye are of this world; I am not of this world. I said therefore unto you that ye shall die in your sins: for if ye believe not that I am he, ye shall die in your sins.","id":"saying-194","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":24,"matched":true}]},{"number":195,"reference":"","text":"Even the same that I said unto you from the beginning. I have many things to say and to judge of you: but he that sent me is true; and I speak to the world those things which I have heard of him.","id":"saying-195","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":26,"matched":true}]},{"number":196,"reference":"","text":"When ye have lifted up the Son of man, then shall ye know that I am he, and that I do nothing of myself; but as my Father hath taught me, I speak these things. And he that sent me is with me: the Father hath not left me alone; for I do always those things that please him.","id":"saying-196","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":29,"matched":true}]},{"number":197,"reference":"","text":"If ye continue in my word, then are ye my disciples indeed; and ye shall know the truth, and the truth shall make you free.","id":"saying-197","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":32,"matched":true}]},{"number":198,"reference":"","text":"Verily, verily, I say unto you, Whosoever committeth sin is the servant of sin. And the servant abideth not in the house for ever: but the Son abideth ever. If the Son therefore shall make you free, ye shall be free indeed. I know that ye are Abraham's seed; but ye seek to kill me, because my word hath no place in you. I speak that which I have seen with my Father: and ye do that which ye have seen with your father.","id":"saying-198","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":35,"matched":true}]},{"number":199,"reference":"","text":"If ye were Abraham's children, ye would do the works of Abraham. But now ye seek to kill me, a man that hath told you the truth, which I have heard of God: this did not Abraham. Ye do the deeds of your father.","id":"saying-199","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":40,"matched":true}]},{"number":200,"reference":"","text":"If God were your Father, ye would love me: for I proceeded forth and came from God; neither came I of myself, but he sent me. Why do ye not understand my speech? even because ye cannot hear my word. Ye are of your father the devil, and the lusts of your father ye will do: he was a murderer from the beginning, and abode not in the truth, because there is no truth in him. When he speaketh a lie, he speaketh of his own: for he is a liar, and the father of it. And because I tell you the truth, ye believe me not. Which of you convinceth me of sin? And if I say the truth, why do ye not believe me? He that is of God heareth God's words: ye therefore hear them not, because ye are not of God.","id":"saying-200","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":43,"matched":true}]},{"number":201,"reference":"","text":"I have not a devil; but I honor my Father, and ye do dishonor me. And I seek not mine own glory: there is one that seeketh and judgeth. Verily, verily, I say unto you, if a man keep my saying, he shall never see death.","id":"saying-201","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":50,"matched":true}]},{"number":202,"reference":"","text":"If I honor myself, my honor is nothing: it is my Father that honoreth me; of whom ye say, that he is your God: yet ye have not known him: but I know him: and if I should say, I know him not, I shall be a liar like unto you; but I know him, and keep his saying. Your father Abraham rejoiced to see my day; and he saw it, and was glad.","id":"saying-202","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":55,"matched":true}]},{"number":203,"reference":"","text":"Verily, verily I say unto you, Before Abraham was, I am.","id":"saying-203","section_index":43,"contexts":[{"book":"John","chapter":8,"verse":58,"matched":true}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Jesus Heals Man Born Blind — The Jews Cross- Examine the Man — Again: \"I Am the Light of the World\" — Parable: \"I Am the Door. I Am the Good Shepherd\" — Winter Feast of the Dedication — Again He Eludes the Jews.","source":"John 9, 1-41; 10, 1-18; 22-40.","items":[{"number":204,"reference":"","text":"Neither hath this man sinned, nor his parents: but that the works of God should be made manifest in him. I must work the works of him that sent me, while it is day: the night cometh, when no man can work. As long as I am in the world, I am the light of the world.","id":"saying-204","section_index":44,"contexts":[{"book":"John","chapter":9,"verse":4,"matched":true},{"book":"John","chapter":10,"verse":1,"matched":false}]},{"number":205,"reference":"","text":"Go, wash in the pool of Siloam.","id":"saying-205","section_index":44,"contexts":[{"book":"John","chapter":9,"verse":7,"matched":true},{"book":"John","chapter":10,"verse":1,"matched":false}]},{"number":206,"reference":"","text":"Dost thou believe on the Son of God?","id":"saying-206","section_index":44,"contexts":[{"book":"John","chapter":9,"verse":35,"matched":true},{"book":"John","chapter":10,"verse":1,"matched":false}]},{"number":207,"reference":"","text":"Thou hast both seen him, and it is he that talketh with thee.","id":"saying-207","section_index":44,"contexts":[{"book":"John","chapter":9,"verse":37,"matched":true},{"book":"John","chapter":10,"verse":1,"matched":false}]},{"number":208,"reference":"","text":"For judgment I am come into this world, that they which see not might see; and that they which see might be made blind.","id":"saying-208","section_index":44,"contexts":[{"book":"John","chapter":9,"verse":39,"matched":true},{"book":"John","chapter":10,"verse":1,"matched":false}]},{"number":209,"reference":"","text":"If ye were blind, ye should have no sin: but now ye say, We see; therefore your sin remaineth.","id":"saying-209","section_index":44,"contexts":[{"book":"John","chapter":9,"verse":41,"matched":true},{"book":"John","chapter":10,"verse":1,"matched":false}]},{"number":210,"reference":"","text":"Verily, verily, I say unto you, He that entereth not by the door into the sheepfold, but climbeth up some other way, the same is a thief and a robber. But he that entereth in by the door is the shepherd of the sheep. To him the porter openeth; and the sheep hear his voice: and he calleth his own sheep by name, and leadeth them out. And when he putteth forth his own sheep, he goeth before them, and the sheep follow him: for they know his voice. And a stranger will they not follow, but will flee from him: for they know not the voice of strangers.","id":"saying-210","section_index":44,"contexts":[{"book":"John","chapter":10,"verse":1,"matched":true},{"book":"John","chapter":9,"verse":1,"matched":false}]},{"number":211,"reference":"","text":"Verily, verily, I say unto you, I am the door of the sheep. All that ever came before me are thieves and robbers: but the sheep did not hear them. I am the door: by me if any man enter in, he shall be saved, and shall go in and out, and find pasture. The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly. I am the good shepherd: the good shepherd giveth his life for the sheep. But he that is a hireling, and not the shepherd, whose own the sheep are not, seeth the wolf coming, and leaveth the sheep, and fleeth: and the wolf catcheth them, and scattereth the sheep. The hireling fleeth, because he is a hireling, and careth not for the sheep. I am the good shepherd, and know my sheep, and am known of mine. As the Father knoweth me, even so know I the Father: and I lay down my life for the sheep. And other sheep I have, which are not of this fold: them also I must bring, and they shall hear my voice; and there shall be one fold, and one shepherd. Therefore doth my Father love me, because I lay down my life, that I might take it again. No man taketh it from me, but I lay it down of myself. I have power to lay it down, and I have power to take it again. This commandment have I received of my Father.","id":"saying-211","section_index":44,"contexts":[{"book":"John","chapter":10,"verse":8,"matched":true},{"book":"John","chapter":9,"verse":1,"matched":false}]},{"number":212,"reference":"","text":"I told you, and ye believed not: the works that I do in my Father's name, they bear witness of me. But ye believe not, because ye are not of my sheep, as I said unto you. My sheep hear my voice, and I know them, and they follow me: and I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand. My Father, which gave them me, is greater than all; and no man is able to pluck them out of my Father's hand. I and my Father are one.","id":"saying-212","section_index":44,"contexts":[{"book":"John","chapter":10,"verse":26,"matched":true},{"book":"John","chapter":9,"verse":1,"matched":false}]},{"number":213,"reference":"","text":"Many good works have I shewed you from my Father; for which of those works do ye stone me?","id":"saying-213","section_index":44,"contexts":[{"book":"John","chapter":10,"verse":32,"matched":true},{"book":"John","chapter":9,"verse":1,"matched":false}]},{"number":214,"reference":"","text":"Is it not written in your law, I said, Ye are gods? If he called them gods, unto whom the word of God came, and the Scripture cannot be broken; say ye of him, whom the Father hath sanctified and sent into the world, Thou blasphemest; because I said, I am the Son of God? If I do not the works of my Father, believe me not. But if I do, though ye believe not me, believe the works; that ye may know, and believe, that the Father is in me, and I in him.","id":"saying-214","section_index":44,"contexts":[{"book":"John","chapter":10,"verse":35,"matched":true},{"book":"John","chapter":9,"verse":1,"matched":false}]}],"notes":[],"era":2},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"James and John Rebuked — \"Hath Not Where to Lay His Head\" — The Seventy Sent Two and Two: Return Rejoicing — Explicit Instructions — A Prayer.","source":"Luke 9, 51-62; 10, 1-24.","items":[{"number":215,"reference":"","text":"Ye know not what manner of spirit ye are of. For the Son of man is not come to destroy men's lives, but to save them.","id":"saying-215","section_index":45,"contexts":[{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Luke","chapter":10,"verse":1,"matched":false}]},{"number":216,"reference":"","text":"Foxes have holes, and birds of the air have nests; but the Son of man hath not where to lay his head.","id":"saying-216","section_index":45,"contexts":[{"book":"Luke","chapter":9,"verse":58,"matched":true},{"book":"Luke","chapter":10,"verse":1,"matched":false}]},{"number":217,"reference":"","text":"Follow me.","id":"saying-217","section_index":45,"contexts":[{"book":"Luke","chapter":9,"verse":1,"matched":false},{"book":"Luke","chapter":10,"verse":1,"matched":false}]},{"number":218,"reference":"","text":"Let the dead bury their dead: but go thou and preach the kingdom of God.","id":"saying-218","section_index":45,"contexts":[{"book":"Luke","chapter":9,"verse":60,"matched":true},{"book":"Luke","chapter":10,"verse":1,"matched":false}]},{"number":219,"reference":"","text":"No man, having put his hand to the plough, and looking back, is fit for the kingdom of God.","id":"saying-219","section_index":45,"contexts":[{"book":"Luke","chapter":9,"verse":62,"matched":true},{"book":"Luke","chapter":10,"verse":1,"matched":false}]},{"number":220,"reference":"","text":"The harvest truly is great, but the laborers are few: pray ye therefore the Lord of the harvest, that he would send forth laborers into his harvest. Go your ways: behold, I send you forth as lambs among wolves. Carry neither purse, nor scrip, nor shoes: and salute no man by the way. And into whatsoever house ye enter, first say, Peace be to this house. And if the son of peace be there, your peace shall rest upon it: if not, it shall turn to you again. And in the same house remain, eating and drinking such things as they give: for the laborer is worthy of his hire. Go not from house to house. And into whatsoever city ye enter, and they receive you, eat such things as are set before you: and heal the sick that are therein, and say unto them, The kingdom of God is come nigh unto you. But into whatsoever city ye enter, and they receive you not, go your ways out into the streets of the same, and say, Even the very dust of your city, which cleaveth on us, we do wipe off against you: notwithstanding, be ye sure of this, that the kingdom of God is come nigh unto you. But I say unto you, that it shall be more tolerable in that day for Sodom, than for that city. Woe unto thee, Chorazin! woe unto thee, Bethsaida! for if the mighty works had been done in Tyre and Sidon, which have been done in you, they had a great while ago repented, sitting in sackcloth and ashes. But it shall be more tolerable for Tyre and Sidon at the judgment, than for you. And thou, Capernaum, which art exalted to heaven, shalt be thrust down to hell. He that heareth you heareth me; and he that despiseth you despiseth me; and he that despiseth me despiseth him that sent me.","id":"saying-220","section_index":45,"contexts":[{"book":"Luke","chapter":10,"verse":3,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false}]},{"number":221,"reference":"","text":"I beheld Satan as lightning fall from heaven. Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy; and nothing shall by any means hurt you. Notwithstanding, in this rejoice not, that the spirits are subject unto you; but rather rejoice, because your names are written in heaven.","id":"saying-221","section_index":45,"contexts":[{"book":"Luke","chapter":10,"verse":19,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false}]},{"number":222,"reference":"","text":"I thank thee, O Father, Lord of heaven and earth, that thou hast hid these things from the wise and prudent, and has revealed them unto babes: even so, Father; for so it seemed good in thy sight. All things are delivered to me of my Father: and no man knoweth who the Son is, but the Father; and who the Father is, but the Son, and he to whom the Son will reveal him.","id":"saying-222","section_index":45,"contexts":[{"book":"Luke","chapter":10,"verse":22,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false}]},{"number":223,"reference":"","text":"Blessed are the eyes which see the things that ye see: for I tell you, that many prophets and kings have desired to see those things which ye see, and have not seen them; and to hear those things which ye hear, and have not heard them.","id":"saying-223","section_index":45,"contexts":[{"book":"Luke","chapter":10,"verse":24,"matched":true},{"book":"Luke","chapter":9,"verse":1,"matched":false}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Good Samaritan: A Lawyer Answered.","source":"Luke 10, 25-37.","items":[{"number":224,"reference":"","text":"What is written in the law? how readest thou?","id":"saying-224","section_index":46,"contexts":[{"book":"Luke","chapter":10,"verse":26,"matched":true}]},{"number":225,"reference":"","text":"Thou hast answered right: this do, and thou shalt live.","id":"saying-225","section_index":46,"contexts":[{"book":"Luke","chapter":10,"verse":28,"matched":true}]},{"number":226,"reference":"","text":"A certain man went down from Jerusalem to Jericho, and fell among thieves, which stripped him of his raiment, and wounded him, and departed, leaving him half dead. And by chance there came down a certain priest that way: and when he saw him, he passed by on the other side.And like wise a Levite, when he was at the place, came and looked on him, and passed by on the other side. But a certain Samaritan, as he journeyed, came where he was: and when he saw him, he had compassion on him, and went to him, and bound up his wounds, pouring in oil and wine, and set him on his own beast, and brought him to an inn, and took care of him. And on the morrow when he departed, he took out two pence, and gave them to the host, and said unto him, Take care of him: and whatsoever thou spendest more, when I come again, I will repay thee. Which now of these three, thinkest thou, was neighbor unto him that fell among the thieves?","id":"saying-226","section_index":46,"contexts":[{"book":"Luke","chapter":10,"verse":31,"matched":true}]},{"number":227,"reference":"","text":"Go, and do thou likewise.","id":"saying-227","section_index":46,"contexts":[{"book":"Luke","chapter":10,"verse":37,"matched":true}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"\"When Ye Pray, Say\" (Luke 11:2) — Parables and Precepts — \"Blessed is the Womb that Bare Thee\" — \"A Greater than Solomon is Here\" — Jesus Dines with Pharisee: Chides Pharisees and Lawyers.","source":"Luke 11, 1-13; 27-54.","items":[{"number":228,"reference":"","text":"When ye pray, say, Our Father which art in heaven, Hallowed be thy name. Thy kingdom come. Thy will be done, as in heaven, so in earth. Give us day by day our daily bread. And forgive us our sins; for we also forgive every one that is indebted to us. And lead us not into temptation; but deliver us from evil.","id":"saying-228","section_index":47,"contexts":[{"book":"Luke","chapter":11,"verse":3,"matched":true}]},{"number":229,"reference":"","text":"Which of you shall have a friend, and shall go unto him at midnight, and say unto him, Friend, lend me three loaves; for a friend of mine in his journey is come to me, and I have nothing to set before him? And he from within shall answer and say, Trouble me not: the door is now shut, and my children are with me in bed; I cannot rise and give thee. I say unto you, Though he will not rise and give him, because he is his friend, yet because of his importunity he will rise and give him as many as he needeth. And I say unto you, Ask, and it shall be given you: seek, and ye shall find; knock, and it shall be opened unto you. For every one that asketh receiveth; and he that seeketh findeth; and to him that knocketh it shall be opened. If a son shall ask bread of any of you that is a father, will he give him a stone? or if he ask a fish, will he for a fish give him a serpent? Or, if he shall ask an egg, will he offer him a scorpion? If ye then, being evil, know how to give good gifts unto your children; how much more shall your heavenly Father give the Holy Spirit to them that ask him?","id":"saying-229","section_index":47,"contexts":[{"book":"Luke","chapter":11,"verse":6,"matched":true}]},{"number":230,"reference":"","text":"Yea rather, blessed are they that hear the word of God, and keep it.","id":"saying-230","section_index":47,"contexts":[{"book":"Luke","chapter":11,"verse":28,"matched":true}]},{"number":231,"reference":"","text":"This is an evil generation: they seek a sign; and there shall no sign be given it, but the sign of Jonas the prophet. For as Jonas was a sign unto the Ninevites, so shall also the Son of man be to this generation. The queen of the south shall rise up in the judgment with the men of this generation, and condemn them: for she came from the utmost parts of the earth to hear the wisdom of Solomon; and, behold, a greater than Solomon is here. The men of Nineveh shall rise up in the judgment with this generation, and shall condemn it: for they repented at the preaching of Jonas; and, behold, a greater than Jonas is here. No man, when he hath lighted a candle, putteth it in a secret place, neither under a bushel, but on a candlestick, that they which come in may see the light. The light of the body is the eye: therefore when thine eye is single, thy whole body also is full of light; but when thine eye is evil, thy body also is full of darkness. Take heed therefore that the light which is in thee be not darkness. If thy whole body therefore be full of light, having no part dark, the whole shall be full of light, as when the bright shining of a candle doth give thee light.","id":"saying-231","section_index":47,"contexts":[{"book":"Luke","chapter":11,"verse":30,"matched":true}]},{"number":232,"reference":"","text":"Now do ye Pharisees make clean the outside of the cup and the platter; but your inward part is full of ravening and wickedness. Ye fools, did not he that made that which is without, make that which is within also? But rather give alms of such things as ye have; and, behold, all things are clean unto you. But woe unto you, Pharisees! for ye tithe mint and rue and all manner of herbs, and pass over judgment and the love of God: these ought ye to have done, and not to leave the other undone. Woe unto you, Pharisees! for ye love the uppermost seats in the synagogues, and greetings in the markets. Woe unto you, scribes and Pharisees, hypocrites! for ye are as graves which appear not, and the men that walk over them are not aware of them.","id":"saying-232","section_index":47,"contexts":[{"book":"Luke","chapter":11,"verse":40,"matched":true}]},{"number":233,"reference":"","text":"Woe unto you also, ye lawyers! for ye lade men with burdens grievous to be borne, and ye yourselves touch not the burdens with one of your fingers. Woe unto you! for we build the sepulchres of the prophets, and your fathers killed them. Truly ye bear witness that ye allow the deeds of your fathers: for they indeed killed them, and ye build their sepulchres. Therefore also said the wisdom of God, I will send them prophets and apostles, and some of them they shall slay and persecute: that the blood of all the prophets, which was shed from the foundation of the world, may be required of this generation; from the blood of Abel unto the blood of Zacharias, which perished between the altar and the temple: verily I say unto you, It shall be required of this generation. Woe unto you, lawyers! for ye have taken away the key of knowledge: ye entered not in yourselves, and them that were entering in ye hindered.","id":"saying-233","section_index":47,"contexts":[{"book":"Luke","chapter":11,"verse":48,"matched":true}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Sermon to the Innumerable Multitude: Precepts, Parables: The Sparrows, the Self-Centered Rich Man, the Ravens, the Lilies — \"The Hairs of Your Head are Numbered\" — \"Let Your Light Be Burning.\"","source":"Luke 12, 1-40.","items":[{"number":234,"reference":"","text":"Beware ye of the leaven of the Pharisees, which is hypocrisy. For there is nothing covered, that shall not be revealed; neither hid, that shall not be known. Therefore, whatsoever ye have spoken in darkness shall be heard in the light; and that which ye have spoken in the ear in closets shall be proclaimed upon the housetops. And I say unto you my friend, Be not afraid of them that kill the body, and after that have no more that they can do. But I will forewarn you whom ye shall fear: Fear him, which after he hath killed hath power to cast into hell; yea, I say unto you, Fear him. Are not five sparrows sold for two farthings, and not one of them is forgotten before God? But even the very hairs on your head are all numbered. Fear not therefore; ye are of more value than many sparrows. Also I say unto you, Whosoever shall confess me before men, him shall the Son of man also confess before the angels of God: but he that denieth me before men shall be denied before the angels of God. And whosoever shall speak a word against the Son of man, it shall be forgiven him: but unto him that blasphemeth against the Holy Ghost it shall not be forgiven. And when they bring you unto the synagogues, and unto magistrates, and powers, take ye no thought how or what thing ye shall answer, or what ye shall say: for the Holy Ghost shall teach you in the same hour what ye ought to say.","id":"saying-234","section_index":48,"contexts":[{"book":"Luke","chapter":12,"verse":2,"matched":true}]},{"number":235,"reference":"","text":"Man, who made me a judge or a divider over you?","id":"saying-235","section_index":48,"contexts":[{"book":"Luke","chapter":12,"verse":14,"matched":true}]},{"number":236,"reference":"","text":"Take heed, and beware of covetousness: for a man's life consisteth not in the abundance of the things which he possesseth.","id":"saying-236","section_index":48,"contexts":[{"book":"Luke","chapter":12,"verse":15,"matched":true}]},{"number":237,"reference":"","text":"The ground of a certain rich man brought forth plentifully: and he thought within himself, saying, What shall I do, because I have no room where to bestow my fruits. And he said, This will I do: I will pull down my barns, and build greater and there will I bestow all my fruits and my goods. And I will say to my soul, Soul, thou hast much goods laid up for many years; take thine ease, eat, drink, and be merry. But God said unto him, Thou fool, this night thy soul shall be required of thee: then whose shall those things be, which thou hast provided? So is he that layeth up treasure for himself, and is not rich toward God.","id":"saying-237","section_index":48,"contexts":[{"book":"Luke","chapter":12,"verse":17,"matched":true}]},{"number":238,"reference":"","text":"Therefore I say unto you, Take no thought for your life, what ye shall eat, neither for the body, what ye shall put on. The life is more than meat, and the body is more than raiment. Consider the ravens: for they neither sow nor reap; which neither have storehouse nor barn; and God feedeth them: how much more are ye better than the fowls? And which of you with taking thought can add to his stature one cubit? If ye then be not able to do that thing which is least, why take ye thought for the rest? Consider the lilies how they grow: they toil not, they spin not; and yet I say unto you, that Solomon in all his glory was not arrayed like one of these. If then God so clothe the grass, which is to day in the field, and to morrow is cast into the oven; how much more will he clothe you, O ye of little faith? And seek not ye what ye shall eat, or what ye shall drink, neither be ye of doubtful mind. For all these things do the nations of the world seek after; and your Father knoweth that ye have need of these things. But rather seek ye the kingdom of God; and all these things shall be added unto you. Fear not, little flock; for it is your Father's good pleasure to give you the kingdom. Sell that ye have, and give alms; provide yourselves bags which wax not old, a treasure in the heavens that faileth not, where no thief approacheth, neither moth corrupteth. For where your treasure is, there will your heart be also. Let your loins be girded about, and your lights burning; and ye yourselves like unto men that wait for their lord, when he will return from the wedding; that when he cometh and knocketh, they may open unto him immediately. Blessed are those servants, whom the lord when he cometh shall find watching: verily I say unto you, that he shall gird himself, and make them to sit down to meat, and will come forth and serve them. And if he shall come in the second watch, or come in the third watch, and find them so, blessed are those servants. *And this know, that if the goodman of the house had known what hour the thief would come, he would have watched, and not have suffered his house to be broken through. Be ye therefore ready also; for the Son of man cometh at an hour when ye think not.","id":"saying-238","section_index":48,"contexts":[{"book":"Luke","chapter":12,"verse":23,"matched":true}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Sermon Continued: \"Speakest Thou This Parable to All?\" — \"I Am Come to Send Fire\" — The Face of the Sky — \"Unless Ye Repent\" — The Fig Tree Spared.","source":"Luke 12, 41-59; 13, 1-9.","items":[{"number":239,"reference":"","text":"Who then is that faithful and wise steward, whom his lord shall make ruler over his household, to give them their portion of meat in due season? Blessed is that servant, whom his lord when he cometh shall find so doing. Of a truth I say unto you, that he will make him ruler over all that he hath. But if that servant say in his heart, My lord delayeth his coming; and shall begin to beat the menservants and maidens, and to eat and drink, and to be drunken; the lord of that servant will come in a day when he looketh not for him, and at an hour when he is not aware, and will cut him in sunder, and will appoint him his portion with the unbelievers. And that servant, which knew his lord's will, and prepared not himself, neither did according to his will, shall be beaten with many stripes. But he that knew not, and did commit things worthy of stripes, shall be beaten with few stripes. For unto whomsoever much is given, of him shall be much required; and to whom men have committeth much, of him they will ask more. I am come to send fire on the earth; and what will I, if it be already kindled? But I have a baptism to be baptized with; and how am I straitened till it be accomplished! Suppose ye that I am come to give peace on earth? I tell you, Nay; but rather division: for from henceforth there shall be five in one house divided, three against two, and two against three. The father shall be divided against the son, and the son against the father; the mother against the daughter, and the daughter against the mother; the mother in law against her daughter in law, and the daughter in law against her mother in law.","id":"saying-239","section_index":49,"contexts":[{"book":"Luke","chapter":12,"verse":43,"matched":true},{"book":"Luke","chapter":13,"verse":1,"matched":false}]},{"number":240,"reference":"","text":"When ye see a cloud rise out of the west, straightway ye say, There cometh a shower; and so it is. And when ye see the south wind blow, ye say, There will be heat; and it cometh to pass. Ye hypocrites, ye can discern the face of the sky and of the earth: but how is it that ye do not discern this time? Yea, and why even of yourselves judge ye not what is right? When thou goest with thine adversary to the magistrate, as thou art in the way, give diligence that thou mayest be delivered from him; lest he hale thee to the judge, and the judge deliver thee to the officer, and the officer cast thee into prison. I tell thee, thou shalt not depart thence, till thou hast paid the very last mite.","id":"saying-240","section_index":49,"contexts":[{"book":"Luke","chapter":12,"verse":55,"matched":true},{"book":"Luke","chapter":13,"verse":1,"matched":false}]},{"number":241,"reference":"","text":"Suppose ye that these Galileans were sinners above all Galileans, because they suffered such things? I tell you, Nay: but, except ye repent, ye shall all likewise perish. Or those eighteen, upon whom the tower in Siloam fell, and slew them, think ye that they were sinners above all men that dwelt in Jerusalem? I tell you, Nay: but, except ye repent, ye shall all likewise perish.","id":"saying-241","section_index":49,"contexts":[{"book":"Luke","chapter":13,"verse":3,"matched":true},{"book":"Luke","chapter":12,"verse":1,"matched":false}]},{"number":242,"reference":"","text":"A certain man had a fig tree planted in his vineyard; and he came and sought fruit thereon, and found none. Then said he unto the dresser of his vineyard, Behold, these three years I come seeking fruit on this fig tree, and find none: cut it down; why cumbereth it the ground? And he answering said unto him, Lord, let it alone this year also, till I shall dig about it, and dung it: and if it bear fruit, well: and if not, then after that thou shalt cut it down.","id":"saying-242","section_index":49,"contexts":[{"book":"Luke","chapter":13,"verse":7,"matched":true},{"book":"Luke","chapter":12,"verse":1,"matched":false}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Sabbath Cure of Crippled Woman: Hypocrites Shamed — Parables and Precepts: The Mustard Seed, Leaven.","source":"Luke 13, 10-21.","items":[{"number":243,"reference":"","text":"Woman, thou are loosed from thine infirmity.","id":"saying-243","section_index":50,"contexts":[{"book":"Luke","chapter":13,"verse":1,"matched":false}]},{"number":244,"reference":"","text":"Thou hypocrite, doth not each one of you on the sabbath loose his ox or his ass from the stall, and lead him away to watering? And ought not this woman, being a daughter of Abraham, who Satan hath bound, lo, these eighteen years, be loosed from this bond on the sabbath day?","id":"saying-244","section_index":50,"contexts":[{"book":"Luke","chapter":13,"verse":1,"matched":false}]},{"number":245,"reference":"","text":"Unto what is the kingdom of God like? and whereunto shall I resemble it? It is like a grain of mustard seed, which a man took, and cast into his garden; and it grew, and waxed a great tree; and the fowls of the air lodged in the branches of it.","id":"saying-245","section_index":50,"contexts":[{"book":"Luke","chapter":13,"verse":19,"matched":true}]},{"number":246,"reference":"","text":"Whereunto shall I liken the kingdom of God? It is like leaven, which a woman took and hid in three measures of meal, till the whole was leavened.","id":"saying-246","section_index":50,"contexts":[{"book":"Luke","chapter":13,"verse":21,"matched":true}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Journeying Toward Jerusalem — Parable: The Shut Door — Warned of Herod — \"O Jerusalem, Jerusalem!\" — Martha and Mary.","source":"Luke 13, 22-35; 10, 38-42: John 10, 39-40.","items":[{"number":247,"reference":"","text":"Strive to enter in at the strait gate: for many, I say unto you, will seek to enter in, and shall not be able. When once the master of the house is risen up, and hath shut the door, and ye being to stand without, and to knock at the door, saying, Lord, Lord, open unto us: and he shall answer and say unto you, I know you not whence ye are: Then shall ye begin to say, We have eaten and drunk in thy presence, and thou hast taught in our streets. But he shall say, I tell you, I know you not whence ye are; depart from me, all ye workers of iniquity. There shall be weeping and gnashing of teeth, when ye shall see Abraham, and Isaac, and Jacob, and all the prophets, in the kingdom of God, and you yourselves thrust out.","id":"saying-247","section_index":51,"contexts":[{"book":"Luke","chapter":13,"verse":24,"matched":true},{"book":"John","chapter":10,"verse":1,"matched":false},{"book":"Luke","chapter":10,"verse":1,"matched":false}]},{"number":248,"reference":"","text":"Go ye, and tell that fox, Behold, I cast out devils, and I do cures to day and to morrow, and the third day I shall be perfected. Nevertheless I must walk to day, and to morrow, and the day following: for it cannot be that a prophet perish out of Jerusalem. O Jerusalem, Jerusalem, which killest the prophets, and stonest them that are sent unto thee; how often would I have gathered thy children together, as a hen doth gather her brood under her wings, and ye would not! Behold, your house is left unto you desolate: and verily I say unto you, Ye shall not see me, until the time come when ye shall say, Blessed is he that cometh in the name of the Lord.","id":"saying-248","section_index":51,"contexts":[{"book":"Luke","chapter":13,"verse":33,"matched":true},{"book":"John","chapter":10,"verse":1,"matched":false},{"book":"Luke","chapter":10,"verse":1,"matched":false}]},{"number":249,"reference":"","text":"Martha, Martha, thou are careful and troubled about many things: but one thing is needful; and Mary hath chosen that good part, which shall not be taken away from her.","id":"saying-249","section_index":51,"contexts":[{"book":"Luke","chapter":10,"verse":42,"matched":true},{"book":"Luke","chapter":13,"verse":1,"matched":false},{"book":"John","chapter":10,"verse":1,"matched":false}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Sabbath Healing of Dropsy — A Sermon in Parables: Humble Guest, Great Supper, Counting the Cost, the Warring Kid — Excuse-Making — Salt.","source":"Luke 14, 1-35.","items":[{"number":250,"reference":"","text":"Is it lawful to heal on the sabbath day?","id":"saying-250","section_index":52,"contexts":[{"book":"Luke","chapter":14,"verse":3,"matched":true}]},{"number":251,"reference":"","text":"Which of you shall have an ass or an ox fallen into a pit, and will not straightway pull him out on the sabbath day?","id":"saying-251","section_index":52,"contexts":[{"book":"Luke","chapter":14,"verse":5,"matched":true}]},{"number":252,"reference":"","text":"When thou are bidden of any man to a wedding, sit not down in the highest room; lest a more honorable man than thou be bidden of him; and he that bade thee and him come and say to thee, Give this man place; and thou begin with shame to take the lowest room. But when thou are bidden, go and sit down in the lowest room; that when he that bade thee cometh, he may say unto thee, Friend, go up higher: then shalt thou have worship in the presence of them that sit at meat with thee. For whosoever exalteth himself shall be abased; and he that humbleth himself shall be exalted.","id":"saying-252","section_index":52,"contexts":[{"book":"Luke","chapter":14,"verse":9,"matched":true}]},{"number":253,"reference":"","text":"When thou makest a dinner or a supper, call not thy friends, nor thy brethren, neither thy kinsmen, nor thy rich neighbors; lest they also bid thee again, and a recompense be made thee. But when thou makest a feast, call the poor, the maimed, the lame, the blind; and thou shalt be blessed; for they cannot recompense thee: for thou shalt be recompensed at the resurrection of the just.","id":"saying-253","section_index":52,"contexts":[{"book":"Luke","chapter":14,"verse":13,"matched":true}]},{"number":254,"reference":"","text":"A certain man made a great supper, and bade many: and sent his servant at supper time to say to them that were bidden, Come; for all things are now ready. And they all with one consent began to make excuse. The first said unto him, I have bought a piece of ground, and I must needs go and see it: I pray thee have me excused. And another said, I have bought five yoke of oxen, and I go to prove them: I pray thee have me excused. And another said, I have married a wife, and therefore I cannot come. So that servant came and shewed his lord these things. Then the master of the house being angry said to his servant, Go out quickly into the streets and lanes of the city, and bring in hither the poor, and the maimed, and the halt, and the blind. And the servant said, Lord, it is done as thou hast commanded, and yet there is room. And the lord said unto the servant, Go out into the highways and hedges, and compel them to come in, that my house may be filled. For I say unto you, That none of those men which were bidden shall taste of my supper.","id":"saying-254","section_index":52,"contexts":[{"book":"Luke","chapter":14,"verse":17,"matched":true}]},{"number":255,"reference":"","text":"If any man come to me, and hate not his father, and mother, and wife, and children, and brethren, and sisters, yea, and his own life also, he cannot be my disciple. And whosoever doth not bear his cross, and come after me, cannot be my disciple. For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? Lest haply, after he hath laid the foundation, and is not able to finish it, all that behold it begin to mock him, saying, This man began to build, and was not able to finish. Or what king, going to make war against another king, sitteth not down first, and consulteth whether he be able with ten thousand to meet him that cometh against him with twenty thousand? Or else, while the other is yet a great way off, he sendeth an ambassage, and desireth conditions of peace. So likewise, whosoever he be of you that forsaketh not all that he hath, he cannot be my disciple. Salt is good: but if the salt have lost his savor, wherewith shall it be seasoned? It is neither fit for the land, nor yet for the dunghill; but men cast it out. He that hath ears to hear, let him hear.","id":"saying-255","section_index":52,"contexts":[{"book":"Luke","chapter":14,"verse":26,"matched":true}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Sermon in Parables (Continued): The Ninety and Nine, the Lost Coin, the Prodigal Son.","source":"Luke 15, 1-32.","items":[{"number":256,"reference":"","text":"What man of you, having a hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it? And when he hath found it, he layeth it on his shoulders, rejoicing. And when he cometh home, he calleth together his friends and neighbors, saying unto them, Rejoice with me, for I have found my sheep which was lost. I say unto you, that likewise joy shall be in heaven over one sinner that repenteth, more than over ninety and nine just persons, which need no repentance. Either what woman having ten pieces of silver, if she lose one piece, doth not light a candle, and sweep the house, and seek diligently till she find it? And when she hath found it, she calleth her friends and her neighbors together, saying, Rejoice with me: for I have found the piece which I had lost. Likewise, I say unto you, there is joy in the presence of the angels of God over one sinner that repenteth. A certain man had two sons: and the younger of them said to his father, Father, give me the portion of goods that falleth to me. And he divided unto them his living. And not many days after, the younger son gathered all together, and took his journey into a far country, and there wasted his substance with riotous living. And when he had spent all, there arose a mighty famine in that land; and he began to be in want. And he went and joined himself to a citizen of that country; and he sent him into his fields to feed swine. And he would fain have filled his belly with the husks that the swine did eat; and no man gave unto him. And when he came to himself, he said, How many hired servants of my father's have bread enough and to spare, and I perish with hunger! I will arise and go to my father, and will say unto him, Father, I have sinned against heaven, and before thee, and am no more worthy to be called thy son: make me as one of thy hired servants. And he arose, and came to his father. But when he was yet a great way off, his father saw him, and had compassion, and ran, and fell on his neck, and kissed him. And the son said unto him, Father, I have sinned against heaven, and in thy sight, and am no more worthy to be called thy son. But the father said to his servants, Bring forth the best robe, and put it on him; and put a ring on his hand, and shoes on his feet: and bring hither the fatted calf, and kill it; and let us eat, and be merry: for this my son was dead, and is alive again; he was lost, and is found. And they began to be merry. Now his elder son was in the field: and as he came and drew nigh to the house, he heard music and dancing. And he called one of the servants, and asked what these things meant. And he said unto him, Thy brother is come; and thy father hath killed the fatted calf, because he hath received him safe and sound. And he was angry, and would not go in: therefore came his father out, and entreated him. And he answering said to his father, Lo, these many years do I serve thee, neither transgressed I at any time thy commandment; and yet thou never gavest me a kid, that I might make merry with my friends: but as soon as this thy son was come, which hath devoured thy living with harlots, thou hast killed for him the fatted calf. And he said unto him, Son, thou art ever with me, and all that I have is thine. It was meet that we should make merry, and be glad: for this thy brother was dead, and is alive again; and was lost, and is found.","id":"saying-256","section_index":53,"contexts":[{"book":"Luke","chapter":15,"verse":5,"matched":true}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Sermon in Parables (Continued): The Unjust Steward, the Rich Man and Lazarus — \"Ye Cannot Serve God and Mammon.\"","source":"Luke 16, 1-31.","items":[{"number":257,"reference":"","text":"There was a certain rich man, which had a steward; and the same was accused unto him that he had wasted his goods. And he called him, and said unto him, How is it that I hear this of thee? give an account of thy stewardship; for thou mayest be no longer steward. Then the steward said within himself, What shall I do? for my lord taketh away from me the stewardship: I cannot dig: to beg I am ashamed. I am resolved what to do, that, when I am put out of the stewardship, they may receive me into their houses. So he called every one of his lord's debtors unto him, and said unto the first, How much owest thou unto my lord? And he said, A hundred measures of oil. And he said unto him, Take thy bill, and sit down quickly, and write fifty. Then said he to another, And how much owest thou? And he said, A hundred measures of wheat. And he said unto him, Take thy bill, and write four-score. And the lord commended the unjust steward, because he had done wisely: for the children of this world are in their generation wiser than the children of light. And I say unto you, Make to yourselves friends of the mammon of unrighteousness; that, when ye fail, they may receive you into everlasting habitations. He that is faithful in that which is least is faithful also in much: and he that is unjust in the least is unjust also in much. If herefore ye have not been faithful in the unrighteous mammon, who will commit to your trust the true riches? And if ye have not been faithful in that which is another man's who, shall give you that which is your own? No servant can serve two masters: for either he will hate the one, and love the other, or else he will hold to the one and despise the other. Ye cannot serve God and mammon.","id":"saying-257","section_index":54,"contexts":[{"book":"Luke","chapter":16,"verse":2,"matched":true}]},{"number":258,"reference":"","text":"Ye are they which justify yourselves before men; but God knoweth your hearts: for that which is highly esteemed among men is abomination in the sight of God. The law and the prophets were unto John: since that time the kingdom of God is preached, and every man presseth into it. And it is easier for heaven and earth to pass, than one tittle of the law to fail. Whosoever putteth away his wife, and married another, committeth adultery: and whosoever marrieth her that is put away from her husband committeth adultery. There was a certain rich man, which was clothed in purple and fine linen, and fared sumptuously every day: and there was a certain beggar named Lazarus, which was laid at his gate, full of sores, and desiring to be fed with the crumbs which fell from the rich man's table: moreover the dogs came and licked his sores. And it came to pass, that the beggar died, and it was carried by the angels into Abraham's bosom: the rich man also died and was buried; and in hell he lifted up his eyes, being in torments, and seeth Abraham afar off, and Lazarus in his bosom. And he cried and said, Father Abraham, have mercy on me, and send Lazarus, that he may dip the tip of his finger in water, and cool my tongue: for I am tormented in this flame. But Abraham said, Son, remember that thou in thy lifetime receivedst thy good things, and likewise Lazarus evil things: but now he is comforted, and thou art tormented. And beside all this, between us and you there is a great gulf fixed: so that they which would pass from hence to you cannot; neither can they pass to us, that would come from thence. Then he said, I pray thee therefore, father, that thou wouldest send him to my father's house: for I have five brethren; that he may testify unto them, lest they also come into this place of torment. Abraham saith unto him, They have Moses and the prophets; let them hear them. And he said, Nay, father Abraham: but if one went unto them from the dead, they will repent. And he said unto him, If they hear not Moses and the prophets, neither will they be persuaded, though one rose from the dead.","id":"saying-258","section_index":54,"contexts":[{"book":"Luke","chapter":16,"verse":17,"matched":true}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Sermon in Parables (Concluded): Offences, Forgiveness, Faith, Master and Servant, Martha, Mary, Lazarus: \"Lazarus, Come Forth\" — \"I Am the Resurrection\" — Jews Take Counsel to Kill Jesus.","source":"Luke 17, 1-10: John 11, 1-54.","items":[{"number":259,"reference":"","text":"It is impossible but that offences will come: but woe unto him, through whom they come! It were better for him that a millstone were hanged about his neck, and he cast into the sea, than that he should offend one of these little ones. Take heed to yourselves: If thy brother trespass against thee, rebuke him; and if he repent, forgive him. And if he trespass against thee seven times in a day, and seven times in a day turn again to thee, saying, I repent; thou shalt forgive him.","id":"saying-259","section_index":55,"contexts":[{"book":"Luke","chapter":17,"verse":2,"matched":true},{"book":"John","chapter":11,"verse":1,"matched":false}]},{"number":260,"reference":"","text":"If ye had faith as a grain of mustard seed, ye might say unto this sycamine tree, Be thou plucked up by the root, and be thou planted in the sea; and it should obey you. Doth he thank that servant because he did the things that were commanded him? I trow not. So likewise ye, when ye shall have done all those things which are commanded you, say, We are unprofitable servants: we have done that which was our duty to do.","id":"saying-260","section_index":55,"contexts":[{"book":"Luke","chapter":17,"verse":9,"matched":true},{"book":"John","chapter":11,"verse":1,"matched":false}]},{"number":261,"reference":"","text":"This sickness is not unto death, but for the glory of God, that the Son of God might be glorified thereby.","id":"saying-261","section_index":55,"contexts":[{"book":"John","chapter":11,"verse":4,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]},{"number":262,"reference":"","text":"Let us go into Judea again.","id":"saying-262","section_index":55,"contexts":[{"book":"John","chapter":11,"verse":7,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]},{"number":263,"reference":"","text":"Are there not twelve hours in the day? If any man walk in the day, he stumbleth not, because he seeth the light of this world. But if a man walk in the night, he stumbleth, because there is no light in him. Our friend Lazarus sleepeth; but I go, that I may awake him out of his sleep.","id":"saying-263","section_index":55,"contexts":[{"book":"John","chapter":11,"verse":10,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]},{"number":264,"reference":"","text":"Lazarus is dead. And I am glad for your sakes that I was not there, to the intent ye may believe; nevertheless let us go unto him.","id":"saying-264","section_index":55,"contexts":[{"book":"John","chapter":11,"verse":15,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]},{"number":265,"reference":"","text":"Thy brother shall rise again.","id":"saying-265","section_index":55,"contexts":[{"book":"John","chapter":11,"verse":23,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]},{"number":266,"reference":"","text":"I am the resurrection, and the life; he that believeth in me, though he were dead, yet shall he live: and whosoever liveth and believeth in me shall never die. Believest thou this?","id":"saying-266","section_index":55,"contexts":[{"book":"John","chapter":11,"verse":26,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]},{"number":267,"reference":"","text":"Where have ye laid him?","id":"saying-267","section_index":55,"contexts":[{"book":"John","chapter":11,"verse":34,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]},{"number":268,"reference":"","text":"Take ye away the stone.","id":"saying-268","section_index":55,"contexts":[{"book":"John","chapter":11,"verse":39,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]},{"number":269,"reference":"","text":"Said I not unto thee, that, if thou wouldst believe, thou shouldst see the glory of God?","id":"saying-269","section_index":55,"contexts":[{"book":"Luke","chapter":17,"verse":1,"matched":false},{"book":"John","chapter":11,"verse":1,"matched":false}]},{"number":270,"reference":"","text":"Father, I thank thee that thou hast heard me. And I knew that thou hearest me always: but because of the people which stand by I said it, that they may believe that thou hast sent me.","id":"saying-270","section_index":55,"contexts":[{"book":"John","chapter":11,"verse":42,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]},{"number":271,"reference":"","text":"Lazarus, come forth.","id":"saying-271","section_index":55,"contexts":[{"book":"John","chapter":11,"verse":43,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]},{"number":272,"reference":"","text":"Loose him, and let him go.","id":"saying-272","section_index":55,"contexts":[{"book":"John","chapter":11,"verse":44,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"One Grateful Samaritan Among Ten Lepers Healed — \"The Kingdom of God is Within You\" — \"The Son of Man Must Suffer\" — \"Remember Lot's Wife\" — Parable: The Unjust Judge Wavers — \"Shall the Son of Man Find Faith on the Earth?\"","source":"Luke 17, 11-37; 18, 1-8.","items":[{"number":273,"reference":"","text":"Go shew yourselves unto the priests.","id":"saying-273","section_index":56,"contexts":[{"book":"Luke","chapter":17,"verse":14,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false}]},{"number":274,"reference":"","text":"Were there not ten cleansed? but where are the nine? There are not found that returned to give glory to God, save this stranger.","id":"saying-274","section_index":56,"contexts":[{"book":"Luke","chapter":17,"verse":18,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false}]},{"number":275,"reference":"","text":"Arise, go thy way: thy faith hath made thee whole.","id":"saying-275","section_index":56,"contexts":[{"book":"Luke","chapter":17,"verse":19,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false}]},{"number":276,"reference":"","text":"The kingdom of God cometh not with observation: neither shall they say, Lo here! or, lo there! for, behold, the kingdom of God is within you.","id":"saying-276","section_index":56,"contexts":[{"book":"Luke","chapter":17,"verse":21,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false}]},{"number":277,"reference":"","text":"The days will come, when ye shall desire to see one of the days of the Son of man, and ye shall not see it. And they shall say to you, See here; or, see there: go not after them, nor follow them. For as the lightning, which lighteneth out of the one part under heaven, shineth unto the other part under heaven; so shall also the Son of man be in his day. But first must he suffer many things, and be rejected of this generation. And as it was in the days of Noe, so shall it be also in the days of the Son of man. They did eat, they drank, they married wives, they were given in marriage, until the day that Noe entered into the ark, and the flood came, and destroyed them all. Likewise also as it was in the days of Lot; they did eat, they drank, they bought, they sold, they planted, they builded; but the same day that Lot went out of Sodom it rained fire and brimstone from heaven, and destroyed them all. Even thus shall it be in the day when the Son of man is revealed. In that day, he which shall be upon the housetop, and his stuff in the house, let him not come down to take it away: and he that is in the field, let him likewise not return back. Remember Lot's wife. Whosoever shall seek to save his life shall lose it; and whosoever shall lose his life shall preserve it. I tell you, in that night there shall be two men in one bed; the one shall be taken, and the other shall be left. Two women shall be grinding together; the one shall be taken, and the other left. Two men shall be in the field; the one shall be taken, and the other left.","id":"saying-277","section_index":56,"contexts":[{"book":"Luke","chapter":17,"verse":23,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false}]},{"number":278,"reference":"","text":"Wheresoever the body is, thither will the eagles be gathered together.","id":"saying-278","section_index":56,"contexts":[{"book":"Luke","chapter":17,"verse":37,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false}]},{"number":279,"reference":"","text":"There was in a city a judge, which feared not God, neither regarded man: and there was a widow in that city; and she came unto him, saying, Avenge me of mine adversary. And he would not for a while: but afterward he said within himself, Though I fear not God, nor regard man; yet because this widow troubleth me, I will avenge her, lest by her continual coming she weary me. And the Lord said, Hear what the unjust judge saith. And shall not God avenge his own elect, which cry day and night unto him, though he bear long with them? I tell you that he will avenge them speedily. Nevertheless, when the Son of man cometh, shall he find faith on the earth?","id":"saying-279","section_index":56,"contexts":[{"book":"Luke","chapter":18,"verse":3,"matched":true},{"book":"Luke","chapter":17,"verse":1,"matched":false}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Parable: Presumptuous Pharisee, Penitent Publican — \"Suffer Little Children\" — The Poor Rich Young Ruler — Parable: The Vineyard-Men's Wages.","source":"Luke 18, 9-30: Mark 10, 13-31: Matthew 19, 13-30; and 20, 1-16.","items":[{"number":280,"reference":"","text":"Two men went up into the temple to pray; the one a Pharisee, and the other a publican. The Pharisee stood and prayed thus with himself: God, I thank thee, that I am not as other men are, extortioners, unjust, adulterers, or even as this publican. I fast twice in the week, I give tithes of all that I possess. And the publican, standing afar off, would not lift up so much as his eyes unto heaven, but smote upon his breast, saying, God be merciful to me a sinner. I tell you, this man went down to his house justified rather than the other: for every man that exalteth himself shall be abased; and he that humbleth himself shall be exalted.","id":"saying-280","section_index":57,"contexts":[{"book":"Luke","chapter":18,"verse":10,"matched":true},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Matthew","chapter":19,"verse":1,"matched":false}]},{"number":281,"reference":"","text":"Suffer the little children, and forbid them not, to come unto me: for of such is the kingdom of heaven. Verily I say unto you, Whosoever shall not receive the kingdom of God as a little child, he shall in no wise enter therein.","id":"saying-281","section_index":57,"contexts":[{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Matthew","chapter":19,"verse":1,"matched":false}]},{"number":282,"reference":"","text":"Why callest thou me good? None is good, save one, that is, God: but if thou wilt enter into life, keep the commandments.","id":"saying-282","section_index":57,"contexts":[{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Matthew","chapter":19,"verse":1,"matched":false}]},{"number":283,"reference":"","text":"Thou knowest the commandments, Do not commit adultery, Do not kill, Do not steal, Do not bear false witness, Defraud not, Honor thy father and thy mother: and, Thou shalt love thy neighbor as thyself.","id":"saying-283","section_index":57,"contexts":[{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Matthew","chapter":19,"verse":1,"matched":false}]},{"number":284,"reference":"","text":"Yet lackest thou one thing; if thou wilt be perfect, go thy way, sell all that thou hast, and distribute unto the poor, and thou shalt have treasure in heaven: and come, take up the cross, and follow me.","id":"saying-284","section_index":57,"contexts":[{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Matthew","chapter":19,"verse":1,"matched":false}]},{"number":285,"reference":"","text":"How hardly shall they that have riches enter into the kingdom of God? It is easier for a camel to go through the eye of a needle, than for a rich man to enter into the kingdom of God.","id":"saying-285","section_index":57,"contexts":[{"book":"Mark","chapter":10,"verse":25,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Matthew","chapter":19,"verse":1,"matched":false}]},{"number":286,"reference":"","text":"Children, how hard is it for them that trust in riches to enter into the kingdom of God! Verily I say unto you, That a rich man shall hardly enter into the kingdom of heaven! And again I say unto you, It is easier for a camel to go through a needle's eye, than for a rich man to enter into the kingdom of God.","id":"saying-286","section_index":57,"contexts":[{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Matthew","chapter":19,"verse":1,"matched":false}]},{"number":287,"reference":"","text":"With men this is impossible; but not with God. The things which are impossible with men are possible with God: for with God all things are possible.","id":"saying-287","section_index":57,"contexts":[{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Matthew","chapter":19,"verse":1,"matched":false}]},{"number":288,"reference":"","text":"Ye which have followed me, in the regeneration when the Son of man shall sit in the throne of his glory, ye also shall sit upon twelve thrones, judging the twelve tribes of Israel. There is not a man that hath forsaken houses, or father, or mother, or brethren, or sisters, or wife, or children, or lands, for the kingdom of God's sake, for my sake and the gospel's, but he shall receive a hundredfold, and shall inherit everlasting life. Verily I say unto you, every one that hath left house, or father, or mother, or brethren, or sisters, or wife, or children, or lands, for my name's sake, and the gospel's, shall receive manifold more in this present time: houses, and brethren, and sisters, and mothers, and children, and lands, with persecutions; and shall inherit life everlasting in the world to come. But many that are first shall be last; and the last shall be first. For the kingdom of heaven is like unto a man that is a householder, which went out early in the morning to hire laborers into his vineyard. And when he had agreed with the laborers for a penny a day, he sent them into his vineyard. And he went out about the third hour, and saw others standing idle in the marketplace, and said unto them, Go ye also into the vineyard, and whatsoever is right I will give you. And they went their way. Again he went out about the sixth and ninth hour, and did likewise. And about the eleventh hour he went out, and found others standing idle, and saith unto them, Why stand ye here all the day idle? They say unto him, Because no man hath hired us. He saith unto them, Go ye also into the vineyard; and whatsoever is right, that shall ye receive. So when even was come, the lord of the vineyard saith unto his steward, Call the laborers, and give them their hire, beginning from the last unto the first. And when they came that were hired about the eleventh hour, they received every man a penny. But when the first came, they supposed that they should have received more; and they likewise received every man a penny. And when they had received it, they murmured against the goodman of the house, saying, These last have wrought but one hour, and thou hast made them equal unto us, which have borne the burden and heat of the day. But he answered one of them, and said, Friend, I do thee no wrong: didst not thou agree with me for a penny? Take that thine is, and go thy way: I will give unto this last, even as unto thee. Is it not lawful for me to do what I will with mine own? Is thine eye evil, because I am good? So the last shall be first, and the first last; for many be called, but few chosen.","id":"saying-288","section_index":57,"contexts":[{"book":"Matthew","chapter":19,"verse":30,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Mark","chapter":10,"verse":1,"matched":false}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Divorce Denounced: Jesus Answers Pharisees.","source":"Mark 10, 1-12: Matthew 19, 1-12.","items":[{"number":289,"reference":"","text":"What did Moses command you?","id":"saying-289","section_index":58,"contexts":[{"book":"Mark","chapter":10,"verse":3,"matched":true},{"book":"Matthew","chapter":19,"verse":1,"matched":false}]},{"number":290,"reference":"","text":"For the hardness of your heart he wrote you his precept. But from the beginning of creation God made them male and female. For this cause shall a man leave his father and mother, and cleave to his wife. Have ye not read, that he which made them at the beginning made them male and female, and said, For this cause shall man leave father and mother, and shall cleave to his wife: and they twain shall be one flesh? So then they are no more twain, but one flesh. What therefore God hath joined together, let no man put asunder.","id":"saying-290","section_index":58,"contexts":[{"book":"Mark","chapter":10,"verse":7,"matched":true},{"book":"Matthew","chapter":19,"verse":1,"matched":false}]},{"number":291,"reference":"","text":"Moses because of the hardness of your hearts suffered you to put away your wives: but from the beginning it was not so. And I say unto you, Whosoever shall put away his wife, except it be for fornication, and shall marry another, committeth adultery: and whoso marrieth her which is put away doth commit adultery.","id":"saying-291","section_index":58,"contexts":[{"book":"Matthew","chapter":19,"verse":9,"matched":true},{"book":"Mark","chapter":10,"verse":1,"matched":false}]},{"number":292,"reference":"","text":"Whosoever shall put away his wife, and marry another, committeth adultery against her. And if a woman shall put away her husband, and be married to another, she committeth adultery.","id":"saying-292","section_index":58,"contexts":[{"book":"Mark","chapter":10,"verse":12,"matched":true},{"book":"Matthew","chapter":19,"verse":1,"matched":false}]},{"number":293,"reference":"","text":"All men cannot receive this saying, save they to whom it is given. For there are some eunuchs, which were so born from their mother's womb: and there are some eunuchs which were made eunuchs of men: and there be eunuchs, which have made themselves eunuchs for the kingdom of heaven's sake. He that is able to receive it, let him receive it.","id":"saying-293","section_index":58,"contexts":[{"book":"Matthew","chapter":19,"verse":12,"matched":true},{"book":"Mark","chapter":10,"verse":1,"matched":false}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Jesus Tells of Imminent Betrayal, Death, Resurrection — The Mother of James and John Voices their Ambition — \"The Chiefest Shall be Servant.\"","source":"Matthew 20, 17-28: Mark 10, 32-45: Luke 18, 31-34.","items":[{"number":294,"reference":"","text":"Behold, we go up to Jerusalem; and the Son of man shall be betrayed and delivered unto the chief priests, and unto the scribes; and he shall be spitefully entreated and spitted on; and they shall condemn him to death, and shall deliver him unto the Gentiles. They shall mock him, and shall scourge him, and shall crucify and kill him: and the third day he shall rise again. And all the things that are written by the prophets concerning the Son of man shall be accomplished.","id":"saying-294","section_index":59,"contexts":[{"book":"Matthew","chapter":20,"verse":1,"matched":false},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Luke","chapter":18,"verse":1,"matched":false}]},{"number":295,"reference":"","text":"What wilt thou?","id":"saying-295","section_index":59,"contexts":[{"book":"Matthew","chapter":20,"verse":21,"matched":true},{"book":"Mark","chapter":10,"verse":51,"matched":true},{"book":"Luke","chapter":18,"verse":41,"matched":true}]},{"number":296,"reference":"","text":"What would ye that I should do for you?","id":"saying-296","section_index":59,"contexts":[{"book":"Mark","chapter":10,"verse":36,"matched":true},{"book":"Matthew","chapter":20,"verse":1,"matched":false},{"book":"Luke","chapter":18,"verse":1,"matched":false}]},{"number":297,"reference":"","text":"Ye know not what ye ask: are ye able to drink of the cup that I shall drink of, and to be baptized with the baptism that I am baptized with?","id":"saying-297","section_index":59,"contexts":[{"book":"Matthew","chapter":20,"verse":22,"matched":true},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Luke","chapter":18,"verse":1,"matched":false}]},{"number":298,"reference":"","text":"Ye shall drink indeed of my cup, the cup that I drink of: and with the baptism that I am baptized withal ye shall be baptized: but to sit on my right hand and on my left hand, is not mine to give, but it shall be given to them for whom it is prepared of my Father.","id":"saying-298","section_index":59,"contexts":[{"book":"Mark","chapter":10,"verse":40,"matched":true},{"book":"Matthew","chapter":20,"verse":1,"matched":false},{"book":"Luke","chapter":18,"verse":1,"matched":false}]},{"number":299,"reference":"","text":"Ye know that the princes of the Gentiles exercise dominion over them; ye know that they which are accounted to rule over the Gentiles exercise lordship over them; and their great ones exercise authority upon them. But so shall it not be among you: but whosoever will be great among you, shall be your minister: and whosoever of you will be the chiefest, shall be servant of all: let him be your servant, even as the Son of man: for even the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many.","id":"saying-299","section_index":59,"contexts":[{"book":"Mark","chapter":10,"verse":43,"matched":true},{"book":"Matthew","chapter":20,"verse":1,"matched":false},{"book":"Luke","chapter":18,"verse":1,"matched":false}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Sight Restored to Two Blind Beggars — Parable: The Nobleman, the Servants, and the Money (Pounds).","source":"Luke 18, 35-43; 19, 1-27: Mark 10, 46-52.","items":[{"number":300,"reference":"","text":"What wilt thou that I shall do unto thee?","id":"saying-300","section_index":60,"contexts":[{"book":"Luke","chapter":18,"verse":41,"matched":true},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Luke","chapter":19,"verse":1,"matched":false}]},{"number":301,"reference":"","text":"Receive thy sight: thy faith hath saved thee.","id":"saying-301","section_index":60,"contexts":[{"book":"Luke","chapter":18,"verse":42,"matched":true},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Luke","chapter":19,"verse":1,"matched":false}]},{"number":302,"reference":"","text":"What wilt thou that I shall do unto thee?","id":"saying-302","section_index":60,"contexts":[{"book":"Luke","chapter":18,"verse":41,"matched":true},{"book":"Mark","chapter":10,"verse":1,"matched":false},{"book":"Luke","chapter":19,"verse":1,"matched":false}]},{"number":303,"reference":"","text":"Go thy way; thy faith hath made thee whole.","id":"saying-303","section_index":60,"contexts":[{"book":"Mark","chapter":10,"verse":52,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Luke","chapter":19,"verse":1,"matched":false}]},{"number":304,"reference":"","text":"Zaccheus, make haste, and come down: for to day I must abide at thy house.","id":"saying-304","section_index":60,"contexts":[{"book":"Luke","chapter":19,"verse":5,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Mark","chapter":10,"verse":1,"matched":false}]},{"number":305,"reference":"","text":"This day is salvation come to this house, forasmuch as he also is a son of Abraham. For the Son of man is come to seek and to save that which was lost.","id":"saying-305","section_index":60,"contexts":[{"book":"Luke","chapter":19,"verse":10,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Mark","chapter":10,"verse":1,"matched":false}]},{"number":306,"reference":"","text":"A certain nobleman went into a far country to receive for himself a kingdom, and to return. And he called his ten servants, and delivered them ten pounds, and said unto them, Occupy till I come. But his citizens hated him, and sent a message after him, saying, We will not have this man to reign over us. And it came to pass, that when he was returned, having received the kingdom, then he commanded these servants to be called unto him, to whom he had given the money, that he might know how much every man had gained by trading. Then came the first saying, Lord, thy pound hath gained ten pounds. And he said unto him, Well, thou good servant: because thou hast been faithful in a very little, have thou authority over ten cities. And the second came, saying, Lord, thy pound hath gained five pounds. And he said likewise to him, Be thou also over five cities. And another came, saying, Lord, behold, here is thy pound, which I have kept laid up in a napkin; for I feared thee, because thou art an austere man: thou takest up that thou layest not down, and reapest that thou didst not sow. And he saith unto him, Out of thine own mouth will I judge thee, thou wicked servant. Thou knewest that I was an austere man, taking up that I laid not down, and reaping that I did not sow: Wherefore then gavest not thou my money into the bank, that at my coming I might have required mine own with usury? And he said unto them that stood by, Take from him the pound, and give it to him that hath ten pounds. (And they said unto him, Lord, he hath ten pounds.) But those mine enemies, which would not that I should reign over them, bring hither, and slay them before me. For I say unto you, That unto every one which hath shall be given; and from him that hath not, even that he hath shall be taken away from him.","id":"saying-306","section_index":60,"contexts":[{"book":"Luke","chapter":19,"verse":13,"matched":true},{"book":"Luke","chapter":18,"verse":1,"matched":false},{"book":"Mark","chapter":10,"verse":1,"matched":false}]}],"notes":[],"era":3},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Faring Toward Jerusalem Amidst Hosannas — Jesus Weeps Foretelling Jerusalem's Fate.","source":"John 11:55–57; Matthew 21:1–11; Mark 11:1–11; Luke 19:28–44","items":[{"number":307,"reference":"","text":"Go ye your way into the village over against you, in the which, as soon as ye be entered into it, straightway ye shall find an ass tied, and a colt with her, whereon yet never man sat; loose them, and bring them hither unto me. And if any man say aught unto you, and ask you, Why do ye this? why do ye loose them? ye shall say, Because the Lord hath need of them; and straightway he will send them hither.","id":"saying-307","section_index":61,"contexts":[{"book":"John","chapter":11,"verse":1,"matched":false},{"book":"Matthew","chapter":21,"verse":1,"matched":false},{"book":"Mark","chapter":11,"verse":1,"matched":false},{"book":"Luke","chapter":19,"verse":1,"matched":false}]},{"number":308,"reference":"","text":"I tell you, that if these should hold their peace, the stones would immediately cry out.","id":"saying-308","section_index":61,"contexts":[{"book":"Luke","chapter":19,"verse":40,"matched":true},{"book":"John","chapter":11,"verse":1,"matched":false},{"book":"Matthew","chapter":21,"verse":1,"matched":false},{"book":"Mark","chapter":11,"verse":1,"matched":false}]},{"number":309,"reference":"","text":"If thou hadst known, even thou, at least in this thy day, the things which belong unto thy peace! but now they are hid from thine eyes. For the days shall come upon thee, that thine enemies shall cast a trench about thee, and compass thee round, and keep thee in on every side. And shall lay thee even with the ground, and thy children within thee; and they shall not leave in thee one stone upon another; because thou knewest not the time of thy visitation.","id":"saying-309","section_index":61,"contexts":[{"book":"Luke","chapter":19,"verse":43,"matched":true},{"book":"John","chapter":11,"verse":1,"matched":false},{"book":"Matthew","chapter":21,"verse":1,"matched":false},{"book":"Mark","chapter":11,"verse":1,"matched":false}]},{"number":310,"reference":"","text":"Yea; have ye never read, Out of the mouth of babes and sucklings thou hast perfected praise?","id":"saying-310","section_index":61,"contexts":[{"book":"Matthew","chapter":21,"verse":16,"matched":true},{"book":"John","chapter":11,"verse":1,"matched":false},{"book":"Mark","chapter":11,"verse":1,"matched":false},{"book":"Luke","chapter":19,"verse":1,"matched":false}]}],"notes":[],"era":4},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Fig Tree Withered — Faith Exalted — Prayer with Faith Extolled.","source":"Mark 11, 12-26: Matthew 21, 12-13; 18-22: Luke 19, 45-48.","items":[{"number":311,"reference":"","text":"Let no fruit grow on thee henceforward. No man eat fruit of thee hereafter for ever.","id":"saying-311","section_index":62,"contexts":[{"book":"Mark","chapter":11,"verse":1,"matched":false},{"book":"Matthew","chapter":21,"verse":1,"matched":false},{"book":"Luke","chapter":19,"verse":1,"matched":false}]},{"number":312,"reference":"","text":"Verily I say unto you, If ye have faith, and doubt not, ye shall not only do this which is done to the fig tree, but also if ye shall say to this mountain, Be thou removed, and be thou cast into the sea; it shall be done. And all things, whatsoever ye shall ask in prayer, believing, ye shall receive.","id":"saying-312","section_index":62,"contexts":[{"book":"Matthew","chapter":21,"verse":22,"matched":true},{"book":"Mark","chapter":11,"verse":1,"matched":false},{"book":"Luke","chapter":19,"verse":1,"matched":false}]},{"number":313,"reference":"","text":"My house is the house of prayer. Is it not written, My house shall be called of all nations the house of prayer? but ye have made it a den of thieves.","id":"saying-313","section_index":62,"contexts":[{"book":"Mark","chapter":11,"verse":1,"matched":false},{"book":"Matthew","chapter":21,"verse":1,"matched":false},{"book":"Luke","chapter":19,"verse":1,"matched":false}]},{"number":314,"reference":"","text":"Have faith in God. For verily I say unto you, That whosoever shall say unto this mountain, Be thou removed, and be thou cast into the sea; and shall not doubt in his heart, but shall believe that those things which he saith shall come to pass, he shall have whatsoever he saith. Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall receive them. And when ye stand praying, forgive, if ye have ought against any; that your Father also which is in heaven may forgive you your trespasses. But if ye do not forgive, neither will your Father which is in heaven forgive your trespasses.","id":"saying-314","section_index":62,"contexts":[{"book":"Mark","chapter":11,"verse":23,"matched":true},{"book":"Matthew","chapter":21,"verse":1,"matched":false},{"book":"Luke","chapter":19,"verse":1,"matched":false}]}],"notes":[],"era":4},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Christ's Authority Challenged — Parables: The Sons who Were of Two Minds; The Lord of the Vineyard, His Son, and the Murderous Husbandmen.","source":"Matthew 21, 23-46: Mark 11, 27-33; 12, 1-12: Luke 20, 1-19.","items":[{"number":315,"reference":"","text":"I also will ask of you one question, which if ye will tell me, and answer me, I in like wise will tell you by what authority I do these things: The baptism of John, whence was it? was it from heaven, or of men? Answer me.","id":"saying-315","section_index":63,"contexts":[{"book":"Matthew","chapter":21,"verse":1,"matched":false},{"book":"Mark","chapter":11,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false},{"book":"Mark","chapter":12,"verse":1,"matched":false}]},{"number":316,"reference":"","text":"Neither tell I you by what authority I do these things.","id":"saying-316","section_index":63,"contexts":[{"book":"Matthew","chapter":21,"verse":27,"matched":true},{"book":"Luke","chapter":20,"verse":8,"matched":true},{"book":"Mark","chapter":11,"verse":1,"matched":false},{"book":"Mark","chapter":12,"verse":1,"matched":false}]},{"number":317,"reference":"","text":"But what think ye? A certain man had two sons; and he came to the first, and said, Son, go work to day in my vineyard. He answered and said, I will not: but afterward he repented, and went. And he came to the second, and said likewise. And he answered and said, I go, sir: and went not. Whether of them twain did the will of his father?","id":"saying-317","section_index":63,"contexts":[{"book":"Matthew","chapter":21,"verse":28,"matched":true},{"book":"Mark","chapter":11,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false},{"book":"Mark","chapter":12,"verse":1,"matched":false}]},{"number":318,"reference":"","text":"Verily I say unto you, That the publicans and the harlots go into the kingdom of God before you. For John came unto you in the way of righteousness, and ye believed him not: but the publicans and the harlots believed him: and ye, when ye had seen it, repented not afterward, that ye might believe him.","id":"saying-318","section_index":63,"contexts":[{"book":"Matthew","chapter":21,"verse":32,"matched":true},{"book":"Mark","chapter":11,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false},{"book":"Mark","chapter":12,"verse":1,"matched":false}]},{"number":319,"reference":"","text":"Did ye never read in the Scriptures? What is this then that is written? Have ye not read this Scripture: The stone which the builders rejected, the same is become the head of the corner: this was the Lord's doing, and it is marvellous in our eyes? Therefore I say unto you, The kingdom of God shall be taken from you, and given to a nation bringing forth the fruits thereof. And whosoever shall fall on this stone shall be broken: but on whomsoever it shall fall, it will grind him to powder.","id":"saying-319","section_index":63,"contexts":[{"book":"Matthew","chapter":21,"verse":44,"matched":true},{"book":"Mark","chapter":12,"verse":11,"matched":true},{"book":"Mark","chapter":11,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false}]}],"notes":[],"era":4},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Parable: The King's Guests for his Son's Wedding — Futile Wiles: Cesar's Tribute, The Seven Brothers' Widow.","source":"Matthew 22, 1-32: Mark 12, 13-27: Luke 20, 20-38.","items":[{"number":320,"reference":"","text":"The kingdom of heaven is like unto a certain king which made a marriage for his son, and sent forth his servants to call them that were bidden to the wedding: and they would not come. Again, he sent forth other servants, saying, Tell them which are bidden, Behold, I have prepared my dinner: my oxen and my fatlings are killed, and all things are ready: come unto the marriage. But they made light of it, and went their ways, one to his farm, another to his merchandise: and the remnant took his servants, and entreated them spitefully, and slew them. But when the king heard thereof, he was wroth: and sent forth his armies, and destroyed those murderers, and burned up their city. Then saith he to his servants, The wedding is ready, but they which were bidden were not worthy. Go ye therefore into the highways, and as many as ye shall find, bid to the marriage. So those servants went out into the highways, and gathered all together as many as they found, both bad and good: and the wedding was furnished with guests. And when the king came in to see the guests, he saw there a man which had not on a wedding garment: and he saith unto him, Friend, how earnest thou in hither not having a wedding garment? And he was speechless. Then said the king to the servants, Bind him hand and foot, and take him away, and cast him into outer darkness; there shall be weeping and gnashing of teeth. For many are called, but few are chosen.","id":"saying-320","section_index":64,"contexts":[{"book":"Matthew","chapter":22,"verse":2,"matched":true},{"book":"Mark","chapter":12,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false}]},{"number":321,"reference":"","text":"Why tempt ye me, ye hypocrites? Shew me the tribute money; bring me a penny, that I may see it. Shew me a penny.","id":"saying-321","section_index":64,"contexts":[{"book":"Matthew","chapter":22,"verse":1,"matched":false},{"book":"Mark","chapter":12,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false}]},{"number":322,"reference":"","text":"Whose image and superscription hath it? Whose is this image and superscription?","id":"saying-322","section_index":64,"contexts":[{"book":"Matthew","chapter":22,"verse":1,"matched":false},{"book":"Mark","chapter":12,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false}]},{"number":323,"reference":"","text":"Render therefore unto Cesar the things which be Cesar's; and unto God the things which be God's.","id":"saying-323","section_index":64,"contexts":[{"book":"Luke","chapter":20,"verse":25,"matched":true},{"book":"Matthew","chapter":22,"verse":1,"matched":false},{"book":"Mark","chapter":12,"verse":1,"matched":false}]},{"number":324,"reference":"","text":"Do ye not therefore err, because ye know not the Scriptures? Ye do err, not knowing the Scriptures, neither the power of God. The children of this world marry, and are given in marriage; but they which shall be accounted worthy to obtain that world, and the resurrection from the dead; when they shall rise from the dead, they neither marry, nor are given in marriage: for they are equal unto the angels of God which are in heaven; and are the children of God, being the children of the resurrection. Now that the dead are raised, even Moses shewed at the bush, when he calleth the Lord the God of Abraham, and the God of Isaac, and the God of Jacob. And as touching the resurrection of the dead, that they rise, have ye not read in the book of Moses that which was spoken unto you by God: how in the bush God spake unto Moses, saying, I am the God of Abraham, and the God of Isaac, and the God of Jacob? God is not the God of the dead, but the God of the living; for all live unto him: ye therefore do greatly err.","id":"saying-324","section_index":64,"contexts":[{"book":"Luke","chapter":20,"verse":37,"matched":true},{"book":"Matthew","chapter":22,"verse":1,"matched":false},{"book":"Mark","chapter":12,"verse":1,"matched":false}]}],"notes":[],"era":4},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The First Great Commandment: And the Second — \"Whose Son is Christ?\" — Widow's Mite.","source":"Matthew 22, 34-46: Mark 12, 28-44: Luke 20, 41-47; 21, 1-4.","items":[{"number":325,"reference":"","text":"The first of all the commandments is, Hear, O Israel; The Lord our God is one Lord: and thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind, and with all thy strength: this is the first and great commandment. And the second is like unto it, namely this, Thou shalt love thy neighbor as thyself. On these two commandments hang all the law and the prophets. There is none other commandment greater than these.","id":"saying-325","section_index":65,"contexts":[{"book":"Matthew","chapter":22,"verse":38,"matched":true},{"book":"Mark","chapter":12,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false},{"book":"Luke","chapter":21,"verse":1,"matched":false}]},{"number":326,"reference":"","text":"Thou art not far from the kingdom of God.","id":"saying-326","section_index":65,"contexts":[{"book":"Mark","chapter":12,"verse":34,"matched":true},{"book":"Matthew","chapter":22,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false},{"book":"Luke","chapter":21,"verse":1,"matched":false}]},{"number":327,"reference":"","text":"What think ye of Christ? whose son is he?","id":"saying-327","section_index":65,"contexts":[{"book":"Matthew","chapter":22,"verse":42,"matched":true},{"book":"Mark","chapter":12,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false},{"book":"Luke","chapter":21,"verse":1,"matched":false}]},{"number":328,"reference":"","text":"How then doth David in spirit call him Lord, saying, The Lord said unto my Lord, Sit thou on my right hand, till I make thine enemies thy footstool? If David then call him Lord, how is he his son?","id":"saying-328","section_index":65,"contexts":[{"book":"Matthew","chapter":22,"verse":44,"matched":true},{"book":"Luke","chapter":20,"verse":43,"matched":true},{"book":"Mark","chapter":12,"verse":1,"matched":false},{"book":"Luke","chapter":21,"verse":1,"matched":false}]},{"number":329,"reference":"","text":"How say the scribes that Christ is David's son? For in the book of Psalms David himself saith by the Holy Ghost, The Lord said unto my Lord, Sit thou on my right hand, till I make thine enemies thy footstool. David therefore himself calleth him Lord; and how is he then his son?","id":"saying-329","section_index":65,"contexts":[{"book":"Matthew","chapter":22,"verse":44,"matched":true},{"book":"Luke","chapter":20,"verse":43,"matched":true},{"book":"Mark","chapter":12,"verse":1,"matched":false},{"book":"Luke","chapter":21,"verse":1,"matched":false}]},{"number":330,"reference":"","text":"Beware of the scribes, which desire to walk in long robes, and love greetings in the marketplaces, and the highest seats in the synagogues, and the uppermost rooms at feasts; which devour widows' houses, and for a shew make long prayers: these same shall receive greater damnation,","id":"saying-330","section_index":65,"contexts":[{"book":"Matthew","chapter":22,"verse":1,"matched":false},{"book":"Mark","chapter":12,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false},{"book":"Luke","chapter":21,"verse":1,"matched":false}]},{"number":331,"reference":"","text":"Of a truth I say unto you, that this poor widow doth cast in more than they all which have cast into the treasury: for all these have of their abundance cast in unto the offerings of God: but she of her penury did cast in all that she had, even all her living.","id":"saying-331","section_index":65,"contexts":[{"book":"Matthew","chapter":22,"verse":1,"matched":false},{"book":"Mark","chapter":12,"verse":1,"matched":false},{"book":"Luke","chapter":20,"verse":1,"matched":false},{"book":"Luke","chapter":21,"verse":1,"matched":false}]}],"notes":[],"era":4},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"\"Woe Unto You, Scribes and Pharisees!\" — Hypocrisy and Cant Condemned — \"O Jerusalem, Jerusalem!\" — \"Blessed is He that Cometh in the Name of the Lord.\"","source":"Matthew 23, 1-39.","items":[{"number":332,"reference":"","text":"The scribes and the Pharisees sit in Moses' seat: all therefore whatsoever they bid you observe, that observe and do; but do not ye after their works: for they say, and do not. For they bind heavy burdens and grievous to be borne, and lay them on men's shoulders; but they themselves will not move them with one of their fingers. But all their works they do for to be seen of men: they make broad their phylacteries, and enlarge the borders of their garments, and love the uppermost rooms at feasts, and the chief seats in the synagogues, and greetings in the markets, and to be called of men, Rabbi, Rabbi. But be not ye called Rabbi: for one is your Master, even Christ; and all ye are brethren. And call no man your father upon the earth: for one is your Father which is in heaven. Neither be ye called masters: for one is your Master, even Christ. But he that is greatest among you shall be your servant. And whosoever shall exalt himself shall be abased; and he that shall humble himself shall be exalted. But woe unto you, scribes and pharisees, hypocrites! for ye shut up the kingdom of heaven against men: for ye neither go in yourselves, neither suffer ye them that are entering to go in. Woe unto you, scribes and Pharisees, hypocrites! for ye pay tithe of mint and anise and cummin, and have omitted the weightier matters of the law, judgment, mercy and faith: these ought ye to have done, and not to leave the other undone. Ye blind guides, which strain at a gnat, and swallow a camel. Woe unto you, scribes and Pharisees, hypocrites! for ye make clean the outside of the cup and of the platter, but within they are full of extortion and excess. Thou blind Pharisee, cleanse first that which is within the cup and platter, that the outside of them may be clean also. Woe unto you, scribes and Pharisees, hypocrites! for ye are like unto whited sepulchres, which indeed appear beautiful outward, but are within full of dead men's bones, and of all uncleanness. Even so ye also outwardly appear righteous unto men, but within ye are full of hypocrisy and iniquity. Woe unto you, scribes and Pharisees, hypocrites! because ye build the tombs of the prophets, and garnish the sepulchres of the righteous, and say, If we had been in the days of our fathers, we would not have been partakers with them in the blood of the prophets. Wherefore ye be witnesses unto yourselves, that ye are the children of them which killed the prophets. Fill ye up then the measure of your fathers. Ye serpents, ye generation of vipers, how can ye escape the damnation of hell? Wherefore, behold, I send unto you prophets, and wise men, and scribes: and some of them ye shall kill and crucify; and some of them shall ye scourge in your synagogues, and persecute them from city to city: that upon you may come all the righteous blood shed upon the earth, from the blood of righteous Abel unto the blood of Zacharias son of Barachias, whom ye slew between the temple and the altar. Verily I say unto you, All these things shall come upon this generation. O Jerusalem, Jerusalem, thou that killest the prophets, and stonest them which are sent unto thee, how often would I have gathered thy children together, even as a hen gathereth her chickens under her wings, and ye would not! Behold, your house is left unto you desolate. For I say unto you, Ye shall not see me henceforth, till ye shall say, Blessed is he that cometh in the name of the Lord.","id":"saying-332","section_index":66,"contexts":[{"book":"Matthew","chapter":23,"verse":3,"matched":true}]}],"notes":[],"era":4},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Greeks Desire to See Jesus — He Foresees His Death: \"Now is My Soul Troubled\" — Faith Exalted, Prayer Extolled — \"I Am Come a Light into the World...To Save the World.\"","source":"John 12, 20-36; 42-50.","items":[{"number":333,"reference":"","text":"The hour is come, that the Son of man should be glorified. Verily, verily, I say unto you, Except a corn of wheat fall into the ground and die, it abideth alone: but if it die, it bringeth forth much fruit. He that loveth his life shall lose it; and he that hateth his life in his world shall keep it unto life eternal. If any man serve me, let him follow me; and where I am, there shall also my servant be: if any man serve me, him will my Father honor. Now is my soul troubled; and what shall I say? Father, save me from this hour? but for this cause came I unto this hour. Father, glorify thy name.","id":"saying-333","section_index":67,"contexts":[{"book":"John","chapter":12,"verse":24,"matched":true}]},{"number":334,"reference":"","text":"This voice came not because of me, but for your sakes. Now is the judgment of this world: now shall the prince of this world be cast out. And I, if I be lifted up from the earth, will draw all men unto me.","id":"saying-334","section_index":67,"contexts":[{"book":"John","chapter":12,"verse":31,"matched":true}]},{"number":335,"reference":"","text":"Yet a little while is the light with you. Walk while ye have the light, lest darkness come upon you: for he that walketh in darkness knoweth not whither he goeth. While ye have light, believe in the light, that ye may be the children of light.","id":"saying-335","section_index":67,"contexts":[{"book":"John","chapter":12,"verse":1,"matched":false}]},{"number":336,"reference":"","text":"He that believeth on me believeth not on me, but on him that sent me. And he that seeth me seeth him that sent me. I am come a light into the world, that whosoever believeth on me should not abide in darkness. And if any man hear my words, and believe not, I judge him not: for I came not to judge the world, but to save the world. He that rejecteth me, and receiveth not my words, hath one that judgeth him: the word that I have spoken, the same shall judge him in the last day. For I have not spoken of myself; but the Father which sent me, he gave me a commandment, what I should say, and what I should speak. And I know that his commandment is life everlasting: whatsoever 1 speak therefore, even as the Father said unto me, so I speak.","id":"saying-336","section_index":67,"contexts":[{"book":"John","chapter":12,"verse":45,"matched":true}]}],"notes":[],"era":4},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Temple Doomed — Nation to Rise Against Nation — \"I Will Give You Wisdom\" — \"In Your Patience Possess Ye Your Souls\" — The Son of Man Coming with Power.","source":"Matthew 24, 1-31: Mark 13, 1-27: Luke 21, 5-28.","items":[{"number":337,"reference":"","text":"Seest thou these great buildings? See ye not all these things? Verily I say unto you, As for these things which ye behold, the days will come, in the which there shall not be left here one stone upon another, that shall not be thrown down.","id":"saying-337","section_index":68,"contexts":[{"book":"Matthew","chapter":24,"verse":1,"matched":false},{"book":"Mark","chapter":13,"verse":1,"matched":false},{"book":"Luke","chapter":21,"verse":1,"matched":false}]},{"number":338,"reference":"","text":"Take heed lest any man deceive you. For many shall come in my name, saying, I am Christ; and shall deceive many; and the time draweth near; go ye not therefore after them. Take heed that ye be not deceived but when ye shall hear commotions, and wars, and rumors of wars, see that ye be not troubled; be not terrified. Such things must needs be: for all these things must first come to pass; but the end shall not be yet (is not by and by). Nation shall rise against nation, and kingdom against kingdom; and there shall be famines, and troubles, and pestilences, and great earthquakes, in divers places; and fearful sights and great signs shall there be from heaven. All these things are the beginnings of sorrows. But take heed to yourselves: for before all these, they shall lay their hands on you, and persecute you; delivering you up to councils, and into prisons, to be afflicted: and in the synagogues ye shall be beaten: and ye shall be brought before rulers and kings for my name's sake. And it shall turn to you for a testimony against them. Then shall they kill you, and ye shall be hated of all nations for my name's sake. But the gospel must first be published among all nations. And when they shall lead you, and deliver you up, take no thought beforehand what ye shall speak, neither do ye premeditate: but whatsoever shall be given you in that hour, that speak ye: for it is not ye that speak, but the Holy Ghost. Settle it therefore in your hearts, not to meditate before what ye shall answer; for I will give you a mouth and wisdom, which all your adversaries shall not be able to gainsay nor resist. And then shall many be offended, and shall betray one another. And ye shall be betrayed both by parents, and brethren, and kinsfolks, and friends. Now the brother shall betray the brother to death, and the father the son; and children shall rise up against their parents, and shall cause them to be put to death; and some of you shall they cause to be put to death. And ye shall be hated of all men for my name's sake. But there shall not a hair of your head perish. In your patience possess ye your souls. And many false prophets shall rise and shall deceive many. And because iniquity shall abound, the love of many shall wax cold. But he that shall endure unto the end, the same shall be saved. And this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come. When ye therefore shall see the abomination of desolation, spoken of by Daniel the prophet, standing in the holy place, where it ought not (let him that readeth understand): and when ye shall see Jerusalem compassed with armies, then know that the desolation thereof is nigh; then let them which are in Judea flee to the mountains: and let them which are in the midst of it depart out; and let not them that are in the countries enter thereinto. And let him that is on the housetop not come down into the house, neither enter therein, to take anything out of his house; and let him which is in the field not return back for to take his clothes. For these be the days of vengeance, that all things which are written may be fulfilled. And woe unto them that are with child, and to them that give suck, in those days! for there shall be great distress in the land, and wrath upon the people. And pray ye that your flight be not in winter, neither on the sabbath day: for in those days shall be great affliction, tribulation such as was not since the beginning of the creation which God created, unto this time; no, nor ever in the world shall be. And except that the Lord had shortened those days, there should no flesh be saved: but for the elect's sake, whom he hath chosen, those days shall be shortened. And they shall fall by the edge of the sword, and shall be led away captive into all nations: and Jerusalem shall be trodden down of the Gentiles, until the times of the Gentiles be fulfilled. And then if any man shall say to you, Lo, here is Christ; or, lo, he is there; believe it not: for there shall arise false Christs and false prophets, and shall show great signs and wonders, to seduce; insomuch that, if it were possible, they shall deceive even the very elect. But take ye heed: behold, I have foretold you all things. Wherefore if they shall say unto you, Behold, he is in the desert; go not forth: Behold, he is in the secret chambers; believe it not. For as the lightning cometh out of the east, and shineth even unto the west; so shall also the coming of the Son of man be. For wheresoever the carcass is, there will the eagles be gathered together. But immediately, in those days after that tribulation, there shall be signs in the sun, and in the moon, and in the stars: the sun shall be darkened, and the moon shall not give her light, and the stars of heaven shall fall; and the powers that are in the heavens shall be shaken: and upon the earth [shall be] distress of nations, with perplexity; the sea and waves roaring: men's hearts failing them for fear, and for looking after those things which are coming on the earth: for the powers of heaven shall be shaken. And then shall appear the sign of the Son of man in heaven: and then shall all the tribes of the earth mourn, and they shall see the Son of man coming in the clouds of heaven with power and great glory. And then shall he send his angels with a great sound of a trumpet, and they shall gather together his elect from the four winds, from the uttermost part of the earth to the uttermost part of heaven; from one end of heaven to another. And when these things begin to come to pass, then look up, and lift up your heads; for your redemption draweth nigh.","id":"saying-338","section_index":68,"contexts":[{"book":"Matthew","chapter":24,"verse":5,"matched":true},{"book":"Mark","chapter":13,"verse":6,"matched":true},{"book":"Luke","chapter":21,"verse":13,"matched":true}]}],"notes":[],"era":4},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Parables: The Fig Tree in Leaf, Absent Householder and the House Servants, Virgins Wise and Virgins Foolish — \"Watch and Pray.\"","source":"Matthew 24, 32-51; 25, 1-13: Mark 13, 28-37: Luke 21, 29-36.","items":[{"number":339,"reference":"","text":"NOW learn a parable of the fig tree: Behold the fig tree when her branch is yet tender, and putteth forth leaves; and behold the trees when they now shoot forth: ye see and know of your own selves that summer is nigh at hand. So in like manner, when ye shall see all these things come to pass, know ye that the kingdom of God is nigh at hand, even at the doors. Verily I say unto you, This generation shall not pass, till all these things be done. Heaven and earth shall pass away, but my words shall not pass away. And take heed to yourselves, lest at any time your hearts be overcharged with surfeiting and drunkenness, and cares of this life; and so that day come upon you unawares. For as a snare shall it come on all them that dwell on the face of the whole earth. Watch ye therefore, and pray always, that ye may be accounted worthy to escape all these things that shall come to pass, and to stand before the Son of man. But of that day and that hour knoweth no man, no, not the angels which are in heaven, neither the Son, but my Father only. Take ye heed, watch and pray: for ye know not when the time is. as the days of Noe were, so shall also the coming of the Son of man be. For as in the days that were before the flood they were eating and drinking, marrying and giving in marriage, until the day that Noe entered into the ark, and knew not till the flood came, and took them all away: so shall also the coming of the Son of man be. Then shall two be in the field; the one shall be taken, and the other left. Two women shall be grinding at the mill; the one shall be taken, and the other left. Watch therefore: for ye know not what hour your Lord doth come. For the Son of man is as a man taking a far journey, who left his house, and gave authority to his servants, and to every man his work, and commanded the porter to watch. Watch ye therefore: for ye know not when the master of the house cometh, at even, or at midnight, or at the cockcrowing, or in the morning: lest coming suddenly he find you sleeping. And what I say unto you I say unto all, Watch. But know this, that if the goodman of the house had known in what watch the thief would come, he would have watched, and would not have suffered his house to be broken up. Therefore be ye also ready: for in such an hour as ye think not the Son of man cometh. And what I say unto you I say unto all, Watch. Who then is a faithful and wise servant, whom his lord hath made ruler over his household, to give them meat in due season? Blessed is that servant, whom his lord when he cometh shall find so doing. Verily I say unto you, That he shall make him ruler over all his goods. But and if that evil servant shall say in his heart, My lord delayeth his coming; and shall begin to smit his fellow servants, and to eat and drink with the drunken; the lord of that servant shall come in a day when he looketh not for him, and in an hour that he is not aware of, and shall cut him asunder, and appoint him his portion with the hypocrites: there shall be weeping and gnashing of teeth. Then shall the kingdom of heaven be likened unto ten virgins, which took their lamps, and went forth to meet the bridegroom. And five of them were wise, and five were foolish. They that were foolish took their lamps, and took no oil with them. But the wise took oil in their vessels with their lamps. While the bridegroom tarried, they all slumbered and slept. And at midnight there was a cry made, Behold, the bridegroom cometh; go ye out to meet him. Then all those virgins arose, and trimmed their lamps. And the foolish said unto the wise, Give us of your oil; for our lamps are gone out. But the wise answered, saying, Not so; lest there be not enough for us and you, but go ye rather to them that sell, and buy for yourselves. And while they went to buy, the bridegroom came: and they that were ready went in with him to the marriage: and the door was shut. Afterward came also the other virgins, saying, Lord, Lord, open to us. But he answered and said, Verily I say unto you, I know you not. Watch, therefore, for ye know neither the day nor the hour wherein the Son of man cometh.","id":"saying-339","section_index":69,"contexts":[{"book":"Matthew","chapter":24,"verse":35,"matched":true},{"book":"Mark","chapter":13,"verse":31,"matched":true},{"book":"Luke","chapter":21,"verse":33,"matched":true},{"book":"Matthew","chapter":25,"verse":1,"matched":true}]}],"notes":[],"era":4},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Parable: The Master, the Servants, the Money (Talents) — On the Last Judgment: \"When the Son of Man Shall Come.\"","source":"Matthew 25, 14-46.","items":[{"number":340,"reference":"","text":"FOR the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods. And unto one he gave five talents, to another, two, and to another, one; to every man according to his several ability; and straightway took his journey. Then he that had received the five talents went and traded with the same, and made them other five talents. And likewise he that had received two, he also gained other two. But he that had received one went and digged in the earth, and hid his lord's money. After a long time the lord of those servants cometh, and reckoned with them. And so he that had received five talents came and brought other five talents, saying, Lord, thou deliveredst unto me five talents: behold, I have gained beside them five talents more. His lord said unto him, Well done, thou good and faithful servant: thou hast been faithful over a few things, I will make thee ruler over many things: enter thou into the joy of thy lord. He also that had received two talents came and said, Lord, thou deliveredst unto me two talents: behold, I have gained two other talents beside them. His lord said unto him, Well done, good and faithful servant: thou hast been faithful over a few things, I will make thee ruler over many things: enter thou into the joy of thy lord. Then he which had received the one talent came and said, Lord, I knew thee that thou art a hard man, reaping where thou hast not sown, and gathering where thou hast not strewed; and I was afraid, and went and hid thy talent in the earth: lo, there thou hast that is thine. His lord answered and said unto him, Thou wicked and slothful servant, thou knewest that I reap where I sowed not, and gather where I have not strewed: Thou oughtest therefore to have put my money to the exchangers, and then at my coming I should have received mine own with usury. Take therefore the talent from him, and give it unto him which hath ten talents. For unto every one that hath shall be given, and he shall have abundance: but from him that hath not shall be taken away even that which he hath. And cast ye the unprofitable servant into outer darkness: there shall be weeping and gnashing of teeth. When the Son of man shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory: and before him shall be gathered all nations: and he shall separate them one from another, as a shepherd divideth his sheep from the goats: and he shall set the sheep on his right hand, but the goats on the left. Then shall the King say unto them on his right hand, Come, ye blessed of my Father, inherit the kingdom prepared for you from the foundation of the world: for I was a hungered, and ye gave me meat: I was thirsty, and ye gave me drink: I was a stranger, and ye took me in: naked, and ye clothed me: I was sick, and ye visited me: I was in prison, and ye came unto me. Then shall the righteous answer him, saying, Lord, when saw we thee a hungered, and fed thee? or thirsty, and gave thee drink? When saw we thee a stranger, and took thee in? or naked, and clothed thee? Or when saw we thee sick, or in prison, and came unto thee? And the King shall answer and say unto them, Verily I say unto you, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me. Then shall he say also unto them on the left hand, Depart from me, ye cursed, into everlasting fire, prepared for the devil and his angels: for I was a hungered, and ye gave me no meat: I was thirsty, and ye gave me no drink: I was a stranger, and ye took me not in: naked, and ye clothed me not; sick, and in prison, and ye visited me not. Then shall they also answer him, saying, Lord, when saw we thee a hungered, or athirst, or a stranger, or naked, or sick, or in prison, and did not minister unto thee? Then he shall answer them, saying, Verily I say unto you, Inasmuch as ye did it not to one of the least of these, ye did it not to me. And these shall go away into everlasting punishment: but the righteous into life eternal.","id":"saying-340","section_index":70,"contexts":[{"book":"Matthew","chapter":25,"verse":14,"matched":true}]}],"notes":[],"era":4},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Jesus Sups in Bethany: Martha Serves, Mary's Devotion, Judas' Duplicity, Jesus Lauds Mary's Homage — Chief Priests Astir.","source":"John 12, 1-11: Matthew 26, 6-13: Mark 14, 3-9.","items":[{"number":341,"reference":"","text":"Let her alone: why trouble ye the woman? Against the day of my burying hath she done this. For ye have the poor with you always, and whensoever ye will ye may do them good: but me ye have not always. She hath wrought a good work upon me; for she hath done what she could: for in that she hath poured this ointment on my body, she is come aforehand to anoint my body to the burying (she did it for my burial). Why trouble ye her? Verily I say unto you, Wheresoever this gospel shall be preached throughout the whole world, there shall also this that this woman hath done, be told for a memorial of her.","id":"saying-341","section_index":71,"contexts":[{"book":"Mark","chapter":14,"verse":7,"matched":true},{"book":"John","chapter":12,"verse":1,"matched":false},{"book":"Matthew","chapter":26,"verse":1,"matched":false}]}],"notes":[],"era":4},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Conspiracy at the High Priest's Palace — Judas Hired — The Passover Supper — Christ's Humility: He Washes the Feet of the Twelve.","source":"Luke 21, 37-38; 22, 1-18: Matthew 26, 1-5; 14-20: Mark 14, 1-2; 10-17: John 13,","items":[{"number":342,"reference":"","text":"Ye know that after two days is the feast of passover, and the Son of man is betrayed to be crucified.","id":"saying-342","section_index":72,"contexts":[{"book":"Luke","chapter":21,"verse":1,"matched":false},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]},{"number":343,"reference":"","text":"Go and prepare the passover, that we may eat.","id":"saying-343","section_index":72,"contexts":[{"book":"Luke","chapter":21,"verse":1,"matched":false},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]},{"number":344,"reference":"","text":"When ye are entered into the city, behold, there shall meet you a man bearing a pitcher of water: go ye into the city to such a man, and follow him into the house where he entereth in. And wheresoever he shall go in, say ye to the goodman of the house, The Master saith unto thee, My time is at hand; I will keep the passover at thy house with my disciples. Where is the guestchamber, where I shall eat the passover with my disciples? And he will shew you a large upper room furnished and prepared: there make ready for us.","id":"saying-344","section_index":72,"contexts":[{"book":"Mark","chapter":14,"verse":15,"matched":true},{"book":"Luke","chapter":21,"verse":1,"matched":false},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]},{"number":345,"reference":"","text":"With desire I have desired to eat this passover with you before I suffer: for I say unto you, I will not any more eat thereof, until it be fulfilled in the kingdom of God.","id":"saying-345","section_index":72,"contexts":[{"book":"Luke","chapter":22,"verse":16,"matched":true},{"book":"Luke","chapter":21,"verse":1,"matched":false},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false}]},{"number":346,"reference":"","text":"Take this, and divide it among yourselves: for I say unto you, I will not drink of the fruit of the vine, until the kingdom of God shall come.","id":"saying-346","section_index":72,"contexts":[{"book":"Luke","chapter":22,"verse":18,"matched":true},{"book":"Luke","chapter":21,"verse":1,"matched":false},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false}]},{"number":347,"reference":"","text":"What I do thou knowest not now; but thou shalt know hereafter.","id":"saying-347","section_index":72,"contexts":[{"book":"John","chapter":13,"verse":7,"matched":true},{"book":"Luke","chapter":21,"verse":1,"matched":false},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]},{"number":348,"reference":"","text":"If I wash thee not, thou hast no part with me.","id":"saying-348","section_index":72,"contexts":[{"book":"John","chapter":13,"verse":8,"matched":true},{"book":"Luke","chapter":21,"verse":1,"matched":false},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]},{"number":349,"reference":"","text":"He that is washed needeth not save to wash his feet, but is clean every whit: and ye are clean, but not all.","id":"saying-349","section_index":72,"contexts":[{"book":"John","chapter":13,"verse":10,"matched":true},{"book":"Luke","chapter":21,"verse":1,"matched":false},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]},{"number":350,"reference":"","text":"Ye are not all clean.","id":"saying-350","section_index":72,"contexts":[{"book":"John","chapter":13,"verse":11,"matched":true},{"book":"Luke","chapter":21,"verse":1,"matched":false},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]},{"number":351,"reference":"","text":"Ye call me Master and Lord: and ye say well; for so I am. If I then, your Lord and Master, have washed your feet: ye also ought to wash one another's feet. For I have given you an example, that ye should do as I have done to you. Verily, verily, I say unto you, The servant is not greater than his lord: neither he that is sent greater than he that sent him. If ye know these things, happy are ye if ye do them.","id":"saying-351","section_index":72,"contexts":[{"book":"John","chapter":13,"verse":13,"matched":true},{"book":"Luke","chapter":21,"verse":1,"matched":false},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]}],"notes":[],"era":5},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Christ Institutes his Holy Supper — Judas the Betrayer — Peter's Three Denials Predicted — \"Yet a Little While I Am with You: Let Not Your Heart Be Troubled\" — Many Mansions.","source":"Matthew 26, 21-29: Mark 14, 18-25: Luke 22, 19-38: John 13, 18-38; 14, 1-4; also 1 Corinthians 11, 23-25.","items":[{"number":352,"reference":"","text":"This is my body which is given for you: this do in remembrance of me.","id":"saying-352","section_index":73,"contexts":[{"book":"Luke","chapter":22,"verse":19,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":353,"reference":"","text":"Verily I say unto you, that one of you shall betray me. But, behold, the hand of him that betrayeth me is with me on the table. And truly the Son of man goeth, as it was determined: but woe unto that man by whom he is betrayed! I speak not of you all: I know whom I have chosen: but that the Scripture may be fulfilled, He that eateth bread with me hath lifted up his heel against me. Now I tell you before it come, that, when it is come to pass, ye may believe that I am he. Verily, verily, I say unto you, He that receiveth whomsoever I send receiveth me; and he that receiveth me receiveth him that sent me.","id":"saying-353","section_index":73,"contexts":[{"book":"Luke","chapter":22,"verse":21,"matched":true},{"book":"John","chapter":13,"verse":18,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":354,"reference":"","text":"Verily, verily, I say unto you, that one of you which eateth with me shall betray me.","id":"saying-354","section_index":73,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":355,"reference":"","text":"It is one of the twelve: he that dippeth his hand with me in the dish, the same shall betray me. The Son of man indeed goeth, as it is written of him; but woe to that man by whom the Son of man is betrayed! good were it for that man if he had never been born.","id":"saying-355","section_index":73,"contexts":[{"book":"Mark","chapter":14,"verse":21,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":356,"reference":"","text":"He it is, to whom I shall give a sop, when I have dipped it.","id":"saying-356","section_index":73,"contexts":[{"book":"John","chapter":13,"verse":26,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":357,"reference":"","text":"That thou doest, do quickly.","id":"saying-357","section_index":73,"contexts":[{"book":"John","chapter":13,"verse":27,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":358,"reference":"","text":"Thou hast said.","id":"saying-358","section_index":73,"contexts":[{"book":"Matthew","chapter":26,"verse":25,"matched":true},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":359,"reference":"","text":"Now is the Son of man glorified, and God is glorified in him. If God be glorified in him, God shall also glorify him in himself, and shall straightway glorify him. Little children, yet a little while I am with you. Ye shall seek me: and as I said unto the Jews, so now I say to you, Whither I go, ye cannot come. A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another. By this shall all men know that ye are my disciples, if ye have love one to another.","id":"saying-359","section_index":73,"contexts":[{"book":"John","chapter":13,"verse":32,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":360,"reference":"","text":"Whither I go, thou canst not follow me now: but thou shalt follow me afterwards.","id":"saying-360","section_index":73,"contexts":[{"book":"John","chapter":13,"verse":36,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":361,"reference":"","text":"Wilt thou lay down thy life for my sake? Verily, verily, I say unto thee, The cock shall not crow, till thou hast denied me thrice.","id":"saying-361","section_index":73,"contexts":[{"book":"John","chapter":13,"verse":38,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":362,"reference":"","text":"The kings of the Gentile exercise lordship over them; and they that exercise authority upon them are called benefactors. But ye shall not be so; but he that is greatest among you, let him be as the younger; and he that is chief, as he that doth serve. For whether is greater, he that sitteth at meat, or he that serveth? is not he that sitteth at meat? but I am among you as he that serveth. Ye are they which have continued with me in my temptations. And I appoint unto you a kingdom, as my father hath appointed unto me; that ye may eat and drink at my table in my kingdom, and sit on thrones judging the twelve tribes of Israel.","id":"saying-362","section_index":73,"contexts":[{"book":"Luke","chapter":22,"verse":26,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":363,"reference":"","text":"Simon, Simon, behold, Satan hath desired to have you, that he may sift you as wheat: but I have prayed for thee, that thy faith fail not: and when thou art converted, strengthen thy brethren.","id":"saying-363","section_index":73,"contexts":[{"book":"Luke","chapter":22,"verse":32,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":364,"reference":"","text":"I tell thee, Peter, the cock shall not crow this day, before that thou shalt thrice deny that thou knowest me.","id":"saying-364","section_index":73,"contexts":[{"book":"Luke","chapter":22,"verse":34,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":365,"reference":"","text":"When I sent you without purse, and scrip, and shoes, lacked ye anything?","id":"saying-365","section_index":73,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":366,"reference":"","text":"But now, he that hath a purse, let him take it, and likewise his scrip: and he that hath no sword, let him sell his garment, and buy one. For I say unto you, that this that is written must yet be accomplished in me, And he was reckoned among the transgressors. For the things concerning me have an end.","id":"saying-366","section_index":73,"contexts":[{"book":"Luke","chapter":22,"verse":37,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":367,"reference":"","text":"It is enough.","id":"saying-367","section_index":73,"contexts":[{"book":"Mark","chapter":14,"verse":41,"matched":true},{"book":"Luke","chapter":22,"verse":38,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":368,"reference":"","text":"Drink ye all of it.","id":"saying-368","section_index":73,"contexts":[{"book":"Matthew","chapter":26,"verse":27,"matched":true},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false},{"book":"John","chapter":14,"verse":1,"matched":false}]},{"number":369,"reference":"","text":"This cup is the new testament in my blood, which is shed for you; for this is my blood of the new testament which is shed for many for the remission of sins: this do ye, as oft as ye drink it, in remembrance of me. Verily I say unto you, I will drink henceforth no more of this fruit of the vine, until that day when I drink it new with you in the kingdom of God, my Father's kingdom. Let not your heart be troubled: ye believe in God, believe also in me. In my Father's house are many mansions: if it were not so, I would have told you. I go to prepare a place for you. And if I go and prepare a place for you, I will come again, and receive you unto myself; that where I am, there ye may be also. And whither I go ye know, and the way ye know.","id":"saying-369","section_index":73,"contexts":[{"book":"Matthew","chapter":26,"verse":28,"matched":true},{"book":"John","chapter":14,"verse":1,"matched":true},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":13,"verse":1,"matched":false},{"book":"1 Corinthians","chapter":11,"verse":1,"matched":false}]}],"notes":[],"era":5},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Saying \"I Go Unto my Father,\" Christ Exalts Peace, Good Will, Love — \"I Am the Way, the Truth, the Life\" — Reassures the Apostles — The Comforter: \"Peace I Leave with You.\"","source":"John 14, 5-31.","items":[{"number":370,"reference":"","text":"I am the way, the truth, and the life: no man cometh unto the Father, but by me. If ye had known me, ye should have known my Father also: and from henceforth ye know him, and have seen him.","id":"saying-370","section_index":74,"contexts":[{"book":"John","chapter":14,"verse":7,"matched":true}]},{"number":371,"reference":"","text":"Have I been so long time with you, and yet hast thou not known me, Philip? he that hath seen me hath seen the Father; and how sayest thou then, Shew us the Father? Believest thou not that I am in the Father, and the Father in me? The words I speak unto you, I speak not of myself: but the Father that dwelleth in me, he doeth the works. Believe me that I am in the Father, and the Father in me: or else believe me for the very works’ sake. Verily, verily, I say unto you, He that believeth on me, the works that I do shall he do also; and greater works than these shall he do; because I go unto my Father. And whatsoever ye shall ask in my name, that will I do, that the Father may be glorified in the Son. If ye shall ask anything in my name, I will do it. If ye love me keep my commandments. And I will pray the Father, and he shall give you another Comforter, that he may abide with you for ever; even the Spirit of truth; whom the world cannot receive, because it seeth him not, neither knoweth him: but ye know him; for he dwelleth with you, and shall be in you. I will not leave you comfortless; I will come to you. Yet a little while, and the world seeth me no more; but ye see me: because I live, ye shall live also. At that day ye shall know that I am in my Father, and ye in me, and I in you. He that hath my commandments, and keepeth them, he it is that loveth me: and he that loveth me shall be loved of my Father, and I will love him, and will manifest myself to him.","id":"saying-371","section_index":74,"contexts":[{"book":"John","chapter":14,"verse":11,"matched":true}]},{"number":372,"reference":"","text":"If a man love me, he will keep my words: and my Father will love him, and we will come unto him, and make our abode with him. He that loveth me not keepth not my sayings: and the word which ye hear is not mine, but the Father's which sent me. These things have I spoken unto you, being yet present with you. But the Comforter, which is the Holy Ghost, whom the Father will send in my name, he shall teach you all things, and bring all things to your remembrance, whatsoever I have said unto you. Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid. Ye have heard how I said unto you, I go away, and come again unto you. If ye loved me, ye would rejoice, because I said, I go unto the Father: for my Father is greater than I. And now I have told you before it come to pass, that, when it is come to pass, ye might believe. Hereafter I will not talk much with you: for the prince of this world cometh, and hath nothing in me. But that the world may know that I love the Father; and as the Father gave me commandment, even so I do.","id":"saying-372","section_index":74,"contexts":[{"book":"John","chapter":14,"verse":25,"matched":true}]}],"notes":[],"era":5},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"\"I Am the True Vine\" — Relationship in Love — \"When the Comforter is Come\" — \"Greater Love Hath No Man than This....\"","source":"John 15, 1-27; 16, 1.","items":[{"number":373,"reference":"","text":"I AM the true vine, and my Father is the husbandman. Every branch in me that beareth not fruit he taketh away: and every branch that beareth fruit, he purgeth it, that it may bring forth more fruit. Now ye are clean through the word which I have spoken unto you. Abide in me, and I in you. As the branch cannot bear fruit of itself, except it abide in the vine; no more can ye, except ye abide in me. I am the vine, ye are the branches; he that abideth in me, and I in him, the same bringeth forth much fruit; for without me ye can do nothing. If a man abide not in me, he is cast forth as a branch, and is withered; and men gather them, and cast them into the fire, and they are burned. If ye abide in me, and my words abide in you, ye shall ask what ye will, and it shall be done unto you. Herein is my Father glorified, that ye bear much fruit; so shall ye be my disciples. As the Father hath loved me, so have I loved you: continue ye in my love. If ye keep my commandments, ye shall abide in my love; even as I have kept my Father's commandments and abide in his love. These things have I spoken unto you, that my joy might remain in you, and that your joy might be full. This is my commandment, that ye love one another, as I have loved you. Greater love hath no man than this, that a man lay down his life for his friends. Ye are my friends, if ye do whatsoever I command you. Henceforth I call you not servants; for the servant knoweth not what his lord doeth; but I have called you friends; for all things that I have heard of my Father I have made known unto you. Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you. These things I command you, that ye love one another. If the world hate you, ye know that it hated me before it hated you. If ye were of the world, the world would love his own: but because ye are not of the world but I have chosen you out of the world, therefore the world hateth you. Remember the word that I said unto you, The servant is not greater than his lord. If they have persecuted me, they will also persecute you; if they have kept my saying, they will keep yours also. But all these things will they do unto you for my name's sake, because they know not him that sent me. If I had not come and spoken unto them, they had not had sin: but now they have no cloak for their sin. He that hateth me hateth my Father also. If I had not done among them the works which none other man did, they had not had sin: but now have they both seen and hated both me and my Father. But this cometh to pass, that the word might be fulfilled that is written in their law, They hated me without a cause. But when the Comforter is come, whom I will send unto you from the Father, even the Spirit of truth, which proceedeth from the Father, he shall testify of me: and ye also shall bear witness, because ye have been with me from the beginning. These things have I spoken unto you, that ye should not be offended.","id":"saying-373","section_index":75,"contexts":[{"book":"John","chapter":15,"verse":1,"matched":true},{"book":"John","chapter":16,"verse":1,"matched":true}]}],"notes":[],"era":5},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Comforter, The Spirit of Truth: \"Be of Good Cheer, I have Overcome the World\" — \"Your Sorrow Shall be Turned to Joy\" — Christ to Depart this Life.","source":"John 16, 2-33.","items":[{"number":374,"reference":"","text":"THEY shall put you out of the synagogues: yea, the time cometh, that whosoever killeth you, you will think that he doeth God service. And these things will they do unto you, because they have not known the Father, nor me. But these things have I told you, that when the time shall come, ye may remember that I told you of them. And these things I said not unto you at the beginning, because I was with you. But now I go my way to him that sent me; and none of you asketh me, Whither goest thou? But because I have said these things unto you, sorrow hath filled your heart. Nevertheless I tell you the truth; It is expedient for you that I go away: for if I go not away, the Comforter will not come unto you; but if I depart, I will send him unto you. And when he is come, he will reprove the world of sin, and of righteousness, and of judgment: of sin, because they believed not on me; of righteousness, because I go to my Father, and ye see me no more; of judgment, because the prince of this world is judged. I have yet many things to say unto you, but ye cannot bear them now. Howbeit when he, the Spirit of truth, is come, he will guide you into all truth: for he shall not speak of himself; but whatsoever he shall hear, that shall he speak: and he will shew you things to come. He shall glorify me: for he shall receive of mine, and shall shew it unto you. All things that the Father hath are mine: therefore said I, that he shall take of mine, and shall shew it unto you. A little while, and ye shall not see me: and again, a little while, and ye shall see me, because I go to the Father.","id":"saying-374","section_index":76,"contexts":[{"book":"John","chapter":16,"verse":3,"matched":true}]},{"number":375,"reference":"","text":"Do ye inquire among yourselves of that I said, A little while, and ye shall not see me: and again, a little while, and ye shall see me? Verily, verily, I say unto you, That ye shall weep and lament, but the world shall rejoice; and ye shall be sorrowful, but your sorrow shall be turned into joy. A woman when she is in travail hath sorrow, because her hour is come: but as soon as she is delivered of the child, she remembereth no more the anguish, for joy that a man is born into the world. And ye now therefore have sorrow: but I will see you again, and your heart shall rejoice, and your joy no man taketh from you. And in that day ye shall ask me nothing. Verily, verily, I say unto you, Whatsoever ye shall ask the Father in my name, he will give it you. Hitherto have ye asked nothing in my name: ask, and ye shall receive, that your joy may be full. These things have I spoken unto you in proverbs: but the time cometh, when I shall no more speak unto you in proverbs, but I shall shew you plainly of the Father. At that day ye shall ask in my name: and 1 say not unto you, that I will pray the Father for you: for the Father himself loveth you, because ye have loved me, and have believed that I came out from God. I came forth from the Father, and am come into the world: again, I leave the world, and go to the Father.","id":"saying-375","section_index":76,"contexts":[{"book":"John","chapter":16,"verse":20,"matched":true}]},{"number":376,"reference":"","text":"Do ye now believe? Behold, the hour cometh, yea, is now come, that ye shall be scattered, every man to his own, and shall leave me alone: and yet I am not alone, because the Father is with me. These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.","id":"saying-376","section_index":76,"contexts":[{"book":"John","chapter":16,"verse":32,"matched":true}]}],"notes":[],"era":5},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Christ Prays for Aid — \"I Have Finished the Work\" — Prays for the Apostles Also, and their Work — Prays for All Believers.","source":"John 17, 1-26.","items":[{"number":377,"reference":"","text":"Father, the hour is come; glorify thy Son, that thy Son also may glorify thee: as thou hast given him power over all flesh, that he should give eternal life to as many as thou hast given him. And this is life eternal, that they might know thee the only true God, and Jesus Christ whom thou hast sent. I have glorified thee on the earth: I have finished the work which thou gavest me to do. And now, O Father, glorify thou me with thine own self with the glory which I had with thee before the world was. I have manifested thy name unto the men which thou gavest me out of the world: thine they were, and thou gavest them me; and they have kept thy word. Now they have known that all things whatsoever thou hast given me are of thee. For I have given unto them the words which thou gavest me; and they have received them, and have known surely that I came out from thee, and they have believed that thou didst send me. I pray for them: I pray not for the world, but for them which thou hast given me; for they are thine. And all mine are thine, and thine are mine; and I am glorified in them. And now I am no more in the world, but these are in the world, and I come to thee. Holy Father, keep through thine own name those whom thou hast given me, that they may be one, as we are. While I was with them in the world, I kept them in thy name: those that thou gavest me I have kept, and none of them is lost, but the son of perdition: that the Scripture might be fulfilled. And now come I to thee; and these things I speak in the world, that they might have my joy fulfilled in themselves. I have given them thy word; and the world hath hated them, because they are not of the world, even as I am not of the world. I pray not that thou shouldest take them out of the world, but that thou shouldest keep them from the evil. They are not of the world, even as I am not of the world. Sanctify them through thy truth: thy word is truth. As thou hast sent me into the world, even so have I also sent them into the world. And for their sakes I sanctify myself, that they also might be sanctified through the truth. Neither pray I for these alone, but for them also which shall believe on me through their word; that they all may be one; as thou, Father, art in me, and I in thee, that they also may be one in us: that the world may believe that thou hast sent me. And the glory which thou gavest me I have given them: that they may be one, even as we are one; I in them, and thou in me, that they may be made perfect in one; and that the world may know that thou hast sent me, and hast loved them, as thou hast loved me. Father, I will that they also, whom thou hast given me, be with me where I am; that they may behold my glory, which thou hast given me: for thou lovedst me before the foundation of the world. O righteous Father, the world hath not known thee: but I have known thee, and these have known that thou hast sent me. And I have declared unto them thy name, and will declare it: that the love wherewith thou hast loved me may be in them, and I in them. Arise, let us go hence.","id":"saying-377","section_index":77,"contexts":[{"book":"John","chapter":17,"verse":2,"matched":true}]}],"notes":[],"era":5},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Christ Again Foretells Peter's Three Denials — In Gethsemane Prays While Apostles Sleep — The Spirit Willing, the Flesh Weak — Judas and Crowd with Weapons Find Jesus.","source":"Matthew 26, 30-47: Mark 14, 26-43: Luke 22, 39-47: John 18, 1-9.","items":[{"number":378,"reference":"","text":"All ye shall be offended because of me this night: for it is written, I will smite the Shepherd, and the sheep of the flock shall be scattered abroad. But after that I am risen again, I will go before you into Galilee.","id":"saying-378","section_index":78,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":379,"reference":"","text":"Verily I say unto thee, That this day, even in this night, before the cock crow twice, thou shalt deny me thrice.","id":"saying-379","section_index":78,"contexts":[{"book":"Mark","chapter":14,"verse":30,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":380,"reference":"","text":"Sit ye here, while I go and pray yonder. Pray that ye enter not into temptation.","id":"saying-380","section_index":78,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":381,"reference":"","text":"My soul is exceeding sorrowful, even unto death: tarry ye here, and watch with me.","id":"saying-381","section_index":78,"contexts":[{"book":"Matthew","chapter":26,"verse":38,"matched":true},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":382,"reference":"","text":"Abba, Father, all things are possible unto thee: Father, if it be possible, if thou be willing, remove this cup from me: nevertheless not my will, but thine, be done.","id":"saying-382","section_index":78,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":383,"reference":"","text":"Simon, sleepest thou? What, couldest not thou watch with me one hour? Watch ye and pray, lest ye enter into temptation. The spirit truly is willing, but the flesh is weak.","id":"saying-383","section_index":78,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":384,"reference":"","text":"O my Father, if it be possible, let this cup pass from me: if this cup may not pass away from me, except I drink it, thy will be done.","id":"saying-384","section_index":78,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":385,"reference":"","text":"Why sleep ye? rise and pray, lest ye enter into temptation.","id":"saying-385","section_index":78,"contexts":[{"book":"Luke","chapter":22,"verse":46,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":386,"reference":"","text":"Father, take away this cup from me: nevertheless not what I will, but what thou wilt.","id":"saying-386","section_index":78,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":387,"reference":"","text":"Sleep on now, and take your rest: it is enough: behold, the hour is come; behold, the hour is at hand, and the Son of man is betrayed into the hands of sinners. Rise up, let us be going: lo, he is at hand that doth betray me.","id":"saying-387","section_index":78,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":388,"reference":"","text":"Whom seek ye?","id":"saying-388","section_index":78,"contexts":[{"book":"John","chapter":18,"verse":4,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]},{"number":389,"reference":"","text":"I am he.","id":"saying-389","section_index":78,"contexts":[{"book":"John","chapter":18,"verse":5,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]},{"number":390,"reference":"","text":"Whom seek ye?","id":"saying-390","section_index":78,"contexts":[{"book":"John","chapter":18,"verse":4,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]},{"number":391,"reference":"","text":"I have told you that I am he: if therefore ye seek me, let these go their way.","id":"saying-391","section_index":78,"contexts":[{"book":"John","chapter":18,"verse":8,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]},{"number":392,"reference":"","text":"Of them which thou gavest me have I lost none.","id":"saying-392","section_index":78,"contexts":[{"book":"John","chapter":18,"verse":9,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false}]}],"notes":[],"era":6},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"The Betrayal: Judas' Kiss — Peter Militant — Christ Hailed to Court — An Officer Strikes Jesus Though Bound — \"All the Disciples Forsook Him.\"","source":"Matthew 26, 48-58: Mark 14, 44-50; 53-54: Luke 22, 47-55: John 18, 10-16; 19-","items":[{"number":393,"reference":"","text":"Friend, wherefore art thou come? Judas, betrayest thou the Son of man with a kiss?","id":"saying-393","section_index":79,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":394,"reference":"","text":"Suffer thus far.","id":"saying-394","section_index":79,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":395,"reference":"","text":"Put up again thy sword into his place in the sheath: for all they that take the sword shall perish with the sword: the cup which my Father hath given me, shall I not drink it? Thinkest thou that I cannot now pray to my Father, and he shall presently give me more than twelve legions of angels? But how then shall the Scriptures be fulfilled, that thus it must be?","id":"saying-395","section_index":79,"contexts":[{"book":"Matthew","chapter":26,"verse":53,"matched":true},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":396,"reference":"","text":"Be ye come out, as against a thief, with swords and staves for to take me? When I sat daily with you, teaching in the temple, ye stretched forth no hands against me: ye laid no hold on me: ye took me not: but this is your hour, and the power of darkness. But all this was done that the Scriptures of the prophets might be fulfilled. The Scriptures must be fulfilled.","id":"saying-396","section_index":79,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":397,"reference":"","text":"I spake openly to the world: I ever taught in the synagogues, and in the temple, whither the Jews always resort: and in secret have I said nothing. Ask them which heard me, what I have said unto them: behold, they know what I said. Why askest thou me?","id":"saying-397","section_index":79,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]},{"number":398,"reference":"","text":"If I have spoken evil, bear witness to the evil: but if well, why smitest thou me?","id":"saying-398","section_index":79,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false}]}],"notes":[],"era":6},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Christ's Trial Continued — False Witness — Peter Thrice Denies Christ — Morning: Further Questioning — Judas a Suicide.","source":"Matthew 26, 59-75; 27, 1-7: Mark 14, 55-72: Luke 22, 56-71: John 18, 17-27.","items":[{"number":399,"reference":"","text":"Thou hast said. I am. Nevertheless I say unto you, Hereafter shall ye see the Son of man sitting on the right hand of power, and coming in the clouds of heaven.","id":"saying-399","section_index":80,"contexts":[{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false},{"book":"Matthew","chapter":27,"verse":1,"matched":false}]},{"number":400,"reference":"","text":"Before the cock crow twice, thou shalt deny me thrice.","id":"saying-400","section_index":80,"contexts":[{"book":"Mark","chapter":14,"verse":30,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Luke","chapter":22,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false},{"book":"Matthew","chapter":27,"verse":1,"matched":false}]},{"number":401,"reference":"","text":"Ye say that I am.","id":"saying-401","section_index":80,"contexts":[{"book":"Luke","chapter":22,"verse":70,"matched":true},{"book":"Matthew","chapter":26,"verse":1,"matched":false},{"book":"Mark","chapter":14,"verse":1,"matched":false},{"book":"John","chapter":18,"verse":1,"matched":false},{"book":"Matthew","chapter":27,"verse":1,"matched":false}]}],"notes":[],"era":6},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Christ Haled before Pilate: Pilate's Dilemma — \"Crucify Him\" — Pilate Vacillates: Sends Jesus to Herod, Who Sends him Back — Jesus Scourged — Pilate Delivers Jesus to be Crucified.","source":"John 18, 28-40; 19, 1-16: Luke 23, 1-11; 13-25: Mark 15, 1-15: Matthew 27, 11-","items":[{"number":402,"reference":"","text":"Sayest thou this thing of thyself, or did others tell it thee of me?","id":"saying-402","section_index":81,"contexts":[{"book":"John","chapter":18,"verse":34,"matched":true},{"book":"Luke","chapter":23,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"John","chapter":19,"verse":1,"matched":false}]},{"number":403,"reference":"","text":"My kingdom is not of this world: if my kingdom were of this world, then would my servants fight, that I should not be delivered to the Jews: but now is my kingdom not from hence.","id":"saying-403","section_index":81,"contexts":[{"book":"John","chapter":18,"verse":36,"matched":true},{"book":"Luke","chapter":23,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"John","chapter":19,"verse":1,"matched":false}]},{"number":404,"reference":"","text":"Thou sayest that I am a king. To this end was I born, and for this cause came I into the world, that I should bear witness unto the truth. Every one that is of the truth heareth my voice.","id":"saying-404","section_index":81,"contexts":[{"book":"John","chapter":18,"verse":37,"matched":true},{"book":"Luke","chapter":23,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"John","chapter":19,"verse":1,"matched":false}]},{"number":405,"reference":"","text":"Thou couldest have no power at all against me, except it were given thee from above: therefore he that delivered me unto thee hath the greater sin.","id":"saying-405","section_index":81,"contexts":[{"book":"John","chapter":19,"verse":11,"matched":true},{"book":"John","chapter":18,"verse":1,"matched":false},{"book":"Luke","chapter":23,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"Matthew","chapter":27,"verse":1,"matched":false}]},{"number":406,"reference":"","text":"Thou sayest it.","id":"saying-406","section_index":81,"contexts":[{"book":"Luke","chapter":23,"verse":3,"matched":true},{"book":"Mark","chapter":15,"verse":2,"matched":true},{"book":"John","chapter":18,"verse":1,"matched":false},{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"John","chapter":19,"verse":1,"matched":false}]}],"notes":[],"era":6},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Christ Crowned with Thorns, Robed in Scarlet — Mocked — \"In a Green Tree, in the Dry?\" — The Crucifixion — \"Father, Forgive Them\" — Pilate Writes the Title.","source":"Matthew 27, 27-38: Mark 15, 16-27: Luke 23, 26-34: John 19, 17-20.","items":[{"number":407,"reference":"","text":"Daughters of Jerusalem, weep not for me, but weep for yourselves, and for your children. For, behold, the days are coming, in the which they shall say, Blessed are the barren, and the wombs that never bare, and the paps which never gave suck. Then shall they begin to say to the mountains, Fall on us: and to the hills, Cover us. For if they do these things in a green tree, what shall be done in the dry?","id":"saying-407","section_index":82,"contexts":[{"book":"Luke","chapter":23,"verse":29,"matched":true},{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":19,"verse":1,"matched":false}]},{"number":408,"reference":"","text":"Father, forgive them; for they know not what they do.","id":"saying-408","section_index":82,"contexts":[{"book":"Luke","chapter":23,"verse":34,"matched":true},{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":19,"verse":1,"matched":false}]}],"notes":[],"era":6},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Casting Lots for the Savior's Clothes — The Penitent Thief Rewarded — Christ's Filial Farewell to his Mother — It Is Finished.","source":"Matthew 27, 39-56: Mark 15, 29-41: Luke 23, 35-49: John 19, 23-30.","items":[{"number":409,"reference":"","text":"Verily I say unto thee, To day shalt thou be with me in paradise.","id":"saying-409","section_index":83,"contexts":[{"book":"Luke","chapter":23,"verse":43,"matched":true},{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":19,"verse":1,"matched":false}]},{"number":410,"reference":"","text":"Woman, behold thy son!","id":"saying-410","section_index":83,"contexts":[{"book":"John","chapter":19,"verse":26,"matched":true},{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"Luke","chapter":23,"verse":1,"matched":false}]},{"number":411,"reference":"","text":"Behold thy mother!","id":"saying-411","section_index":83,"contexts":[{"book":"John","chapter":19,"verse":27,"matched":true},{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"Luke","chapter":23,"verse":1,"matched":false}]},{"number":412,"reference":"","text":"My God, my God, why hast thou forsaken me?","id":"saying-412","section_index":83,"contexts":[{"book":"Matthew","chapter":27,"verse":46,"matched":true},{"book":"Mark","chapter":15,"verse":34,"matched":true},{"book":"Luke","chapter":23,"verse":1,"matched":false},{"book":"John","chapter":19,"verse":1,"matched":false}]},{"number":413,"reference":"","text":"I thirst.","id":"saying-413","section_index":83,"contexts":[{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"Luke","chapter":23,"verse":1,"matched":false},{"book":"John","chapter":19,"verse":1,"matched":false}]},{"number":414,"reference":"","text":"It is finished.","id":"saying-414","section_index":83,"contexts":[{"book":"John","chapter":19,"verse":30,"matched":true},{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"Luke","chapter":23,"verse":1,"matched":false}]},{"number":415,"reference":"","text":"Father, into thy hands I commend my spirit!","id":"saying-415","section_index":83,"contexts":[{"book":"Luke","chapter":23,"verse":46,"matched":true},{"book":"Matthew","chapter":27,"verse":1,"matched":false},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"John","chapter":19,"verse":1,"matched":false}]}],"notes":[],"era":6},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Pilate Gives Christ's Body to the Arimathean — Laid in Joseph's New Tomb — The Galilean Women Watching — The Priests Set a Watch.","source":"Mark 15, 42-47: Luke 23, 50-56: John 19, 38-42: Matthew 27, 57-66.","items":[{"number":416,"reference":"","text":"After three days I will rise again.","id":"saying-416","section_index":84,"contexts":[{"book":"Matthew","chapter":27,"verse":63,"matched":true},{"book":"Mark","chapter":15,"verse":1,"matched":false},{"book":"Luke","chapter":23,"verse":1,"matched":false},{"book":"John","chapter":19,"verse":1,"matched":false}]}],"notes":[],"era":6},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"After the Resurrection: The Devoted Marys — Christ in Person: \"All Hail\" — Talks with mary Magdalene.","source":"Matthew 28, 1, and 8-10: Mark 16, 1-11: Luke 24, 1-9: John 20, 11-18.","items":[{"number":417,"reference":"","text":"All hail!","id":"saying-417","section_index":85,"contexts":[{"book":"Matthew","chapter":28,"verse":1,"matched":false},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Luke","chapter":24,"verse":1,"matched":false},{"book":"John","chapter":20,"verse":1,"matched":false}]},{"number":418,"reference":"","text":"Be not afraid: go tell my brethren that they go into Galilee, and there shall they see me.","id":"saying-418","section_index":85,"contexts":[{"book":"Matthew","chapter":28,"verse":10,"matched":true},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Luke","chapter":24,"verse":1,"matched":false},{"book":"John","chapter":20,"verse":1,"matched":false}]},{"number":419,"reference":"","text":"Woman, why weepest thou? whom seekest thou?","id":"saying-419","section_index":85,"contexts":[{"book":"John","chapter":20,"verse":15,"matched":true},{"book":"Matthew","chapter":28,"verse":1,"matched":false},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Luke","chapter":24,"verse":1,"matched":false}]},{"number":420,"reference":"","text":"Mary.","id":"saying-420","section_index":85,"contexts":[{"book":"Matthew","chapter":28,"verse":1,"matched":false},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Luke","chapter":24,"verse":1,"matched":false},{"book":"John","chapter":20,"verse":1,"matched":false}]},{"number":421,"reference":"","text":"Touch me not; for I am not yet ascended to my Father: but go to my brethren, and say unto them, I ascend unto my Father, and your Father; and to my God, and your God.","id":"saying-421","section_index":85,"contexts":[{"book":"John","chapter":20,"verse":17,"matched":true},{"book":"Matthew","chapter":28,"verse":1,"matched":false},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Luke","chapter":24,"verse":1,"matched":false}]}],"notes":[],"era":7},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"After the Resurrection (Continued): Christ in Person: With the Two Men; With the Eleven — Doubting Thomas.","source":"Mark 16, 12-13: Luke 24, 13-31; 33-43: John 20, 19-29.","items":[{"number":422,"reference":"","text":"What manner of communications are these that ye have one to another, as ye walk, and are sad?","id":"saying-422","section_index":86,"contexts":[{"book":"Luke","chapter":24,"verse":17,"matched":true},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"John","chapter":20,"verse":1,"matched":false}]},{"number":423,"reference":"","text":"What things?","id":"saying-423","section_index":86,"contexts":[{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Luke","chapter":24,"verse":1,"matched":false},{"book":"John","chapter":20,"verse":1,"matched":false}]},{"number":424,"reference":"","text":"O fools, and slow of heart to believe all that the prophets have spoken: ought not Christ to have suffered these things, and to enter into his glory? And beginning at Moses, he expounded the things in all the Scriptures concerning himself.","id":"saying-424","section_index":86,"contexts":[{"book":"Luke","chapter":24,"verse":26,"matched":true},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"John","chapter":20,"verse":1,"matched":false}]},{"number":425,"reference":"","text":"Peace be unto you.","id":"saying-425","section_index":86,"contexts":[{"book":"Luke","chapter":24,"verse":36,"matched":true},{"book":"John","chapter":20,"verse":19,"matched":true},{"book":"Mark","chapter":16,"verse":1,"matched":false}]},{"number":426,"reference":"","text":"Why are ye troubled? and why do thoughts arise in your hearts? Behold my hands and my feet, that it is myself: handle me, and see; for a spirit hath not flesh and bones, as ye see me have.","id":"saying-426","section_index":86,"contexts":[{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Luke","chapter":24,"verse":1,"matched":false},{"book":"John","chapter":20,"verse":1,"matched":false}]},{"number":427,"reference":"","text":"Have ye here any meat?","id":"saying-427","section_index":86,"contexts":[{"book":"Luke","chapter":24,"verse":41,"matched":true},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"John","chapter":20,"verse":1,"matched":false}]},{"number":428,"reference":"","text":"Peace be unto you; as my Father hath sent me, even so I send you. Receive ye the Holy Ghost. Whosesoever sins ye remit, they are remitted unto them: and whosesoever sins ye retain, they are retained.","id":"saying-428","section_index":86,"contexts":[{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Luke","chapter":24,"verse":1,"matched":false},{"book":"John","chapter":20,"verse":1,"matched":false}]},{"number":429,"reference":"","text":"Peace be unto you.","id":"saying-429","section_index":86,"contexts":[{"book":"Luke","chapter":24,"verse":36,"matched":true},{"book":"John","chapter":20,"verse":19,"matched":true},{"book":"Mark","chapter":16,"verse":1,"matched":false}]},{"number":430,"reference":"","text":"Reach hither thy finger, and behold my hands; and reach hither thy hand, and thrust it into my side: and be not faithless, but believing.","id":"saying-430","section_index":86,"contexts":[{"book":"John","chapter":20,"verse":27,"matched":true},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Luke","chapter":24,"verse":1,"matched":false}]},{"number":431,"reference":"","text":"Thomas, because thou hast seen me, thou hast believed: blessed are they that have not seen, and yet have believed.","id":"saying-431","section_index":86,"contexts":[{"book":"John","chapter":20,"verse":29,"matched":true},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Luke","chapter":24,"verse":1,"matched":false}]}],"notes":[],"era":7},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"After the Resurrection (Continued): Jesus in Person: On the Shore — The Great Catch of Fish — Peter — That Other Loved One.","source":"John 21, 1-25.","items":[{"number":432,"reference":"","text":"Children, have ye any meat?","id":"saying-432","section_index":87,"contexts":[{"book":"John","chapter":21,"verse":5,"matched":true}]},{"number":433,"reference":"","text":"Cast the net on the right side of the ship, and ye shall find.","id":"saying-433","section_index":87,"contexts":[{"book":"John","chapter":21,"verse":6,"matched":true}]},{"number":434,"reference":"","text":"Bring of the fish which ye have now caught.","id":"saying-434","section_index":87,"contexts":[{"book":"John","chapter":21,"verse":10,"matched":true}]},{"number":435,"reference":"","text":"Simon, son of Jonas, lovest thou me more than these?","id":"saying-435","section_index":87,"contexts":[{"book":"John","chapter":21,"verse":15,"matched":true}]},{"number":436,"reference":"","text":"Feed my lambs.","id":"saying-436","section_index":87,"contexts":[{"book":"John","chapter":21,"verse":15,"matched":true}]},{"number":437,"reference":"","text":"Simon, son of Jonas, lovest thou me?","id":"saying-437","section_index":87,"contexts":[{"book":"John","chapter":21,"verse":15,"matched":true}]},{"number":438,"reference":"","text":"Feed my sheep.","id":"saying-438","section_index":87,"contexts":[{"book":"John","chapter":21,"verse":16,"matched":true}]},{"number":439,"reference":"","text":"Simon, son of Jonas, lovest thou me?","id":"saying-439","section_index":87,"contexts":[{"book":"John","chapter":21,"verse":15,"matched":true}]},{"number":440,"reference":"","text":"Feed my sheep. Verily, verily, I say unto thee, When thou wast young, thou girdedst thyself, and walkedst whither thou wouldest: but when thou shall be old, thou shalt stretch forth thy hands, and another shall gird thee, and carry thee whither thou wouldest not.","id":"saying-440","section_index":87,"contexts":[{"book":"John","chapter":21,"verse":1,"matched":false}]},{"number":441,"reference":"","text":"Follow me.","id":"saying-441","section_index":87,"contexts":[{"book":"John","chapter":21,"verse":1,"matched":false}]},{"number":442,"reference":"","text":"If I will that he tarry till I come, what is that to thee? follow thou me.","id":"saying-442","section_index":87,"contexts":[{"book":"John","chapter":21,"verse":22,"matched":true}]}],"notes":[],"era":7},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"After the Resurrection (Continued): Christ in Person: His Last Talk with The Eleven — \"Go Ye and Preach the Gospel to Every Creature\" — The Ascension.","source":"Matthew 28:16–20; Mark 16:14–20; Luke 24:44–53; Acts 1:1–11","items":[{"number":443,"reference":"","text":"Go ye into all the world, and preach the gospel to every creature. He that believeth and is baptized shall be saved; but he that believeth not shall be damned. And these signs shall follow them that believe: In my name shall they cast out devils; they shall speak with new tongues; they shall take up serpents; and if they drink any deadly thing, it shall not hurt them; they shall lay hands on the sick, and they shall recover. All power is given unto me in heaven and in earth. Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost: teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world.","id":"saying-443","section_index":88,"contexts":[{"book":"Matthew","chapter":28,"verse":19,"matched":true},{"book":"Mark","chapter":16,"verse":16,"matched":true},{"book":"Luke","chapter":24,"verse":1,"matched":false},{"book":"Acts","chapter":1,"verse":1,"matched":false}]},{"number":444,"reference":"","text":"These are the words which I spake unto you, while I was with you, That all things must be fulfilled, which were written in the law of Moses, and in the prophets, and in the psalms, concerning me.","id":"saying-444","section_index":88,"contexts":[{"book":"Matthew","chapter":28,"verse":1,"matched":false},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Luke","chapter":24,"verse":1,"matched":false},{"book":"Acts","chapter":1,"verse":1,"matched":false}]},{"number":445,"reference":"","text":"Thus it is written, and thus it behooved Christ to suffer, and to rise from the dead the third day: and that repentance and remission of sins should be preached in his name among all nations, beginning at Jerusalem. And ye are witnesses of these things. And, behold, I send the promise of my Father upon you: but tarry ye in the city of Jerusalem, until ye be endued with power from on high.","id":"saying-445","section_index":88,"contexts":[{"book":"Luke","chapter":24,"verse":47,"matched":true},{"book":"Matthew","chapter":28,"verse":1,"matched":false},{"book":"Mark","chapter":16,"verse":1,"matched":false},{"book":"Acts","chapter":1,"verse":1,"matched":false}]}],"notes":[],"era":7},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"Unplaced within the earthly ministry: a saying preserved only by Paul","source":"","items":[{"number":null,"reference":"Acts 20:35","text":"It is more blessed to give than to receive.","id":"passage-90-1","section_index":89,"contexts":[{"book":"Acts","chapter":20,"verse":35,"matched":true}]}],"notes":[],"era":8},{"major":"A. Chronological Gospel harmony: childhood, ministry, Passion, Resurrection, and Ascension","title":"After the Resurrection (Continued): Christ in Person: Apostles' Question Answered.","source":"Luke: Acts 1, 2-9.","items":[{"number":446,"reference":"","text":"Wait (tarry in Jerusalem) for the promise of the Father, which ye have heard of me. For John truly baptized with water; but ye shall be baptized with the Holy Ghost not many days hence.","id":"saying-446","section_index":90,"contexts":[{"book":"Acts","chapter":1,"verse":5,"matched":true}]},{"number":447,"reference":"","text":"It is not for you to know the times or the seasons, which the Father hath put in his own power. But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judea, and in Samaria, and unto the uttermost parts of the earth.","id":"saying-447","section_index":90,"contexts":[{"book":"Acts","chapter":1,"verse":1,"matched":false}]}],"notes":["Part 92 above contains Jesus’ words immediately before the Ascension (Acts 1). The following sayings occur after the Ascension."],"era":7},{"major":"B. Post-Ascension sayings in Acts and Paul","title":"The road to Damascus — the risen Jesus addresses Saul","source":"Acts 9:4-6; Acts 22:7-10; Acts 26:14-18","items":[{"number":null,"reference":"Acts 9","text":"Saul, Saul, why persecutest thou me?","id":"passage-92-1","section_index":91,"contexts":[{"book":"Acts","chapter":9,"verse":4,"matched":true}]},{"number":null,"reference":"Acts 9","text":"I am Jesus whom thou persecutest: it is hard for thee to kick against the pricks.","id":"passage-92-2","section_index":91,"contexts":[{"book":"Acts","chapter":9,"verse":5,"matched":true}]},{"number":null,"reference":"Acts 9","text":"Arise, and go into the city, and it shall be told thee what thou must do.","id":"passage-92-3","section_index":91,"contexts":[{"book":"Acts","chapter":9,"verse":6,"matched":true}]},{"number":null,"reference":"Acts 22 retelling of the same event","text":"I am Jesus of Nazareth, whom thou persecutest.","id":"passage-92-4","section_index":91,"contexts":[{"book":"Acts","chapter":22,"verse":8,"matched":true}]},{"number":null,"reference":"Acts 22 retelling of the same event","text":"Arise, and go into Damascus; and there it shall be told thee of all things which are appointed for thee to do.","id":"passage-92-5","section_index":91,"contexts":[{"book":"Acts","chapter":22,"verse":10,"matched":true}]},{"number":null,"reference":"Acts 26 retelling of the same event","text":"Saul, Saul, why persecutest thou me? it is hard for thee to kick against the pricks.","id":"passage-92-6","section_index":91,"contexts":[{"book":"Acts","chapter":26,"verse":14,"matched":true}]},{"number":null,"reference":"Acts 26 retelling of the same event","text":"I am Jesus whom thou persecutest.","id":"passage-92-7","section_index":91,"contexts":[{"book":"Acts","chapter":26,"verse":15,"matched":true}]},{"number":null,"reference":"Acts 26 retelling of the same event","text":"But rise, and stand upon thy feet: for I have appeared unto thee for this purpose, to make thee a minister and a witness both of these things which thou hast seen, and of those things in the which I will appear unto thee; delivering thee from the people, and from the Gentiles, unto whom now I send thee, to open their eyes, and to turn them from darkness to light, and from the power of Satan unto God, that they may receive forgiveness of sins, and inheritance among them which are sanctified by faith that is in me.","id":"passage-92-8","section_index":91,"contexts":[{"book":"Acts","chapter":26,"verse":16,"matched":true}]}],"notes":["*The event occurred once. Acts 22 and 26 are Paul's later retellings and preserve additional wording; they are shown here with the original event rather than treated as later speeches.*"],"era":8},{"major":"B. Post-Ascension sayings in Acts and Paul","title":"A vision to Ananias concerning Saul","source":"Acts 9:10-16","items":[{"number":null,"reference":"Acts 9:10","text":"Ananias.","id":"passage-93-1","section_index":92,"contexts":[{"book":"Acts","chapter":9,"verse":1,"matched":false}]},{"number":null,"reference":"Acts 9:11-12","text":"Arise, and go into the street which is called Straight, and inquire in the house of Judas for one called Saul, of Tarsus: for, behold, he prayeth, and hath seen in a vision a man named Ananias coming in, and putting his hand on him, that he might receive his sight.","id":"passage-93-2","section_index":92,"contexts":[{"book":"Acts","chapter":9,"verse":12,"matched":true}]},{"number":null,"reference":"Acts 9:15-16","text":"Go thy way: for he is a chosen vessel unto me, to bear my name before the Gentiles, and kings, and the children of Israel: for I will shew him how great things he must suffer for my name's sake.","id":"passage-93-3","section_index":92,"contexts":[{"book":"Acts","chapter":9,"verse":16,"matched":true}]}],"notes":[],"era":8},{"major":"B. Post-Ascension sayings in Acts and Paul","title":"Paul's Jerusalem temple vision","source":"Acts 22:17-21","items":[{"number":null,"reference":"Acts 22:18","text":"Make haste, and get thee quickly out of Jerusalem: for they will not receive thy testimony concerning me.","id":"passage-94-1","section_index":93,"contexts":[{"book":"Acts","chapter":22,"verse":18,"matched":true}]},{"number":null,"reference":"Acts 22:21","text":"Depart: for I will send thee far hence unto the Gentiles.","id":"passage-94-2","section_index":93,"contexts":[{"book":"Acts","chapter":22,"verse":21,"matched":true}]}],"notes":[],"era":8},{"major":"B. Post-Ascension sayings in Acts and Paul","title":"An undated revelation to Paul","source":"2 Corinthians 12:7-9","items":[{"number":null,"reference":"2 Corinthians 12:9","text":"My grace is sufficient for thee: for my strength is made perfect in weakness.","id":"passage-95-1","section_index":94,"contexts":[{"book":"2 Corinthians","chapter":12,"verse":9,"matched":true}]}],"notes":["*Paul does not give enough information to place this saying at a precise point in the Acts chronology. The speaker is called “the Lord”; the surrounding context and traditional Christian reading identify the Lord here as Christ.*"],"era":8},{"major":"B. Post-Ascension sayings in Acts and Paul","title":"The Lord speaks to Paul at Corinth","source":"Acts 18:9-10","items":[{"number":null,"reference":"Acts 18:9-10","text":"Be not afraid, but speak, and hold not thy peace: for I am with thee, and no man shall set on thee to hurt thee: for I have much people in this city.","id":"passage-96-1","section_index":95,"contexts":[{"book":"Acts","chapter":18,"verse":10,"matched":true}]}],"notes":[],"era":8},{"major":"B. Post-Ascension sayings in Acts and Paul","title":"The Lord stands by Paul in Jerusalem","source":"Acts 23:11","items":[{"number":null,"reference":"Acts 23:11","text":"Be of good cheer, Paul: for as thou hast testified of me in Jerusalem, so must thou bear witness also at Rome.","id":"passage-97-1","section_index":96,"contexts":[{"book":"Acts","chapter":23,"verse":11,"matched":true}]}],"notes":["*Revelation contains several speaker-identification questions. The passages below follow the traditional KJV red-letter attribution used for this compilation; sayings clearly assigned to an angel, the Spirit, or another heavenly voice are not silently reassigned to Jesus.*"],"era":8},{"major":"C. Sayings of the risen Christ in Revelation","title":"The risen Christ identifies himself to John","source":"Revelation 1:8, 11, 17-20","items":[{"number":null,"reference":"Revelation 1:8","text":"I am Alpha and Omega, the beginning and the ending, saith the Lord, which is, and which was, and which is to come, the Almighty.","id":"passage-98-1","section_index":97,"contexts":[{"book":"Revelation","chapter":1,"verse":8,"matched":true}]},{"number":null,"reference":"Revelation 1:11","text":"I am Alpha and Omega, the first and the last: and, What thou seest, write in a book, and send it unto the seven churches which are in Asia; unto Ephesus, and unto Smyrna, and unto Pergamos, and unto Thyatira, and unto Sardis, and unto Philadelphia, and unto Laodicea.","id":"passage-98-2","section_index":97,"contexts":[{"book":"Revelation","chapter":1,"verse":11,"matched":true}]},{"number":null,"reference":"Revelation 1:17-20","text":"Fear not; I am the first and the last: I am he that liveth, and was dead; and, behold, I am alive for evermore, Amen; and have the keys of hell and of death. Write the things which thou hast seen, and the things which are, and the things which shall be hereafter; The mystery of the seven stars which thou sawest in my right hand, and the seven golden candlesticks. The seven stars are the angels of the seven churches: and the seven candlesticks which thou sawest are the seven churches.","id":"passage-98-3","section_index":97,"contexts":[{"book":"Revelation","chapter":1,"verse":18,"matched":true}]}],"notes":[],"era":9},{"major":"C. Sayings of the risen Christ in Revelation","title":"To the church at Ephesus","source":"Revelation 2:1-7","items":[{"number":null,"reference":"Revelation 2:1-7","text":"These things saith he that holdeth the seven stars in his right hand, who walketh in the midst of the seven golden candlesticks; I know thy works, and thy labour, and thy patience, and how thou canst not bear them which are evil: and thou hast tried them which say they are apostles, and are not, and hast found them liars: and hast borne, and hast patience, and for my name's sake hast laboured, and hast not fainted. Nevertheless I have somewhat against thee, because thou hast left thy first love. Remember therefore from whence thou art fallen, and repent, and do the first works; or else I will come unto thee quickly, and will remove thy candlestick out of his place, except thou repent. But this thou hast, that thou hatest the deeds of the Nicolaitans, which I also hate. He that hath an ear, let him hear what the Spirit saith unto the churches; To him that overcometh will I give to eat of the tree of life, which is in the midst of the paradise of God.","id":"passage-99-1","section_index":98,"contexts":[{"book":"Revelation","chapter":2,"verse":2,"matched":true}]}],"notes":[],"era":9},{"major":"C. Sayings of the risen Christ in Revelation","title":"To the church at Smyrna","source":"Revelation 2:8-11","items":[{"number":null,"reference":"Revelation 2:8-11","text":"These things saith the first and the last, which was dead, and is alive; I know thy works, and tribulation, and poverty, (but thou art rich) and I know the blasphemy of them which say they are Jews, and are not, but are the synagogue of Satan. Fear none of those things which thou shalt suffer: behold, the devil shall cast some of you into prison, that ye may be tried; and ye shall have tribulation ten days: be thou faithful unto death, and I will give thee a crown of life. He that hath an ear, let him hear what the Spirit saith unto the churches; He that overcometh shall not be hurt of the second death.","id":"passage-100-1","section_index":99,"contexts":[{"book":"Revelation","chapter":2,"verse":9,"matched":true}]}],"notes":[],"era":9},{"major":"C. Sayings of the risen Christ in Revelation","title":"To the church at Pergamos","source":"Revelation 2:12-17","items":[{"number":null,"reference":"Revelation 2:12-17","text":"These things saith he which hath the sharp sword with two edges; I know thy works, and where thou dwellest, even where Satan's seat is: and thou holdest fast my name, and hast not denied my faith, even in those days wherein Antipas was my faithful martyr, who was slain among you, where Satan dwelleth. But I have a few things against thee, because thou hast there them that hold the doctrine of Balaam, who taught Balac to cast a stumblingblock before the children of Israel, to eat things sacrificed unto idols, and to commit fornication. So hast thou also them that hold the doctrine of the Nicolaitans, which thing I hate. Repent; or else I will come unto thee quickly, and will fight against them with the sword of my mouth. He that hath an ear, let him hear what the Spirit saith unto the churches; To him that overcometh will I give to eat of the hidden manna, and will give him a white stone, and in the stone a new name written, which no man knoweth saving he that receiveth it.","id":"passage-101-1","section_index":100,"contexts":[{"book":"Revelation","chapter":2,"verse":13,"matched":true}]}],"notes":[],"era":9},{"major":"C. Sayings of the risen Christ in Revelation","title":"To the church at Thyatira","source":"Revelation 2:18-29","items":[{"number":null,"reference":"Revelation 2:18-29","text":"These things saith the Son of God, who hath his eyes like unto a flame of fire, and his feet are like fine brass; I know thy works, and charity, and service, and faith, and thy patience, and thy works; and the last to be more than the first. Notwithstanding I have a few things against thee, because thou sufferest that woman Jezebel, which calleth herself a prophetess, to teach and to seduce my servants to commit fornication, and to eat things sacrificed unto idols. And I gave her space to repent of her fornication; and she repented not. Behold, I will cast her into a bed, and them that commit adultery with her into great tribulation, except they repent of their deeds. And I will kill her children with death; and all the churches shall know that I am he which searcheth the reins and hearts: and I will give unto every one of you according to your works. But unto you I say, and unto the rest in Thyatira, as many as have not this doctrine, and which have not known the depths of Satan, as they speak; I will put upon you none other burden. But that which ye have already hold fast till I come. And he that overcometh, and keepeth my works unto the end, to him will I give power over the nations: and he shall rule them with a rod of iron; as the vessels of a potter shall they be broken to shivers: even as I received of my Father. And I will give him the morning star. He that hath an ear, let him hear what the Spirit saith unto the churches.","id":"passage-102-1","section_index":101,"contexts":[{"book":"Revelation","chapter":2,"verse":19,"matched":true}]}],"notes":[],"era":9},{"major":"C. Sayings of the risen Christ in Revelation","title":"To the church at Sardis","source":"Revelation 3:1-6","items":[{"number":null,"reference":"Revelation 3:1-6","text":"These things saith he that hath the seven Spirits of God, and the seven stars; I know thy works, that thou hast a name that thou livest, and art dead. Be watchful, and strengthen the things which remain, that are ready to die: for I have not found thy works perfect before God. Remember therefore how thou hast received and heard, and hold fast, and repent. If therefore thou shalt not watch, I will come on thee as a thief, and thou shalt not know what hour I will come upon thee. Thou hast a few names even in Sardis which have not defiled their garments; and they shall walk with me in white: for they are worthy. He that overcometh, the same shall be clothed in white raiment; and I will not blot out his name out of the book of life, but I will confess his name before my Father, and before his angels. He that hath an ear, let him hear what the Spirit saith unto the churches.","id":"passage-103-1","section_index":102,"contexts":[{"book":"Revelation","chapter":3,"verse":2,"matched":true}]}],"notes":[],"era":9},{"major":"C. Sayings of the risen Christ in Revelation","title":"To the church at Philadelphia","source":"Revelation 3:7-13","items":[{"number":null,"reference":"Revelation 3:7-13","text":"These things saith he that is holy, he that is true, he that hath the key of David, he that openeth, and no man shutteth; and shutteth, and no man openeth; I know thy works: behold, I have set before thee an open door, and no man can shut it: for thou hast a little strength, and hast kept my word, and hast not denied my name. Behold, I will make them of the synagogue of Satan, which say they are Jews, and are not, but do lie; behold, I will make them to come and worship before thy feet, and to know that I have loved thee. Because thou hast kept the word of my patience, I also will keep thee from the hour of temptation, which shall come upon all the world, to try them that dwell upon the earth. Behold, I come quickly: hold that fast which thou hast, that no man take thy crown. Him that overcometh will I make a pillar in the temple of my God, and he shall go no more out: and I will write upon him the name of my God, and the name of the city of my God, which is new Jerusalem, which cometh down out of heaven from my God: and I will write upon him my new name. He that hath an ear, let him hear what the Spirit saith unto the churches.","id":"passage-104-1","section_index":103,"contexts":[{"book":"Revelation","chapter":3,"verse":6,"matched":true}]}],"notes":[],"era":9},{"major":"C. Sayings of the risen Christ in Revelation","title":"To the church at Laodicea","source":"Revelation 3:14-22","items":[{"number":null,"reference":"Revelation 3:14-22","text":"These things saith the Amen, the faithful and true witness, the beginning of the creation of God; I know thy works, that thou art neither cold nor hot: I would thou wert cold or hot. So then because thou art lukewarm, and neither cold nor hot, I will spue thee out of my mouth. Because thou sayest, I am rich, and increased with goods, and have need of nothing; and knowest not that thou art wretched, and miserable, and poor, and blind, and naked: I counsel thee to buy of me gold tried in the fire, that thou mayest be rich; and white raiment, that thou mayest be clothed, and that the shame of thy nakedness do not appear; and anoint thine eyes with eyesalve, that thou mayest see. As many as I love, I rebuke and chasten: be zealous therefore, and repent. Behold, I stand at the door, and knock: if any man hear my voice, and open the door, I will come in to him, and will sup with him, and he with me. To him that overcometh will I grant to sit with me in my throne, even as I also overcame, and am set down with my Father in his throne. He that hath an ear, let him hear what the Spirit saith unto the churches.","id":"passage-105-1","section_index":104,"contexts":[{"book":"Revelation","chapter":3,"verse":6,"matched":true}]}],"notes":[],"era":9},{"major":"C. Sayings of the risen Christ in Revelation","title":"A warning during the bowls","source":"Revelation 16:15","items":[{"number":null,"reference":"Revelation 16:15","text":"Behold, I come as a thief. Blessed is he that watcheth, and keepeth his garments, lest he walk naked, and they see his shame.","id":"passage-106-1","section_index":105,"contexts":[{"book":"Revelation","chapter":16,"verse":15,"matched":true}]}],"notes":[],"era":9},{"major":"C. Sayings of the risen Christ in Revelation","title":"The one seated on the throne speaks","source":"Revelation 21:5-8","items":[{"number":null,"reference":"Revelation 21:5","text":"Behold, I make all things new.","id":"passage-107-1","section_index":106,"contexts":[{"book":"Revelation","chapter":21,"verse":5,"matched":true}]},{"number":null,"reference":"Revelation 21:6-8","text":"It is done. I am Alpha and Omega, the beginning and the end. I will give unto him that is athirst of the fountain of the water of life freely. He that overcometh shall inherit all things; and I will be his God, and he shall be my son. But the fearful, and unbelieving, and the abominable, and murderers, and whoremongers, and sorcerers, and idolaters, and all liars, shall have their part in the lake which burneth with fire and brimstone: which is the second death.","id":"passage-107-2","section_index":106,"contexts":[{"book":"Revelation","chapter":21,"verse":7,"matched":true}]}],"notes":[],"era":9},{"major":"C. Sayings of the risen Christ in Revelation","title":"The closing sayings of Revelation","source":"Revelation 22:7, 12-13, 16, 20","items":[{"number":null,"reference":"Revelation 22:7","text":"Behold, I come quickly: blessed is he that keepeth the sayings of the prophecy of this book.","id":"passage-108-1","section_index":107,"contexts":[{"book":"Revelation","chapter":22,"verse":7,"matched":true}]},{"number":null,"reference":"Revelation 22:12-13","text":"And, behold, I come quickly; and my reward is with me, to give every man according as his work shall be. I am Alpha and Omega, the beginning and the end, the first and the last.","id":"passage-108-2","section_index":107,"contexts":[{"book":"Revelation","chapter":22,"verse":12,"matched":true}]},{"number":null,"reference":"Revelation 22:16","text":"I Jesus have sent mine angel to testify unto you these things in the churches. I am the root and the offspring of David, and the bright and morning star.","id":"passage-108-3","section_index":107,"contexts":[{"book":"Revelation","chapter":22,"verse":16,"matched":true}]},{"number":null,"reference":"Revelation 22:20","text":"Surely I come quickly.","id":"passage-108-4","section_index":107,"contexts":[{"book":"Revelation","chapter":22,"verse":20,"matched":true}]}],"notes":["These are not ordinary red-letter narrative scenes and Scripture does not give them a datable place in Jesus’ earthly chronology. Hebrews quotes Old Testament language and explicitly presents Christ as the speaker, so they are included here rather than omitted."],"era":9},{"major":"D. Words placed on Christ’s lips in Hebrews (undated)","title":"Words placed on Christ’s lips in Hebrews — chronology not assigned","source":"Hebrews 2:12-13; Hebrews 10:5-7, 9","items":[{"number":null,"reference":"Hebrews 2:12","text":"I will declare thy name unto my brethren, in the midst of the church will I sing praise unto thee.","id":"passage-108-5","section_index":108,"contexts":[{"book":"Hebrews","chapter":2,"verse":12,"matched":true}]},{"number":null,"reference":"Hebrews 2:13","text":"I will put my trust in him.","id":"passage-108-6","section_index":108,"contexts":[{"book":"Hebrews","chapter":2,"verse":13,"matched":true}]},{"number":null,"reference":"Hebrews 2:13","text":"Behold I and the children which God hath given me.","id":"passage-108-7","section_index":108,"contexts":[{"book":"Hebrews","chapter":2,"verse":13,"matched":true}]},{"number":null,"reference":"Hebrews 10:5-7","text":"Sacrifice and offering thou wouldest not, but a body hast thou prepared me: In burnt offerings and sacrifices for sin thou hast had no pleasure. Then said I, Lo, I come (in the volume of the book it is written of me,) to do thy will, O God.","id":"passage-108-8","section_index":108,"contexts":[{"book":"Hebrews","chapter":10,"verse":6,"matched":true}]},{"number":null,"reference":"Hebrews 10:9","text":"Lo, I come to do thy will, O God.","id":"passage-108-9","section_index":108,"contexts":[{"book":"Hebrews","chapter":10,"verse":9,"matched":true}]}],"notes":["These quotations are placed on Christ’s lips by the writer of Hebrews, but the epistle does not assign them to a narrated point in Jesus’ earthly chronology."],"era":10}],"total_numbered":447,"total_entries":486,"eras":["Childhood and preparation","Early ministry","Galilee and teaching","Journey toward Jerusalem","Jerusalem and final week","Last Supper and farewell","Arrest and crucifixion","Resurrection and ascension","Other New Testament settings","Revelation","Hebrews: literary quotations"],"versions":{"KJV":"King James Version (1769)","BSB":"Berean Standard Bible","ASV":"American Standard Version (1901)","YLT":"Young’s Literal Translation (1898)"}};
